insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(2224, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 75 ans a des douleurs osseuses diffuses depuis plusieurs mois. Ces douleurs siègent aux hanches et irradient dans les cuisses ; il existe également des dorsalgies, des lombalgies et une faiblesse musculaire. La malade vit dans un hospice, elle n''a pas d''autre antécédent qu''une diarrhée chronique . A l''examen, l''état général est bon. Il existe une douleur à la palpation des pièces osseuses superficielles; sans tumeur décelable. L''examen articulaire est normal ainsi que le reste de l''examen somatique. Les radiographies montrent une déminéralisation squelettique diffuse avec tassements de D7, D9, et D11. La VS est à 1Omm a la 1ère heure, la NFS révèle seulement une anémie normochrome normocytaire arégénérative à 10 g d''hémoglobine/100 ml. Le bilan phosphocalcique est le suivant : - Calcémie : 2,03 mmol/l (81 mg/l) - Calciurie : 0,5 mmol/24 h (20 mg/24 h) - Phosphorémie : 0,61 mmol/24 h (21 mg/l) - Phosphatases alcalines : 360 UI (N 200) - Hydroxyprolinurie : 160 micromol/24 h (N 270). Pour confirmer le diagnostic, on réalise une ponction biopsie de la crête iliaque et on complète le bilan radiographique et biologique.', false, true, 'Parmi les résultats d''examens biologiques suivants, le(s)quel(s) est (sont) compatible(s) avec l''observation de cette malade ?', '[{"l":"A","t":"Effondrement du taux de PTH","c":false},{"l":"B","t":"Augmentation du taux plasmatique de 1 - 25 (OH)2 D3","c":false},{"l":"C","t":"Diminution du taux plasmatique de 25 (OH) D3","c":true},{"l":"D","t":"Augmentation de la clairance du phosphore","c":true},{"l":"E","t":"Diminution du taux de l''AMPc néphrogénique","c":false}]'::jsonb, 'L''hypocalcémie secondaire à l''hypovitaminose D est responsable d''un hyperparathyroïdisme secondaire, avec augmentation de l''AMP cyclique urinaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2225, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 75 ans a des douleurs osseuses diffuses depuis plusieurs mois. Ces douleurs siègent aux hanches et irradient dans les cuisses ; il existe également des dorsalgies, des lombalgies et une faiblesse musculaire. La malade vit dans un hospice, elle n''a pas d''autre antécédent qu''une diarrhée chronique . A l''examen, l''état général est bon. Il existe une douleur à la palpation des pièces osseuses superficielles; sans tumeur décelable. L''examen articulaire est normal ainsi que le reste de l''examen somatique. Les radiographies montrent une déminéralisation squelettique diffuse avec tassements de D7, D9, et D11. La VS est à 1Omm a la 1ère heure, la NFS révèle seulement une anémie normochrome normocytaire arégénérative à 10 g d''hémoglobine/100 ml. Le bilan phosphocalcique est le suivant : - Calcémie : 2,03 mmol/l (81 mg/l) - Calciurie : 0,5 mmol/24 h (20 mg/24 h) - Phosphorémie : 0,61 mmol/24 h (21 mg/l) - Phosphatases alcalines : 360 UI (N 200) - Hydroxyprolinurie : 160 micromol/24 h (N 270). Pour confirmer le diagnostic, on réalise une ponction biopsie de la crête iliaque et on complète le bilan radiographique et biologique.', false, true, 'Chez cette malade, quelle(s) peu(ven)t être la (les) cause(s) de l''ostéomalacie ?', '[{"l":"A","t":"Diabète phosphate en rapport avec une tumeur mésenchymateuse","c":false},{"l":"B","t":"Diabète phosphate en rapport avec un myélome","c":false},{"l":"C","t":"Ostéomalacie par carence d''apport en vitamine D","c":true},{"l":"D","t":"Syndrome de malabsorption","c":true},{"l":"E","t":"Hyperthyroïdie","c":false}]'::jsonb, 'Il s''agit d''un sujet âgé qui vit dans un hospice et qui s''expose certainement peu au soleil, avec une diarrhée chronique et une anémie probablement carentielle qui signe la malabsorption.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2226, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 75 ans a des douleurs osseuses diffuses depuis plusieurs mois. Ces douleurs siègent aux hanches et irradient dans les cuisses ; il existe également des dorsalgies, des lombalgies et une faiblesse musculaire. La malade vit dans un hospice, elle n''a pas d''autre antécédent qu''une diarrhée chronique . A l''examen, l''état général est bon. Il existe une douleur à la palpation des pièces osseuses superficielles; sans tumeur décelable. L''examen articulaire est normal ainsi que le reste de l''examen somatique. Les radiographies montrent une déminéralisation squelettique diffuse avec tassements de D7, D9, et D11. La VS est à 1Omm a la 1ère heure, la NFS révèle seulement une anémie normochrome normocytaire arégénérative à 10 g d''hémoglobine/100 ml. Le bilan phosphocalcique est le suivant : - Calcémie : 2,03 mmol/l (81 mg/l) - Calciurie : 0,5 mmol/24 h (20 mg/24 h) - Phosphorémie : 0,61 mmol/24 h (21 mg/l) - Phosphatases alcalines : 360 UI (N 200) - Hydroxyprolinurie : 160 micromol/24 h (N 270). Pour confirmer le diagnostic, on réalise une ponction biopsie de la crête iliaque et on complète le bilan radiographique et biologique.', false, true, 'Chez cette malade, la cause de cette ostéomalacie peut être précisée par le(s) résultat(s) suivant(s) :', '[{"l":"A","t":"Anémie normochrome hormocytaire","c":false},{"l":"B","t":"Abaissement de l''AMP cyclique urinaire","c":false},{"l":"C","t":"Elévation de la clairance de l''anti-trypsine","c":false},{"l":"D","t":"Découverte d''une stéatorrhée supérieure à 5 g/24 h","c":true},{"l":"E","t":"Diminution de l''élimination urinaire du D-xylose","c":true}]'::jsonb, 'Ces deux éléments confirment le diagnostic de malabsorption intestinale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2227, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 75 ans a des douleurs osseuses diffuses depuis plusieurs mois. Ces douleurs siègent aux hanches et irradient dans les cuisses ; il existe également des dorsalgies, des lombalgies et une faiblesse musculaire. La malade vit dans un hospice, elle n''a pas d''autre antécédent qu''une diarrhée chronique . A l''examen, l''état général est bon. Il existe une douleur à la palpation des pièces osseuses superficielles; sans tumeur décelable. L''examen articulaire est normal ainsi que le reste de l''examen somatique. Les radiographies montrent une déminéralisation squelettique diffuse avec tassements de D7, D9, et D11. La VS est à 1Omm a la 1ère heure, la NFS révèle seulement une anémie normochrome normocytaire arégénérative à 10 g d''hémoglobine/100 ml. Le bilan phosphocalcique est le suivant : - Calcémie : 2,03 mmol/l (81 mg/l) - Calciurie : 0,5 mmol/24 h (20 mg/24 h) - Phosphorémie : 0,61 mmol/24 h (21 mg/l) - Phosphatases alcalines : 360 UI (N 200) - Hydroxyprolinurie : 160 micromol/24 h (N 270). Pour confirmer le diagnostic, on réalise une ponction biopsie de la crête iliaque et on complète le bilan radiographique et biologique.', false, true, 'Quel médicament allez-vous prescrire à cette malade pour la guérir de son ostéomalacie ?', '[{"l":"A","t":"Vitamine D2","c":true},{"l":"B","t":"Anabolisants de synthèse","c":false},{"l":"C","t":"Diphosphonates","c":false},{"l":"D","t":"Calcitonine","c":false},{"l":"E","t":"Fluorure de sodium","c":false}]'::jsonb, 'Les ostéomalacies par défaut d''absorption peuvent être traitées par le Stérogyl® ou le Dédrogyl®, avec des doses importantes au début, en association avec du calcium.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2228, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Parmi les hypothèses diagnostiques suivantes, désignez celle(s) qui, étant la(les) plus plausible(s), doi(ven)t être examinée(s) en premier :', '[{"l":"A","t":"Rhumatisme inflammatoire à début mono-articulaire aigu","c":true},{"l":"B","t":"Crise de goutte du genou","c":false},{"l":"C","t":"Arthrite infectieuse","c":true},{"l":"D","t":"Poussée inflammatoire sur arthrose","c":false},{"l":"E","t":"Bursite pré-rotulienne","c":false}]'::jsonb, 'Ces deux diagnostics sont plausibles et il faut toujours évoquer une origine infectieuse devant une monoarthrite fébrile, en raison des conséquences pronostiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2229, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Parmi les gestes cliniques utiles pour parvenir au diagnostic étiologique, choisissez dans la liste suivante les deux plus utiles au diagnostic :', '[{"l":"A","t":"Interrogatoire approfondi sur les antécédents pathologiques récents","c":true},{"l":"B","t":"Interrogatoire approfondi sur les antécédents pathologiques lointains","c":false},{"l":"C","t":"Examen attentif de la totalité des téguments","c":true},{"l":"D","t":"Examen attentif du coeur","c":false},{"l":"E","t":"Examen attentif des aires ganglionnaires","c":false}]'::jsonb, 'La grille est discutable car outre une arthrite à pyogène ou à gonocoque, on peut parfaitement évoquer une arthrite réactionnelle devant ce tableau et dans ce cas, il peut être intéressant de rechercher la notion d''une infection à chlamydia dans les antécédents lointains.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2230, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Quel examen radiographique souhaitez-vous faire faire en priorité ?', '[{"l":"A","t":"Genou droit : face. profil, interligne fémoro-patellaire en incidence axiale à 30°, 45° et 60° de flexion","c":false},{"l":"B","t":"Les deux genoux, face et profil","c":true},{"l":"C","t":"Le bassin de face","c":false},{"l":"D","t":"Le thorax, face etprofil","c":false},{"l":"E","t":"Toutes ces radiographies sont nécessaires d''emblée","c":false}]'::jsonb, 'Pour déceler une minime atteinte articulaire, il faut évidemment faire des clichés comparatifs. En dépit de la grille, je me serais intéressé aux sacroiliaques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2231, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Parmi les examens sanguins énumérés ci-dessous, quel est chez cette malade, celui qui vous parait le plus urgent :', '[{"l":"A","t":"Vitesse de sédimentation","c":true},{"l":"B","t":"Uricémie","c":false},{"l":"C","t":"Electrophorèse des protides sériques","c":false},{"l":"D","t":"Réaction de Waaler-Rose et du Latex","c":false},{"l":"E","t":"Recherche des anticorps antinucléaires","c":false}]'::jsonb, 'Une vitesse de sédimentation élevée au-delà de 100 mm à la lère heure est évocatrice d''arthrite réactionnelle.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2232, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Vous ponctionnez l''épanchement pour étudier le liquide articulaire. Dans la liste suivante d''examens, quels sont les deux que vous considérez en première analyse comme les plus rentables pour le diagnostic :', '[{"l":"A","t":"Dosage des protéines","c":false},{"l":"B","t":"Numération et formule des éléments figurés","c":true},{"l":"C","t":"Recherche de cristaux","c":false},{"l":"D","t":"Recherche du facteur rhumatoïde","c":false},{"l":"E","t":"Examen bactériologique","c":true}]'::jsonb, 'Il peut être intéressant de reponctionner cette articulation pour éviter tout risque d''erreur : le germe, s''il est présent, peut être fragile et la cellularité peut augmenter et devenir évocatrice d''arthrite septique (supérieur à 50 000/mm3).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2233, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Vous poussez l''interrogatoire sur les antécédents pathologiques de la malade et de son entourage. Parmi les données suivantes, quelle est celle qui pèserait le plus sur votre orientation diagnostique :', '[{"l":"A","t":"Une angine récente chez la malade","c":false},{"l":"B","t":"Une bronchite récente chez la malade","c":false},{"l":"C","t":"Une diarrhée récente chez la malade","c":false},{"l":"D","t":"Une furonculose chez le mari de la malade","c":false},{"l":"E","t":"Une urétrite récente chez le mari de la malade","c":true}]'::jsonb, 'L''uréthrite peut être à gonocoque, mais aussi et surtout à chlamydia +++ (grattage uréthral).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2234, 21, 'Rhumatologie', 'Arthrite septique', 'Une jeune femme de 26 ans consulte pour l''apparition rapide sur trois jours, sans traumatisme récent, de douleurs et d''impotence du genou droit. L''examen montre que ce genou est chaud et contient un épanchement intra-articulaire tendu assez abondant. La mobilisation est très douloureuse ; on ne peut obtenir l''extension complète, la flexion atteint à peine 60 degrés. La température rectale est a 38°2. La malade est hospitalisée. Au 3ème jour d''hospitalisation, l''état clinique est toujours aussi sévère. L''interrogatoire n''a fourni aucune piste étiologique. L''examen du liquide synovial a donné les résultats suivants : protéines = 40g/l, éléments figurés = 38000/mm3, formule : polynucléaires 92 %, cellules mononuclées 8 %. Waaler- Rose et latex négatifs, pas de germes à l''examen direct, culture sur milieux ordinaires stérile, pas de cristaux, soit intra-, soit extra-cellulaires.', false, true, 'Quelle attitude choisissez-vous à titre provisoire au soir du 3ème jour d''hospitalisation ?', '[{"l":"A","t":"Traitement anti inflammatoire non stéroïdien par voie intramusculaire","c":false},{"l":"B","t":"Traitement antibiotique à spectre large par voie orale","c":false},{"l":"C","t":"Traitement par la pénicilline G par voie veineuse","c":true},{"l":"D","t":"Injection intra-articulaire de corticoïdes en suspension microcristalline","c":false},{"l":"E","t":"Synoviorthèse à l''acide osmique","c":false}]'::jsonb, 'Dans l''hypothèse provisoire d''une arthrite gonococcique, il faut mettre en route un traitement par pénicilline G (non actif sur les chlamydia et les arthrites réactionnelles).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2235, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'Quel diagnostic évoquer devant ce tableau clinique ?', '[{"l":"A","t":"Fracture du pilon tibial","c":false},{"l":"B","t":"Luxation sous-astragalienne du pied","c":false},{"l":"C","t":"Fracture du calcanéum","c":true},{"l":"D","t":"Entorse grave tibio-tarsienne","c":false},{"l":"E","t":"Rupture du tendon d''Achille","c":false}]'::jsonb, 'C - Fracture du calcaneum car tableau typique. D''autre part : - c''est le mécanisme (contre E, qui donne par ailleurs un déficit de fléxion plantaire active) - respecte l''articulation tibia astragalienne (contre A et D) B - Peut donner sensiblement le même tableau à la 24e heure, quand l''oedème masque la déformation initiale. Risque d''ischémie du pied si la réduction n''est pas faite en urgence. La radio fait le diagnostic.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2236, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'Quel(s) cliché(s) radiologique(s) de débrouillage demandez-vous en premier ?', '[{"l":"A","t":"Tibio-tarsienne de face","c":true},{"l":"B","t":"Tibio-tarsienne de face en inversion","c":false},{"l":"C","t":"Tibio-tarsienne de face en éversion","c":false},{"l":"D","t":"Tibio-tarsienne et pied de profil","c":true},{"l":"E","t":"Incidence rétro-tibiale","c":true}]'::jsonb, 'A. D : -vérifient l''intégrité de la t biotarsienne. La fracture du calcaneum est au mieux débrouillée sur les clichés de pied de profil (interligne astragalo calcanéen) et sur l''incidence rétrotibiale permettant à eux deux le diagnostic des fractures thalamiques (articulaires) et l''analyse de leur déplacement (séparation ± tassement, vertical ou horizontal)', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2237, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'En ce qui concerne le calcanéum, que pouvez-vous analyser sur le cliché de profil, si vous soupçonnez une fracture ?', '[{"l":"A","t":"La grande apophyse","c":true},{"l":"B","t":"La petite apophys","c":false},{"l":"C","t":"Le thalamus","c":true},{"l":"D","t":"La tubérosité postérieure","c":true},{"l":"E","t":"La corticale inférieure","c":true}]'::jsonb, 'La petite apophyse porte la surface articulaire antéro interne avec l''astragale. C''est le sustentaculum tali le mieux visualisé sur l''incidence rétrotibiale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2238, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'A propos de l''angle de Bohler, il est exact que :', '[{"l":"A","t":"Sa valeur normale est de 40 degrès","c":true},{"l":"B","t":"Cette valeur diminue dans les enfoncements thalamiques","c":true},{"l":"C","t":"Cette valeur ne diminue que dans les enfoncements thalamiques horizontaux","c":false},{"l":"D","t":"Sa valeur diminue dans les fractures en bec de canard de la tubérosité","c":true},{"l":"E","t":"Sa valeur augmente dans les enfoncements thalamiques verticaux","c":false}]'::jsonb, 'A - L''angle de Boehler est délimité par deux droites, une tangente menée du bord supérieur de la grosse tubérosité au bord supérieur de la surface thalamique, et une tangente de ce même point au point le plus élevé du bec de la grande apophyse. Il forme un angle ouvert en arrière de 25 à 40 degrés. B - Horizontalise la deuxième droite sans distinction du type de l''enfoncement (vertical ou horizontal) d''où C. E faux. D - Relève la première droite d''où angle diminue aussi.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2239, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'La radiographie de profil de notre accidenté met en évidence : un angle de Bohler à 0 degrè, un éclat est soulevé à la faveur d''un trait de fracture sous-thalamique allant du sinus au tarse à la tubérosité postérieure du calcénéum. La corticale inférieure de l''os n''est pas fracturée. Vous pouvez en déduire une ou plusieurs des propositions suivantes :', '[{"l":"A","t":"Fracture isolée de la tubérosité postérieure","c":false},{"l":"B","t":"Fracture thalamique avec enfoncement vertical","c":true},{"l":"C","t":"Fracture à deux fragments","c":false},{"l":"D","t":"Fracture à trois fragments","c":true},{"l":"E","t":"La petite apophyse est fracturée","c":true}]'::jsonb, 'A - Est faux car le trait passe dans le sinus du tarse. D - les 3 fragments sont : - antéro interne emportant le sustentaculum talium (1) - postéro externe dans lequel va se produire l''enfoncement isolant un nouveau fragment Le fragment thalamo-cortical (2) enfoncé réalise le soufflet postérieur, le fragment postéro externe (3) comportant la corticale plantaire intacte.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2240, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'Les traits de fracture, séparation pré ou transthalamiques, ne sont bien visibles que sur certains clichés. Le(s)quel(s) ?', '[{"l":"A","t":"Le cliché de face de l''arrière-pied","c":false},{"l":"B","t":"Le cliché en incidence plantaire rétro-tibiale","c":true},{"l":"C","t":"Le cliché de profil","c":false},{"l":"D","t":"Les tomographies frontales du calcanéum","c":true},{"l":"E","t":"Les tomographies sagittales du calcanéum","c":false}]'::jsonb, 'En effet les traits de séparation pré et transthalamiques sont para-sagittaux donc visualisés dans un plan perpendiculaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2241, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un couvreur de 35 ans est tombé de 6 mètres de haut sur ses pieds. Il souffre de son arrière-pied gauche mais peut marcher à petits pas. Lorsque vous le voyez le lendemain, tout l''arrière-pied est tuméfié. Au palper, son talon vous semble élargi et la palpation en est sensible. La mobilisation de la tibio-tarsienne est possible mais les amplitudes extrêmes sont douloureuses. La recherche des mouvements d''inversion et d''éversion du pied est très douloureuse.', false, true, 'Les fractures du calcanéum exposent à une ou plusieurs des complications suivantes. Laquelle(lesquelles) ?', '[{"l":"A","t":"Une pseudarthrose","c":false},{"l":"B","t":"Un cal vicieux","c":true},{"l":"C","t":"Une nécrose du calcanéum","c":false},{"l":"D","t":"Un enraidissement douloureux de la sous astragalienne","c":true},{"l":"E","t":"Une tendinite des péroniers","c":true}]'::jsonb, 'A - Rare : la consolidation est constante. B - Est la principale complication, sa gravité est liée à son siège thalamique articulaire. D - Par arthrose (sur cal vicieux ou par les lésions cartilagineuses fréquentes). E - En fait, il s''agit le plus souvent d''une atteinte des péroniers, qui longent la face externe de la grosse tubérosité en se réfléchissant sous le tubercule des péroniers.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2242, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'Votre diagnostic s''oriente vers :', '[{"l":"A","t":"Une polyarthrite rhumatoïde","c":false},{"l":"B","t":"Une syphilis","c":false},{"l":"C","t":"Un lupus","c":true},{"l":"D","t":"Une maladie périodique","c":false},{"l":"E","t":"Aucune de ces affections","c":false}]'::jsonb, 'En effet il s''agit d''une femme jeune avec une arthrite récente non destructrice avec malgré tout une sérologie très élevée (après une très courte évolution). En faveur du lupus, on retrouvé une leucopénie, un complément abaissé et un BW positif pouvant témoigner de la présence d''anticorps anticardiolipides.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2243, 24, 'Rhumatologie', 'Traumatismes vertébraux-médullaires', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'Vous complétez le bilan par :', '[{"l":"A","t":"Un test de Nelson","c":false},{"l":"B","t":"Un test de Farr","c":true},{"l":"C","t":"Une biopsie cutanée","c":true},{"l":"D","t":"Une ponction-biopsie rénale","c":false},{"l":"E","t":"Une radiographie de la charnière cervico-occipitale","c":false}]'::jsonb, 'La biopsie rénale se discute si le test de Farr et la biopsie cutanée font le diagnostic de lupus. Beaucoup, en effet, considèrent qu''elle n''est pas indispensable en l''absence d''atteinte rénale biologique ; néanmoins la maladie semble ici très évolutive et elle peut permettre d''orienter le traitement.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2244, 28, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'Le liquide de ponction peut vous montrer :', '[{"l":"A","t":"500 éléments par mm3","c":false},{"l":"B","t":"4500 éléments par mm3","c":true},{"l":"C","t":"Des cristaux de pyrophosphate de calcium","c":false},{"l":"D","t":"Un liquide hémorragique","c":false},{"l":"E","t":"Un liquide très visqueux","c":false}]'::jsonb, 'Il s''agira d''un liquide inflammatoire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2245, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'Votre préférence ira au traitement suivant :', '[{"l":"A","t":"Sels d''Or","c":false},{"l":"B","t":"Pénicilline","c":false},{"l":"C","t":"D-Penicillamine","c":false},{"l":"D","t":"Antimalariques de synthèse","c":true},{"l":"E","t":"Immunodépresseurs","c":false}]'::jsonb, 'Si la maladie lupique ne touche pas le rein (ou un autre organe), les antimalariques peuvent suffire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2246, 24, 'Rhumatologie', 'Traumatismes vertébraux-médullaires', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'Vous rechercherez une(des) complication(s) éventuelle(s) :', '[{"l":"A","t":"Luxation de la charnière cervico-occipitale","c":false},{"l":"B","t":"Troubles psychiques","c":true},{"l":"C","t":"Atteinte rénale","c":true},{"l":"D","t":"Glaucome","c":false},{"l":"E","t":"Nodules sur la face postérieure des coudes","c":false}]'::jsonb, 'L''atteinte neurologique est possible et l''atteinte rénale à une grande valeur pronostique et peut faire poser l''indication d''un traitement immunosuppresseur.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2247, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Une femme de 35 ans consulte pour une synovite inflammatoire des 2 poignets et des 2 genoux d''apparition récente. Il n''y a aucun antécédent particulier, la malade ne signale ni angine ni trouble intestinal. L''examen clinique met en évidence une raideur des deux poignets, un léger épanchement des genoux avec épaississement de la synoviale. On ne constate aucune éruption cutanée. Les radiographies des articulations inflammatoires révèlent seulement un gonflement des parties molles aux poignets. Les examens biologiques montrent : - V.S. = 35 - 78 - NFS : 4 350 000 GR, 2 800 GB, Hby 12,3 g, 63 % PN - 1 % E - 0 % b - 22 % L - 14 % M - Test au latex : 1/160ème ; Waaler Rose : 1/128 ; B.W.positif - complément total : 32 u. (N 50 ± 10) - examen cytobactériologique des urines : négatif.', false, true, 'La malade désire une grossesse et vous demande conseil :', '[{"l":"A","t":"Vous pensez qu''elle risque d''aggraver la maladie","c":true},{"l":"B","t":"Vous estimez qu''elle sera bénéfique sur les poussées inflammatoires articulaires","c":false},{"l":"C","t":"Il y a un risque non négligeable d''avortement spontané","c":true},{"l":"D","t":"Vous conseillez d''attendre une stabilisation de la maladie pendant au moins un an","c":true},{"l":"E","t":"Aucun conseil particulier n''est à donner à cette malade","c":false}]'::jsonb, 'Le lupus peut être aggravé par la grossesse (il existe des poussées évolutives au 3e trimestre) et il peut être responsable d''un avortement spontané ou d''une mort in utéro.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2248, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', 'Un ouvrier du bâtiment, à la suite d''une chute d''un lieu élevé, est tombé sur une verrière. Outre un traumatisme crânien, il présente une plaie à la face externe du genou.', false, true, 'La lésion du nerf sciatique poplité externe est suspectée devant :', '[{"l":"A","t":"Une paralysie du triceps sural","c":false},{"l":"B","t":"Une paralysie du jambier antérieur","c":true},{"l":"C","t":"Une paralysie des extenseurs des orteils","c":true},{"l":"D","t":"Une anesthésie du dos du pied","c":true},{"l":"E","t":"Une anesthésie de la plante du pied","c":false}]'::jsonb, 'Le nerf sciatique poplite externe est sensitivo-moteur : moteur pour la loge antéro externe de jambe : paralysie du jambier antérieur (imposs bilité de fléxion dorsale du pied), paralysie de l''extenseur commun des orteils, paralysie de l''extenseur propre du gros orteil, paralysie des péroniers latéraux : (imposs bilité d''éversion du pied : fléxion dorsale, pronation, abduction) - Sensitif pour la face antéro externe de jambe, le dos du pied (sauf le bord externe), la face dorsale de Pl et P2 des 2e, 3e, 4e, 5e orteils, la face dorsale de Pl du gros orteil. E - Nerf sciatique poplité interne (SPI). A - Nerf tibial postérieur, branche du nerf saphène externe issu du SPI.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2249, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un ouvrier du bâtiment, à la suite d''une chute d''un lieu élevé, est tombé sur une verrière. Outre un traumatisme crânien, il présente une plaie à la face externe du genou.', false, true, 'La section du nerf sciatique poplité externe est accompagnée de lésions des parties molles. Indiquez sur quel(s) élément(s) vous faites le diagnostic d''ouverture articulaire :', '[{"l":"A","t":"L''existence d''une large plaie cutanée","c":false},{"l":"B","t":"Une image hydroaérique intra-articulaire à la radiographie standard","c":true},{"l":"C","t":"La ponction du genou","c":false},{"l":"D","t":"Une fracture des épines tibiales","c":false},{"l":"E","t":"L''exploration chirurgicale","c":true}]'::jsonb, 'A - Toute plaie en regard d''une articulation est considérée comme articulaire jusqu''à preuve du contraire. Ici le siège de la plaie cutanée est suspect ; il faut affirmer le diagnostic de plaie articulaire. B - La présence d''air (et le niveau) signe l''effraction capsulaire. C. D - En faveur d''une hémarthrose, sans lien de causalité spécifique avec la plaie articulaire. E - systématique : toute plaie suspecte d''être articulaire doit être explorée et parée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2250, 3, 'Traumatologie', 'Principe de base en médecine physique et réadaptation', 'Un ouvrier du bâtiment, à la suite d''une chute d''un lieu élevé, est tombé sur une verrière. Outre un traumatisme crânien, il présente une plaie à la face externe du genou.', false, true, 'Ce blessé va être opéré en urgence : indiquez l''(es) examen(s) paraclinique(s) que vous demandez :', '[{"l":"A","t":"Groupe sanguin","c":true},{"l":"B","t":"Arthrographie du genou","c":false},{"l":"C","t":"Echographie du creux poplité","c":false},{"l":"D","t":"Electromyogramme","c":false},{"l":"E","t":"Hémoculture","c":false}]'::jsonb, 'BCD - N''ont aucun intérêt en urgence et sont redondants puisque le genou sera exploré en urgence. E - Pas devant une plaie articulaire aussi récente. Le risque de surinfection est plus tardif. A - Fait partie du bilan légal (groupe, rhésus, crase, E.C.G, radio pulmonaire).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2251, 34, 'Traumatologie', 'Lombalgies et lombosciatalgies', 'Un ouvrier du bâtiment, à la suite d''une chute d''un lieu élevé, est tombé sur une verrière. Outre un traumatisme crânien, il présente une plaie à la face externe du genou.', false, true, 'En cas de section complète franche, sans perte de substance du nerf sciatique poplité externe. Indiquez la conduite à envisager :', '[{"l":"A","t":"Une greffe nerveuse sous microscope","c":false},{"l":"B","t":"Une suture directe sous microscope","c":true},{"l":"C","t":"Une suture cutanée avec greffe nerveuse secondaire","c":false},{"l":"D","t":"Une transplantation tendineuse","c":false},{"l":"E","t":"Une arthrodèse de la cheville","c":false}]'::jsonb, 'Evident car la lésion est fraiche (pas de rétraction) franche, sans perte de substance (A : greffe inutile). La suture, sous microscope, épineurale, fasciculaire, donne les meilleurs chances de récupération. Le chirurgien repérera, s''il le peut les faisceaux moteurs et sensitifs pour effectuer les sutures des extrémités homologues. D. E - Traitements palliatifs.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2252, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une jeune femme de 27 ans est enceinte de 7 mois. Depuis 5 mois, elle se plaint de violentes douleurs que l''analyse clinique permet d''identifier comme d''origine sciatique. Ces douleurs l''obligent à s''aliter en permanence. L''examen montre une abolition du réflexe achiléen gauche et 2 nodules mammaires. La gravité est normale. Les deux radiographies (face + profil) de la colonne dorso-lombaire montrent un tassement de L5. Les radiographies du crâne et des mains sont normales, la radiographie pulmonaire également. La calcémie est à 3,25 mmol/l.', false, true, 'Parmi les symptômes et signes suivants, l''hypercalcémie peut être à l''origine de :', '[{"l":"A","t":"Abolition d''un réflexe osteotendineux","c":false},{"l":"B","t":"Polyurie","c":true},{"l":"C","t":"Confusion mentale","c":true},{"l":"D","t":"Raccourcissement de l''espace QT sur l''électrocardiogramme","c":true},{"l":"E","t":"Douleur névralgique","c":false}]'::jsonb, 'Lors des hypercalcémies sévères, il peut y avoir un coma aréflexique et hypotonique mais il n''y a jamais d''abolition d''un réflexe isolé.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2253, 7, 'Rhumatologie', 'Complication de l’immobilité et décubitus', 'Une jeune femme de 27 ans est enceinte de 7 mois. Depuis 5 mois, elle se plaint de violentes douleurs que l''analyse clinique permet d''identifier comme d''origine sciatique. Ces douleurs l''obligent à s''aliter en permanence. L''examen montre une abolition du réflexe achiléen gauche et 2 nodules mammaires. La gravité est normale. Les deux radiographies (face + profil) de la colonne dorso-lombaire montrent un tassement de L5. Les radiographies du crâne et des mains sont normales, la radiographie pulmonaire également. La calcémie est à 3,25 mmol/l.', false, true, 'Quelle(s) étiologie(s) possible(s) de l''hypercalcémie retenez-vous chez cette malade ?', '[{"l":"A","t":"Etat gravidique","c":false},{"l":"B","t":"Métastase osseuse d''un néoplasme","c":true},{"l":"C","t":"Immobilisation prolongée","c":false},{"l":"D","t":"Acromégalie","c":false},{"l":"E","t":"Sarcoïdose","c":false}]'::jsonb, 'On peut évoquer une poussée évolutive d''une néoplasie mammaire au cours de la grosse en raison des deux nodules palpés.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2254, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une jeune femme de 27 ans est enceinte de 7 mois. Depuis 5 mois, elle se plaint de violentes douleurs que l''analyse clinique permet d''identifier comme d''origine sciatique. Ces douleurs l''obligent à s''aliter en permanence. L''examen montre une abolition du réflexe achiléen gauche et 2 nodules mammaires. La gravité est normale. Les deux radiographies (face + profil) de la colonne dorso-lombaire montrent un tassement de L5. Les radiographies du crâne et des mains sont normales, la radiographie pulmonaire également. La calcémie est à 3,25 mmol/l.', false, true, 'Quelle(s) mesure(s) thérapeutique(s) peu(ven)t être envisagée(s) pour traiter l''hypercalcémie ? (sans tenir compte de la grossesse)', '[{"l":"A","t":"Diurèse forcée induite par le furosémide + chlorure de sodium","c":true},{"l":"B","t":"Diurèse forcée induite par les thiazidiques + chlorure de sodium","c":false},{"l":"C","t":"Administration de thyrocalcitonine","c":true},{"l":"D","t":"Corticothérapie. prednisone 100 mg/kg/jour","c":false},{"l":"E","t":"Résine échangeuse d''ions type Kayexalate®","c":false}]'::jsonb, 'Il s''agit d''une hypercalcémie majeure qui ne pourra être contrôlée que par une hyperdiurèse au furosémide, compensée volume à volume par une solution de sérum physiologique. La thyrocalcitonine, par son action antiostéoclastique, peut être un appoint thérapeutique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2255, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une jeune femme de 27 ans est enceinte de 7 mois. Depuis 5 mois, elle se plaint de violentes douleurs que l''analyse clinique permet d''identifier comme d''origine sciatique. Ces douleurs l''obligent à s''aliter en permanence. L''examen montre une abolition du réflexe achiléen gauche et 2 nodules mammaires. La gravité est normale. Les deux radiographies (face + profil) de la colonne dorso-lombaire montrent un tassement de L5. Les radiographies du crâne et des mains sont normales, la radiographie pulmonaire également. La calcémie est à 3,25 mmol/l.', false, true, 'Comment s''expliquent les hypercalcémies associées à des cancers ?', '[{"l":"A","t":"Synthèse d''un facteur activant l''ostéoclastose","c":true},{"l":"B","t":"Production de protides inhibant la parathormone","c":false},{"l":"C","t":"Destruction osseuse par les métastases","c":true},{"l":"D","t":"Production de prostaglandines","c":true},{"l":"E","t":"Synthèse de vitamine D (1-25 OH D3)","c":false}]'::jsonb, 'L''hypercalcémie au cours d''une néoplasie peut s''expliquer par une ostéolyse directe par une métastase, ou par production d''une substance hypercalcémiante ostéolytique : prostaglandine E facteur activant les ostéoclastes, ou peptide analogue ou proche de la P.T.H.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2256, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un sportif de 25 ans a fait une chute sur le moignon de l''épaule il y a six mois. Le patient a été traité par un bandage pendant 8 jours. Il présente des douleurs de l''épaule survenant essentiellement lorsqu''il fait de la gymnastique (barres parallèles et vélo). Ses douleurs sont localisées a la partie supérieure du moignon de l''épaule. Il n''y a pas de douleur au repos et pas de sensation de ressaut, ni d''instabilité. L''examen met en évidence : à l''nspection une saillie osseuse en haut et en arrière au niveau de la partie supérieure du moignon de l''épaule - une mobilité active et passive de l''épaule normale - une douleur provoquée au cours de l''abduction de l''épaule à partir de 90 degrés jusqu''au zénith - la palpation montre une saillie osseuse située en dedans de l''extrémité distale de l''acromion. Cette saillie est mobile de haut en bas et d''avant en arrière.', false, true, 'Les douleurs alléguées évoquent :', '[{"l":"A","t":"Un syndrome inflammatoire","c":false},{"l":"B","t":"Une lésion tumorale","c":false},{"l":"C","t":"Une lésion post-traumatique avec conséquences mécaniques","c":true},{"l":"D","t":"Une lésion dégénérative","c":false},{"l":"E","t":"Une lésion neurologique","c":false}]'::jsonb, 'C - Le tableau est évocateur de luxation acromio-claviculaire stade 3 : - circonstance typique : choc sur moignon de l''épaule - siège de la douleur sur l''articulation acromio claviculaire - déformation typique - arc douloureux - epaule stable - mais mouvements anormaux de l''acromio-claviculaire : touche de piano et tiroir antéro-postérieur. ABDE - Sont inapproprieés car : - douleurs mécaniques - mobilité complète - absence de signe neurologique - terrain.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2257, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un sportif de 25 ans a fait une chute sur le moignon de l''épaule il y a six mois. Le patient a été traité par un bandage pendant 8 jours. Il présente des douleurs de l''épaule survenant essentiellement lorsqu''il fait de la gymnastique (barres parallèles et vélo). Ses douleurs sont localisées a la partie supérieure du moignon de l''épaule. Il n''y a pas de douleur au repos et pas de sensation de ressaut, ni d''instabilité. L''examen met en évidence : à l''nspection une saillie osseuse en haut et en arrière au niveau de la partie supérieure du moignon de l''épaule - une mobilité active et passive de l''épaule normale - une douleur provoquée au cours de l''abduction de l''épaule à partir de 90 degrés jusqu''au zénith - la palpation montre une saillie osseuse située en dedans de l''extrémité distale de l''acromion. Cette saillie est mobile de haut en bas et d''avant en arrière.', false, true, 'La douleur survenant au-delà de 90 degrés d''abduction et jusqu''au zénith évoque :', '[{"l":"A","t":"Une lésion intéressant la clavicule","c":false},{"l":"B","t":"Un syndrome du bourrelet glénoïdien","c":false},{"l":"C","t":"Une tendinite du sus-épineux","c":false},{"l":"D","t":"Un syndrome des arcs douloureux par conflit acromio-huméral","c":true},{"l":"E","t":"Une lésion de l''articulation scapulo-thoracique","c":false}]'::jsonb, 'C''est un signe caractéristique (encore appelé impigemen syndrome).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2258, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un sportif de 25 ans a fait une chute sur le moignon de l''épaule il y a six mois. Le patient a été traité par un bandage pendant 8 jours. Il présente des douleurs de l''épaule survenant essentiellement lorsqu''il fait de la gymnastique (barres parallèles et vélo). Ses douleurs sont localisées a la partie supérieure du moignon de l''épaule. Il n''y a pas de douleur au repos et pas de sensation de ressaut, ni d''instabilité. L''examen met en évidence : à l''nspection une saillie osseuse en haut et en arrière au niveau de la partie supérieure du moignon de l''épaule - une mobilité active et passive de l''épaule normale - une douleur provoquée au cours de l''abduction de l''épaule à partir de 90 degrés jusqu''au zénith - la palpation montre une saillie osseuse située en dedans de l''extrémité distale de l''acromion. Cette saillie est mobile de haut en bas et d''avant en arrière.', false, true, 'La position conseillée pour mettre en évidence la lésion au cours de la radiographie de face sera :', '[{"l":"A","t":"En abduction au-delà de 90 degrés","c":false},{"l":"B","t":"En rotation externe","c":false},{"l":"C","t":"En rotation interne","c":false},{"l":"D","t":"En rétropulsion","c":false},{"l":"E","t":"Avec un poids de quelques kilogrammes dans la main","c":true}]'::jsonb, 'La radiographie en charge (5 kg) montre en cas de luxation acromio claviculaire stade 3 l''écart persistant entre clavicule et acromion, signant la rupture de tous les ligaments acromio- et coraco - claviculaires. Noter que le cliché en abduction est utile, il recherche la réductibilité de la luxation en abduction (stade 2).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2259, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un sportif de 25 ans a fait une chute sur le moignon de l''épaule il y a six mois. Le patient a été traité par un bandage pendant 8 jours. Il présente des douleurs de l''épaule survenant essentiellement lorsqu''il fait de la gymnastique (barres parallèles et vélo). Ses douleurs sont localisées a la partie supérieure du moignon de l''épaule. Il n''y a pas de douleur au repos et pas de sensation de ressaut, ni d''instabilité. L''examen met en évidence : à l''nspection une saillie osseuse en haut et en arrière au niveau de la partie supérieure du moignon de l''épaule - une mobilité active et passive de l''épaule normale - une douleur provoquée au cours de l''abduction de l''épaule à partir de 90 degrés jusqu''au zénith - la palpation montre une saillie osseuse située en dedans de l''extrémité distale de l''acromion. Cette saillie est mobile de haut en bas et d''avant en arrière.', false, true, 'Le traitement proposé est :', '[{"l":"A","t":"Une immobilisation en bandage de Velpeau pendant 3 semaines","c":false},{"l":"B","t":"Une rééducation fonctionnelle","c":false},{"l":"C","t":"Une infiltration locale de corticoïdes","c":false},{"l":"D","t":"Des anti-inflammatoires non stéroïdiens per os","c":false},{"l":"E","t":"Une intervention chirurgicale","c":true}]'::jsonb, 'Indication chirurgicale car : - il s''agit d''un stade 3 (déformation importante, tiroir antéro postérieur, touche de piano) - la gêne fonctionnelle est importante (jeune sportif) - la lésion est ancienne (supérieur à 6 semaines) Les techniques sont variées (hors programme)', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2260, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Ces données vous paraissent suffisantes pour éliminer a priori :', '[{"l":"A","t":"Une polyarthrose","c":true},{"l":"B","t":"Une pseudopolyarthrite rhizomélique","c":true},{"l":"C","t":"Une goutte polyarticulaire","c":true},{"l":"D","t":"Une polyarhrite","c":false},{"l":"E","t":"Une polymyosite","c":true}]'::jsonb, 'Il s''agit en effet d''une femme jeune présentant des arthrites périphériques depuis 6 mois, c''est-à-dire depuis son accouchement...', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2261, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'La topographie des atteintes articulaires est à priori évocatrice :', '[{"l":"A","t":"D''un syndrome de Reiter","c":false},{"l":"B","t":"D''une spondylarthrite ankylosante","c":false},{"l":"C","t":"D''un rhumatisme psoriasique","c":false},{"l":"D","t":"D''une polyarthrite rhumatoïde","c":true},{"l":"E","t":"D''une tuberculose articulaire","c":false}]'::jsonb, 'L''atteinte bilatérale des poignets, des M.C.P., des genoux et des chevilles évoque en premier lieu une polyarthrite rhumatoïde chez une femme.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2262, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Quel(s) examen(s) biologique(s) demandez-vous chez cette malade dans le seul but de confirmer l''existence d''un syndrome inflammatoire ?', '[{"l":"A","t":"Vitesse de sédimentation","c":true},{"l":"B","t":"Numération formule-plaquettes","c":true},{"l":"C","t":"Uricémie","c":false},{"l":"D","t":"Anticorps anti-nucléaires","c":false},{"l":"E","t":"Albuminémie","c":false}]'::jsonb, 'Dans ces examens, on peut retrouver en faveur d''un syndrome inflammatoire : une accélération de la vitesse de sédimentation et une thrombocytose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2263, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Parmi les examens suivants, quel est celui qui vous paraît le plus à même de confirmer le syndrome inflammatoire si les examens de sang laissaient un doute ?', '[{"l":"A","t":"Scintigraphie osseuse","c":false},{"l":"B","t":"Radiographies des jointures atteintes","c":false},{"l":"C","t":"Antigène HLA B 27","c":false},{"l":"D","t":"Numération des éléments du liquide articulaire","c":true},{"l":"E","t":"Thermographie","c":false}]'::jsonb, 'La ponction articulaire va ramener un liquide inflammatoire avec plus de 2 000 éléments par mm3 (polynucléaires essentiellement) et taux de protides supérieur à 40 g/l.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2264, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Quel(s) examen(s) biologique(s) demandez-vous pour préciser l''étiologie de ce tableau de polyarthrite ?', '[{"l":"A","t":"Latex et Waaler Rose","c":true},{"l":"B","t":"Myélogramme","c":false},{"l":"C","t":"Anticorps anti-nucléaires","c":true},{"l":"D","t":"Phosphatases alcalines","c":false},{"l":"E","t":"Albuminurie","c":false}]'::jsonb, 'Le premier diagnostic à évoquer devant une polyarthrite chez une femme jeune ayant débute après une grossesse, où l''on avait découvert une sérologie syphilitique positive, est le lupus. Néanmoins on éliminera une polyarthrite rhumatoïde qui est le diagnostic à évoquer ensuite.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2265, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Le sexe, l''âge, la survenue de la maladie après une grossesse évoquent plus particulièrement :', '[{"l":"A","t":"Polyarthrite rhumatoïde","c":false},{"l":"B","t":"Lupus érythémateux disséminé","c":true},{"l":"C","t":"Spondylarthrite ankylosante","c":false},{"l":"D","t":"Maladie de Horton","c":false},{"l":"E","t":"Chondrocalcinose","c":false}]'::jsonb, 'Sans hésitation car le faux B.W. positif et la poussée évolutive après la grossesse est très classique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2266, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 30 ans présente depuis 6 mois des douleurs articulaires bilatérales au niveau des poignets, des métacarpophalangiennes, des genoux et des chevilles. Les douleurs sont permanentes avec une raideur matinale d''environ 1 heure. Elle est asthénique, a perdu quelques kilos et présente une température à 38°C. L''examen montre une tuméfaction chaude des jointures atteintes et un petit souffle systolique de pointe. Elle aurait eu un rhumatisme articulaire aigu dans l''enfance Elle a accouché 6 mois plus tôt d''un enfant normal et au moment de sa grossesse, on aurait trouvé une sérologie syphilitique positive.', false, true, 'Vous voyez la malade en consultation et vous ne disposez encore d''aucun examen complémentaire Vous prescrivez :', '[{"l":"A","t":"Sels d''or","c":false},{"l":"B","t":"Corticoïdes per os","c":false},{"l":"C","t":"Antimalariques de synthèse","c":false},{"l":"D","t":"Colchicine","c":false},{"l":"E","t":"Anti inflammatoires non stéroïdiens","c":true}]'::jsonb, 'Il faut essayer de réduire l''inflammation par les A.I.N.S. avant toute chose et en attendant les résultats du bilan complémentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2267, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 34 ans. conducteur d''engins, est hospitalisé à la demande de son médecin traitant, pour sciatique droite, en vue d''une probable intervention chirurgicale. Dans les antécédents de ce patient, on trouve plusieurs épisodes lombalgiques généralement provoqués par des efforts. Il n''y a jamais eu de douleur des membres inférieurs avant la troisième semaine précédant l''hospitalisation. Est alors apparue une douleur du membre inférieur droit, intéressant la face postérieure de la cuisse, la face externe de la jambe, le dos du pied et le premier orteil, ainsi qu''une douleur du creux inguinal. L''examen clinique montre un signe de Lasegue droit à 60°. une raideur lombaire avec distance doigts-sol à 50 cm dans l''antéflexion maximale ; l''examen neurologique est normal. La mobilité des hanches est également normale. Le patient apporte des radiographies pratiquées un mois et demi plus tôt à loccasion de la lombalgie, qui montrent un spina bifida de S1 et une hémisacralasisation de L5. Ce malade, qui mesure 178 cm et pèse 86 kg a une vitesse de sédimentation normale, un hémogramme normal, une uricémie à 80 mg/l, (480 mmol).', false, true, 'En faveur d''un conflit discoradiculaire, vous retenez dans ce cas :', '[{"l":"A","t":"Les antécédents lombalgiques","c":true},{"l":"B","t":"Le spina bifida","c":false},{"l":"C","t":"L''examen neurologique normal","c":false},{"l":"D","t":"La douleur inguinale","c":false},{"l":"E","t":"Le signe de Lasègue","c":true}]'::jsonb, 'Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2268, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 34 ans. conducteur d''engins, est hospitalisé à la demande de son médecin traitant, pour sciatique droite, en vue d''une probable intervention chirurgicale. Dans les antécédents de ce patient, on trouve plusieurs épisodes lombalgiques généralement provoqués par des efforts. Il n''y a jamais eu de douleur des membres inférieurs avant la troisième semaine précédant l''hospitalisation. Est alors apparue une douleur du membre inférieur droit, intéressant la face postérieure de la cuisse, la face externe de la jambe, le dos du pied et le premier orteil, ainsi qu''une douleur du creux inguinal. L''examen clinique montre un signe de Lasegue droit à 60°. une raideur lombaire avec distance doigts-sol à 50 cm dans l''antéflexion maximale ; l''examen neurologique est normal. La mobilité des hanches est également normale. Le patient apporte des radiographies pratiquées un mois et demi plus tôt à loccasion de la lombalgie, qui montrent un spina bifida de S1 et une hémisacralasisation de L5. Ce malade, qui mesure 178 cm et pèse 86 kg a une vitesse de sédimentation normale, un hémogramme normal, une uricémie à 80 mg/l, (480 mmol).', false, true, 'Il importe de demander :', '[{"l":"A","t":"De nouveaux clichés lombaires de face et de profil","c":false},{"l":"B","t":"Une tomodensitométrie des derniers disques","c":false},{"l":"C","t":"Une radiculographie","c":false},{"l":"D","t":"Une scintigraphie","c":false},{"l":"E","t":"Aucun des examens précédents","c":true}]'::jsonb, 'Indication de traitement médical, aucun problème diagnostique donc pas d''examen.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2269, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 34 ans. conducteur d''engins, est hospitalisé à la demande de son médecin traitant, pour sciatique droite, en vue d''une probable intervention chirurgicale. Dans les antécédents de ce patient, on trouve plusieurs épisodes lombalgiques généralement provoqués par des efforts. Il n''y a jamais eu de douleur des membres inférieurs avant la troisième semaine précédant l''hospitalisation. Est alors apparue une douleur du membre inférieur droit, intéressant la face postérieure de la cuisse, la face externe de la jambe, le dos du pied et le premier orteil, ainsi qu''une douleur du creux inguinal. L''examen clinique montre un signe de Lasegue droit à 60°. une raideur lombaire avec distance doigts-sol à 50 cm dans l''antéflexion maximale ; l''examen neurologique est normal. La mobilité des hanches est également normale. Le patient apporte des radiographies pratiquées un mois et demi plus tôt à loccasion de la lombalgie, qui montrent un spina bifida de S1 et une hémisacralasisation de L5. Ce malade, qui mesure 178 cm et pèse 86 kg a une vitesse de sédimentation normale, un hémogramme normal, une uricémie à 80 mg/l, (480 mmol).', false, true, 'La douleur décrite par le patient évoque :', '[{"l":"A","t":"Un conflit discoradiculaire L3-L4","c":false},{"l":"B","t":"Un conflit discoradiculaire L4-L5","c":true},{"l":"C","t":"Un conflit discoradiculaire L5 S1","c":false},{"l":"D","t":"Une sténose du canal lombaire","c":false},{"l":"E","t":"Aucune de ces lésions","c":false}]'::jsonb, 'La douleur décrite est une radiculalgie L5. L5 est le plus souvent comprimée par une hernie paramédiane à l''étage susjacent (L4, L5 d''où B). Mais il faut se rappeler que la racine sort sous la vertèbre lombaire correspondante, ici dans le trou de conjugaison L5 S1 où elle serait alors comprimée par une hernie latéralisée (foraminale) ou par les articulaires (inférieure de L5, supérieure de S1). Ici le tableau est évocateur de hernie paramédiane, donc L4 L5.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2270, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 34 ans. conducteur d''engins, est hospitalisé à la demande de son médecin traitant, pour sciatique droite, en vue d''une probable intervention chirurgicale. Dans les antécédents de ce patient, on trouve plusieurs épisodes lombalgiques généralement provoqués par des efforts. Il n''y a jamais eu de douleur des membres inférieurs avant la troisième semaine précédant l''hospitalisation. Est alors apparue une douleur du membre inférieur droit, intéressant la face postérieure de la cuisse, la face externe de la jambe, le dos du pied et le premier orteil, ainsi qu''une douleur du creux inguinal. L''examen clinique montre un signe de Lasegue droit à 60°. une raideur lombaire avec distance doigts-sol à 50 cm dans l''antéflexion maximale ; l''examen neurologique est normal. La mobilité des hanches est également normale. Le patient apporte des radiographies pratiquées un mois et demi plus tôt à loccasion de la lombalgie, qui montrent un spina bifida de S1 et une hémisacralasisation de L5. Ce malade, qui mesure 178 cm et pèse 86 kg a une vitesse de sédimentation normale, un hémogramme normal, une uricémie à 80 mg/l, (480 mmol).', false, true, 'L''état de ce patient justifie particulièrement :', '[{"l":"A","t":"La mise au repos","c":true},{"l":"B","t":"L''usage des antiinflammatoires non stéroïdiens","c":true},{"l":"C","t":"La pratique d''une injection péridurale de corticoïde","c":true},{"l":"D","t":"Une kinésithérapie active","c":false},{"l":"E","t":"Une exploration chirurgicale","c":false}]'::jsonb, 'C''est l''indication typique du traitement médical : repos et A.I.N.S. par voie générale + infiltrations (1 à 3).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2271, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 34 ans. conducteur d''engins, est hospitalisé à la demande de son médecin traitant, pour sciatique droite, en vue d''une probable intervention chirurgicale. Dans les antécédents de ce patient, on trouve plusieurs épisodes lombalgiques généralement provoqués par des efforts. Il n''y a jamais eu de douleur des membres inférieurs avant la troisième semaine précédant l''hospitalisation. Est alors apparue une douleur du membre inférieur droit, intéressant la face postérieure de la cuisse, la face externe de la jambe, le dos du pied et le premier orteil, ainsi qu''une douleur du creux inguinal. L''examen clinique montre un signe de Lasegue droit à 60°. une raideur lombaire avec distance doigts-sol à 50 cm dans l''antéflexion maximale ; l''examen neurologique est normal. La mobilité des hanches est également normale. Le patient apporte des radiographies pratiquées un mois et demi plus tôt à loccasion de la lombalgie, qui montrent un spina bifida de S1 et une hémisacralasisation de L5. Ce malade, qui mesure 178 cm et pèse 86 kg a une vitesse de sédimentation normale, un hémogramme normal, une uricémie à 80 mg/l, (480 mmol).', false, true, 'L''hyperuricémie justifie :', '[{"l":"A","t":"L''usage de la colchicine","c":false},{"l":"B","t":"L''usage de l''allopurinol (Zyloric®)","c":false},{"l":"C","t":"Un régime hypocalorique","c":true},{"l":"D","t":"Un régime pauvre en alcool","c":true},{"l":"E","t":"Une urographie intraveineuse","c":false}]'::jsonb, 'L''hyperuricémie asymptomatique n''est traitée qu''à partir de 100 mg/l.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2272, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 30 ans se plaint depuis 6 mois d''une douleur mécanique siégeant au pli inguinal droit et à la face antérieure de la cuisse droite. Dans les antécédents, on retient la notion d''une immobilisation plâtrée du bassin et du membre inférieur droit pendant un an, à l''âge de 2 ans. Au terme de la consultation, on retient le diagnostic de coxarthrose.', false, true, 'Une origine dysplasique à cette coxarthrose est rapidement envisagée. Quel(s) élément(s) plaide(nt) en faveur de cette hypothèse ?', '[{"l":"A","t":"La douleur survenue électivement à la marche","c":false},{"l":"B","t":"Le siège inguino-crural de la douleur","c":false},{"l":"C","t":"L''âge de la malade","c":true},{"l":"D","t":"L''antécédent d''immobilisation plâtrée dans l''enfance","c":true},{"l":"E","t":"Le sexe","c":true}]'::jsonb, 'A. B - Sont des signes de coxarthrose sans orientation étiologique. C - La coxarthrose est inhabituelle chez l''adulte jeune et doit faire évoquer son caractère secondaire (dysplasie, traumatisme,...). D - Méthode de réduction par plâtres successifs autrefois employée comme tentative de réduction des luxations congénitales de hanche diagnostiquées à l''âge de la marche (le dépistage systématique chez le nouveau-né et la radio du 4e mois sont récents). E - Classiquement la luxation congénitale de hanche est plus fréquente chez les filles, premières-nées, originaires de Bretagne (Sex-ratio : 3 filles/1 garçon).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2273, 17, 'Rhumatologie', 'Maladies luxantes de la hanche', 'Une femme de 30 ans se plaint depuis 6 mois d''une douleur mécanique siégeant au pli inguinal droit et à la face antérieure de la cuisse droite. Dans les antécédents, on retient la notion d''une immobilisation plâtrée du bassin et du membre inférieur droit pendant un an, à l''âge de 2 ans. Au terme de la consultation, on retient le diagnostic de coxarthrose.', false, true, 'Des radiographies sont demandées pour affirmer le diagnostic de coxarthrose sur dysplasie de hanche. Quels sont les 2 clichés suffisants à ce diagnostic ?', '[{"l":"A","t":"Un cliché de profil de la hanche droite","c":false},{"l":"B","t":"Un cliché de face de la hanche droite","c":false},{"l":"C","t":"Un cliché de bassin, debout, de face, les membres inférieurs en rotation interne de 20°","c":true},{"l":"D","t":"Un cliché de bassin en oblique à 25° (faux-profil)","c":true},{"l":"E","t":"Des tomographies de la hanche droite","c":false}]'::jsonb, 'La coxométrie confirme la dysplasie cotyloïdienne par la mesure des angles de couverture externe et antérieure du toit, et l''angle d''obliquite du toit, et la dysplasie fémorale par la mesure de l''angle cervico-diaphysaire. C - Le cliché de bassin de face permet l''étude comparative. Un bon cliché de face est obtenu avec une rotation interne de 20°, et l''on doit visualiser les deux petits trochanters. D - Est le faux profil de Lequesne, qui réalise un vrai profil de la tête fémorale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2274, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 30 ans se plaint depuis 6 mois d''une douleur mécanique siégeant au pli inguinal droit et à la face antérieure de la cuisse droite. Dans les antécédents, on retient la notion d''une immobilisation plâtrée du bassin et du membre inférieur droit pendant un an, à l''âge de 2 ans. Au terme de la consultation, on retient le diagnostic de coxarthrose.', false, true, 'Les radiographies montrent les signes d''une coxarthrose débutante. Quel est, à votre avis, le signe compatible avec ce diagnostic ?', '[{"l":"A","t":"Perte de l''arrondi de la tête fémorale","c":false},{"l":"B","t":"Condensation hétérogène de la tête fémorale","c":false},{"l":"C","t":"Flou du contour de la tête fémorale","c":false},{"l":"D","t":"Géode du col fémoral","c":false},{"l":"E","t":"Pincement de 1 mm de l''interligne dans le quadrant supéro-externe","c":true}]'::jsonb, 'Le pincement est un signe précoce de coxarthrose. Il prédomine dans la zone d''hyperpression, le plus souvent supéro-externe (la dysplasie cotyloïdienne étant habituellement un défaut de couverture du toit). A. B. C - Nécrose de la tête fémorale. D - Doit faire rechercher s''il est isolé en processus tumoral (dysplasie fibreuse...).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2275, 26, 'Rhumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Une femme de 30 ans se plaint depuis 6 mois d''une douleur mécanique siégeant au pli inguinal droit et à la face antérieure de la cuisse droite. Dans les antécédents, on retient la notion d''une immobilisation plâtrée du bassin et du membre inférieur droit pendant un an, à l''âge de 2 ans. Au terme de la consultation, on retient le diagnostic de coxarthrose.', false, true, 'Une coxométrie est réalisée. Elle montre les résultats suivants : angle cervico-diaphysaire CCD 130° - angle de couverture extême de la tête VCE 15° - angle de couverture antérieure de la tête VCA 25° - angle d''obliquité HTE 23°. A votre avis, cette dysplasie correspond à :', '[{"l":"A","t":"Une coxa valga","c":false},{"l":"B","t":"Une couverture externe insuffisante de la tête","c":true},{"l":"C","t":"Une couverture antérieure de la tête insuffisante","c":false},{"l":"D","t":"Une pente exagérée du toit du cotyle","c":true},{"l":"E","t":"Une protrusion acétabulaire","c":false}]'::jsonb, 'Connaissance. Les valeurs normales sont : - CC''D - 130° - VCA et VCE supérieurs ou égal à 25° (20 à 25) - HTE inférieur à 10°', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2276, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Une femme de 30 ans se plaint depuis 6 mois d''une douleur mécanique siégeant au pli inguinal droit et à la face antérieure de la cuisse droite. Dans les antécédents, on retient la notion d''une immobilisation plâtrée du bassin et du membre inférieur droit pendant un an, à l''âge de 2 ans. Au terme de la consultation, on retient le diagnostic de coxarthrose.', false, true, 'Le diagnostic de coxarthrose secondaire débutante est affirmé. Quelle est l''attitude thérapeutique qui seule peut prévenir l''aggravation de cette coxarthrose ?', '[{"l":"A","t":"L''emploi de la balnéothérapie et de la bicyclène","c":false},{"l":"B","t":"Une rééducation élective des adducteurs et du moyen fessier","c":false},{"l":"C","t":"L''emploi d''anti inflammatoires non stéroïdiens","c":false},{"l":"D","t":"L''emploi d''une canne pour favoriser la décharge de la hanche douloureuse","c":false},{"l":"E","t":"L''intervention chirurgicale rapide","c":true}]'::jsonb, 'L''indication chirurgicale devant cette dysplasie repose sur : - la douleur - le risque arthrosique de la dysplasie. L''intervention chirurgicale rapide pourra être conservatrice car l''arthrose est débutante, et permettra de freiner l''évolution de la maladie (et retarder l''âge de la prothèse). On discutera : une butée, une ostéotomie de bassin (chiari), hors programme. Noter que dans la coxarthrose idiopathique du sujet d''âge mûr, le traitement est d''abord médical par A,B,C,D pour retarder le plus poss ble l''heure de la chirurgie prothétique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2277, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'A quel diagnostic pensez-vous le plus volontiers, compte-tenu de l''âge et des signes cliniques ?', '[{"l":"A","t":"Luxation traumatique de la hanche","c":false},{"l":"B","t":"Fracture du cotyle","c":false},{"l":"C","t":"Fracture du cadre obturateur","c":false},{"l":"D","t":"Fracture du col du fémur","c":true},{"l":"E","t":"Rupture musculaire du droit antérieur","c":false}]'::jsonb, 'L''âge, les circonstances, l''impotence fonctionnelle, l''examen clinique (douleur de l''aine et déformation typique) sont hautement évocateurs.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2278, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'L''attitude du membre inférieur atteint de fracture transcervicale du fémur type 3 de Garden comporte :', '[{"l":"A","t":"Rotation interne","c":false},{"l":"B","t":"Allongement","c":false},{"l":"C","t":"Raccourcissement","c":true},{"l":"D","t":"Rotation externe","c":true},{"l":"E","t":"Adduction","c":true}]'::jsonb, 'Rappel : la fracture garden 3 comporte un déplacement en varus et bascule postérieure de la tête. Le garden 3 est la plus fréquente des fractures cervicales (45%).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2279, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'Le risque le plus important encouru par un vieillard atteint de fracture du fémur est-il ?', '[{"l":"A","t":"La raideur de la hanche","c":false},{"l":"B","t":"La pseudarthrose","c":false},{"l":"C","t":"Un risque vital","c":true},{"l":"D","t":"La nécrose post traumatique de la tête fémorale","c":false},{"l":"E","t":"Le cal vicieux","c":false}]'::jsonb, 'La mortalité globale par fracture du col fémoral dans cette tranche d''âge est de 15%, en raison des tares associées. D''où la règle de mise au fauteuil la plus précoce possible (2e jour) après traitement chirurgical.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2280, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'Le traitement de principe d''une fracture du col du fémur à 85 ans chez une femme encore valide est-il ?', '[{"l":"A","t":"L''abstention thérapeutique","c":false},{"l":"B","t":"L''immobilisation simple au lit","c":false},{"l":"C","t":"Le traitement chirurgical","c":true},{"l":"D","t":"L''immobilisation en plâtre pelvipédieux","c":false},{"l":"E","t":"La rééducation précoce avec kinésithérapie","c":false}]'::jsonb, 'Pour les raisons évoquées à la question précédente (complications de décubitus).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2281, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'Le traitement le plus adapté à une fracture transcervicale du fémur du vieillard est-il ?', '[{"l":"A","t":"La suspension traction par broche transosseuse","c":false},{"l":"B","t":"La synthèse de la fracture","c":false},{"l":"C","t":"La mise en place d''une prothèse cervico-céphalique","c":true},{"l":"D","t":"La mise en place d''une cupule sur la tête du fémur","c":false},{"l":"E","t":"L''enclouage élastique de Ender à travers la diaphyse fémorale","c":false}]'::jsonb, 'C - Permet la mise au fauteuil et la reprise de l''appui précoces (3e jour). D''autre part, le risque de nécrose céphalique élevé du fait du déplacement (garden 3 avec comminution postérieure, très préjudiciable à la vascularisation) incite à pratiquer d''emblée l''arthoplastie (prothèse de Moore ou analogue : C) A - Traitement orthopédique de certaines fractures du cotyle. B. E - Traitement de choix conservateur chez le sujet jeune, dans les fractures peu déplacées. D - Traitement des nécroses céphaliques chez le sujet jeune. Suppose un col intact.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2282, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une vieille dame de 85 ans, qui conservait une activité de ménagère dans sa maison et faisait seule quelques sorties dans son village, fait une chute de sa hauteur et ne peut plus se relever. Elle présente une douleur aiguë dans l''aine droite Elle est transportée par des voisins jusqu''à sa maison toute proche où on l''allonge sur un lit. Vous êtes appelé en urgence et constatez une tumeur molle douloureuse dans l''aine et une attitude en rotation externe du membre inférieur droit. L''essai de mobilisation entraîne de vives douleurs.', false, true, 'Si cette femme avant sa fracture avait déjà perdu la fonction de la marche depuis longtemps et devait avoir recours à une tierce personne pour aller du lit au fauteuil, quel traitement aurait été logique ?', '[{"l":"A","t":"Synthèse chirurgicale","c":false},{"l":"B","t":"Prothèse de hanche","c":false},{"l":"C","t":"Suspension traction au lit","c":false},{"l":"D","t":"Mise au fauteuil (Lucas Championnière)","c":true},{"l":"E","t":"Résection simple de la tête fémorale","c":false}]'::jsonb, 'Le traitement chirurgical perd alors son bénéfice (contre A,B,E) C - Le décubitus est proscrit (risque vital déjà évoqué).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2283, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Une femme de 60 ans présente des paresthésies et des douleurs intéressant les trois premiers doigts de la main droite. Ces manifestations surviennent parfois dans la journée mais surtout dans la deuxième partie de la nuit. La symptomatologie est réveillée lors de l''examen par la flexion du poignet et la pression exercée à la face palmaire du poignet. L''examen neurologique ne fait pas apparaître de modifications des réflexes ostéo-tendineux des membres supérieurs non plus que de déficit sensitif distal. L''éventualité d''un syndrome du canal est évoquée.', false, true, 'Parmi les muscles suivants quel(s) est (sont) celui (ceux) dont le déficit peut être compatible avec un tel diagnostic ?', '[{"l":"A","t":"Court abducteur du pouce","c":true},{"l":"B","t":"Long abducteur du pouce","c":false},{"l":"C","t":"Adducteur du pouce","c":false},{"l":"D","t":"Opposant du pouce","c":true},{"l":"E","t":"Court extenseur du pouce","c":false}]'::jsonb, 'Le médian au poignet innerve les trois muscles thénariens externes : - court fléchisseur du pouce (faisceau superficiel) - court abducteur du pouce (A) - opposant du pouce (D) B. E - Nerf radial, branche motrice. C - Nerf cubital.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2284, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans présente des paresthésies et des douleurs intéressant les trois premiers doigts de la main droite. Ces manifestations surviennent parfois dans la journée mais surtout dans la deuxième partie de la nuit. La symptomatologie est réveillée lors de l''examen par la flexion du poignet et la pression exercée à la face palmaire du poignet. L''examen neurologique ne fait pas apparaître de modifications des réflexes ostéo-tendineux des membres supérieurs non plus que de déficit sensitif distal. L''éventualité d''un syndrome du canal est évoquée.', false, true, 'Parmi les circonstances étiologiques suivantes, ce syndrome du canal carpien peut être la conséquence de :', '[{"l":"A","t":"Amylose","c":true},{"l":"B","t":"Hypothyroïdie","c":true},{"l":"C","t":"Diabète","c":false},{"l":"D","t":"Polyarthrite rhumatoïde","c":true},{"l":"E","t":"Fracture de l''extrémité inférieure du radius","c":true}]'::jsonb, 'A. B - Sont classiques et font partie des causes générales à bien connaître. D - Par la ténosynovite des fléchisseurs. E - Par cal vicieux du composant osseux de ce canal ostéoligamentaire. Le syndrome du canal carpien idiopathique reste le plus fréquent.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2285, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 60 ans présente des paresthésies et des douleurs intéressant les trois premiers doigts de la main droite. Ces manifestations surviennent parfois dans la journée mais surtout dans la deuxième partie de la nuit. La symptomatologie est réveillée lors de l''examen par la flexion du poignet et la pression exercée à la face palmaire du poignet. L''examen neurologique ne fait pas apparaître de modifications des réflexes ostéo-tendineux des membres supérieurs non plus que de déficit sensitif distal. L''éventualité d''un syndrome du canal est évoquée.', false, true, 'Une infiltration est envisagée chez cette patiente. Parmi les éléments suivants quel(s) est (sont) celui (ceux) qui doit (doivent) faire renoncer à ce geste ?', '[{"l":"A","t":"Polyarthrite rhumatoïde","c":false},{"l":"B","t":"Déficit moteur important","c":true},{"l":"C","t":"Echec de deux infiltrations antérieures récentes","c":true},{"l":"D","t":"Ténosynovite tuberculeuse des fléchisseurs","c":true},{"l":"E","t":"Bilatéralité de la symptomatologie","c":false}]'::jsonb, 'B - Est une indication chirurgicale sans tarder. C - Car inefficace. D - Le traitement spécifique s''impose. La corticothérapie tant locale que générale est contre-indiquée (cause infectieuse). A - Est un bon traitement ++. E - N''est pas une contre-indication en soi.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2286, 35, 'Rhumatologie', 'Syndrome du canal carpien', 'Une femme de 60 ans présente des paresthésies et des douleurs intéressant les trois premiers doigts de la main droite. Ces manifestations surviennent parfois dans la journée mais surtout dans la deuxième partie de la nuit. La symptomatologie est réveillée lors de l''examen par la flexion du poignet et la pression exercée à la face palmaire du poignet. L''examen neurologique ne fait pas apparaître de modifications des réflexes ostéo-tendineux des membres supérieurs non plus que de déficit sensitif distal. L''éventualité d''un syndrome du canal est évoquée.', false, true, 'Avec laquelle(esquelles) des affirmations suivantes concernant le traitement infiltratif êtes-vous d''accord ?', '[{"l":"A","t":"L''infiltration peut constituer un test thérapeutique","c":true},{"l":"B","t":"L''injection s''effectue dans le canal de Guyon","c":false},{"l":"C","t":"Le produit utilisé est un corticoïde","c":true},{"l":"D","t":"L''infiltration peut être répétée régulièrement même en cas de rechutes fréquentes","c":false},{"l":"E","t":"Un délai de 6 mois minimum est nécessaire entre deux infiltrations","c":false}]'::jsonb, 'B - Non : dans le canal carpien. D - Limiter les infiltrations à 2 ou 3 et les espacer (complications, voir question [135]). E - Non. Le test d''infiltration aux corticoïdes est un bon élément diagnostique à connaître.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2287, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Une femme de 60 ans présente des paresthésies et des douleurs intéressant les trois premiers doigts de la main droite. Ces manifestations surviennent parfois dans la journée mais surtout dans la deuxième partie de la nuit. La symptomatologie est réveillée lors de l''examen par la flexion du poignet et la pression exercée à la face palmaire du poignet. L''examen neurologique ne fait pas apparaître de modifications des réflexes ostéo-tendineux des membres supérieurs non plus que de déficit sensitif distal. L''éventualité d''un syndrome du canal est évoquée.', false, true, 'Parmi les éléments suivants, quel(s) est(sont) celui(ceux) susceptible(s) de constituer une complication du traitement infiltratif du syndrome du canal carpien ?', '[{"l":"A","t":"Douleur immédiate par injection défectueuse dans la gaine du médian","c":true},{"l":"B","t":"Rupture d''un tendon fléchisseur","c":true},{"l":"C","t":"Déclenchement d''une crise de goutte","c":false},{"l":"D","t":"Atrophie cutanée en regard de la zone d''infiltration","c":true},{"l":"E","t":"Infection locale","c":true}]'::jsonb, 'B. D propre aux corticoïdes, limitant leur emploi répété. A. E - Risque de tout geste invasif en sachant que l''infection locale risque d''être retardée et abatardie par les corticoïdes.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2288, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur R. André, 47 ans. est attaché commercial dans une entreprise de chaussures caractérisée par ses prix élevés et ses méventes récentes. Ses soucis professionnels bien surmontés jusqu''alors ont entraîné des gastralgies d''intensité croissante qu''il a pris l''habitude de calmer par des prises de lait alternées avec une poudre de carbonate de calcium dont il prend 2 gr à la fois jusqu''à six fois par jour. Il consulte car il a présenté coup sur coup plusieurs fols par semaine depuis trois semaines, des crises douloureuses violentes à type de colique néphrétique droite ou gauche. La calcémie est variable entre 2,5 et 2,8 mmol. La phosphorémie est normale. La calciurie varie entre 12 et 15 mmol/24 h. Une radiographie montre de multiples calcifications dans la zone corticomédullaire des deux reins.', false, true, 'Sans tenir compte des données cliniques et biologiques. le tableau radiologique est compatible avec le(s) diagnostic(s) suivant(s) :', '[{"l":"A","t":"Hypoparathyroïdie","c":false},{"l":"B","t":"Hypercalciurie par excès d''apport calcique","c":false},{"l":"C","t":"Néphrocalcinose par maladie kystique de la médullaire (maladie de Cacchi-Ricci)","c":true},{"l":"D","t":"Hypervitaminose D","c":true},{"l":"E","t":"Malabsorption intestinale","c":false}]'::jsonb, 'Un apport calcique isolé est exceptionnellement responsable d''une nephrocalcinose, mais celle-ci est possible en cas d''hypervitaminose D. La maladie de Cacchi et Ricci est une maladie congénitale héréditaire caractérisée par une dilatation des tubes collecteurs des papilles rénales, et une néphrocalcinose papillaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2289, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur R. André, 47 ans. est attaché commercial dans une entreprise de chaussures caractérisée par ses prix élevés et ses méventes récentes. Ses soucis professionnels bien surmontés jusqu''alors ont entraîné des gastralgies d''intensité croissante qu''il a pris l''habitude de calmer par des prises de lait alternées avec une poudre de carbonate de calcium dont il prend 2 gr à la fois jusqu''à six fois par jour. Il consulte car il a présenté coup sur coup plusieurs fols par semaine depuis trois semaines, des crises douloureuses violentes à type de colique néphrétique droite ou gauche. La calcémie est variable entre 2,5 et 2,8 mmol. La phosphorémie est normale. La calciurie varie entre 12 et 15 mmol/24 h. Une radiographie montre de multiples calcifications dans la zone corticomédullaire des deux reins.', false, true, 'Parmi les hypothèses suivantes, laquelle vous parait la plus recevable en tenant compte de l''ensemble clinique, radiologique et biologique ?', '[{"l":"A","t":"Néphrocalcinose par tubulopathie","c":false},{"l":"B","t":"Maladie polykystique héréditaire","c":false},{"l":"C","t":"Hypercorticisme","c":false},{"l":"D","t":"Iléite terminale de type maladie de Crohn","c":false},{"l":"E","t":"Syndrome de Burnett par prise de lait alcalin","c":true}]'::jsonb, 'Le bilan biologique ne montre qu''une hypercalciurie secondaire aux apports trop importants de calcium. Les calcifications de la zone cortico-médullaires correspondent bien aux calcification papillaires du Cacci-Ricci.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2290, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur R. André, 47 ans. est attaché commercial dans une entreprise de chaussures caractérisée par ses prix élevés et ses méventes récentes. Ses soucis professionnels bien surmontés jusqu''alors ont entraîné des gastralgies d''intensité croissante qu''il a pris l''habitude de calmer par des prises de lait alternées avec une poudre de carbonate de calcium dont il prend 2 gr à la fois jusqu''à six fois par jour. Il consulte car il a présenté coup sur coup plusieurs fols par semaine depuis trois semaines, des crises douloureuses violentes à type de colique néphrétique droite ou gauche. La calcémie est variable entre 2,5 et 2,8 mmol. La phosphorémie est normale. La calciurie varie entre 12 et 15 mmol/24 h. Une radiographie montre de multiples calcifications dans la zone corticomédullaire des deux reins.', false, true, 'D''autres causes peuvent théoriquement entraîner une néphrocalcinose. Citez la(les) hypothèse(s) possible(s) devant la seule image radiologique :', '[{"l":"A","t":"Sarcoïdose (maladie de BBS)","c":true},{"l":"B","t":"Hyperthyroïdie","c":false},{"l":"C","t":"Insuffisance surrénale lente","c":false},{"l":"D","t":"Prise excessive de chelateurs de phosphore","c":false},{"l":"E","t":"Tubulopathie de type Toni Debré Fanconi","c":true}]'::jsonb, 'La sarcoïdose par hyperactivité 1-alpha-hydroxylase des macrophages des granulomes est responsable d''une augmentation de l''absorption du calcium avec hypercalciurie et hypercalcémie. Les tubulopathies peuvent être associées à une néphrocalcinose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2291, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Monsieur R. André, 47 ans. est attaché commercial dans une entreprise de chaussures caractérisée par ses prix élevés et ses méventes récentes. Ses soucis professionnels bien surmontés jusqu''alors ont entraîné des gastralgies d''intensité croissante qu''il a pris l''habitude de calmer par des prises de lait alternées avec une poudre de carbonate de calcium dont il prend 2 gr à la fois jusqu''à six fois par jour. Il consulte car il a présenté coup sur coup plusieurs fols par semaine depuis trois semaines, des crises douloureuses violentes à type de colique néphrétique droite ou gauche. La calcémie est variable entre 2,5 et 2,8 mmol. La phosphorémie est normale. La calciurie varie entre 12 et 15 mmol/24 h. Une radiographie montre de multiples calcifications dans la zone corticomédullaire des deux reins.', false, true, 'Malgré les précautions et les conseils donnés, le sujet élimine à plusieurs reprises de petits calculs de phosphate de calcium et un calcul du bassinet droit est constaté. Quel(s) est(sont) le(s) facteur(s) favorisant ce type de lithiase ?', '[{"l":"A","t":"Urines alcalines","c":true},{"l":"B","t":"Boissons abondantes","c":false},{"l":"C","t":"Soucis professionnels","c":false},{"l":"D","t":"Consommation excessive de légumes (oseille,.épinard,.artichaut)","c":false},{"l":"E","t":"Infection urinaire à proteus mirabilis","c":true}]'::jsonb, 'L''infection urinaire à proteus (germe uréasique) favorise l''alcalinisation des urines.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2292, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Monsieur R. André, 47 ans. est attaché commercial dans une entreprise de chaussures caractérisée par ses prix élevés et ses méventes récentes. Ses soucis professionnels bien surmontés jusqu''alors ont entraîné des gastralgies d''intensité croissante qu''il a pris l''habitude de calmer par des prises de lait alternées avec une poudre de carbonate de calcium dont il prend 2 gr à la fois jusqu''à six fois par jour. Il consulte car il a présenté coup sur coup plusieurs fols par semaine depuis trois semaines, des crises douloureuses violentes à type de colique néphrétique droite ou gauche. La calcémie est variable entre 2,5 et 2,8 mmol. La phosphorémie est normale. La calciurie varie entre 12 et 15 mmol/24 h. Une radiographie montre de multiples calcifications dans la zone corticomédullaire des deux reins.', false, true, 'Parmi les mesures thérapeutiques envisagées chez ce sujet en particulier, laquelle(lesquelles) vous parai(ssen)t adéquate(s) ?', '[{"l":"A","t":"Changement radical du traitement des gastralgies","c":true},{"l":"B","t":"Abord chirurgical pour réduction des parathyroïdes de 7/8ème (on laisse une 1/2 parathyroïde sur 4)","c":false},{"l":"C","t":"Prise d''inhibiteur de synthèse de l''acide urique","c":false},{"l":"D","t":"Prescription prolongée de Kayexalate®","c":false},{"l":"E","t":"Traitement de l''infection urinaire à proteus","c":true}]'::jsonb, 'Il faut en effet réduire les apports de calcium et traiter l''infection, puis instaurer une diurèse par une eau pauvre en calcium.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2293, 9, 'Rhumatologie', 'Spondylarthrites', 'M. B.... 48 ans, salarie peintre en bâtiment, souffre, depuis 3 ans d''épigastralgies survenant par poussées. La seule fibroscopie pratiquée, qui date de 2 ans, a montre un ulcère duodénal bulbaire ; le traitement est suivi très irrégulièrement ; des douleurs sont survenues récemment. Par ailleurs, depuis 4 ans, il existe des rachialgies rapportées à ses activités professionnelles, lesquelles sollicitent fortement les segments rachidiens mobiles. A début lombaire, ces douleurs, qui surviennent par poussées de quelques semaines, ont ensuite concerné également l''étage dorsal et la colonne cervicale. M. B... signale aussi des douleurs thoraciques latérales et antérieures et a vu enfin apparaître, depuis 1 mois, des douleurs inguinales bilatérales. Toutes ces algies du tronc ont une composante nocturne prolongée, en fin de nuit, et entraînent un enraidissement matinal de plusieurs heures. L''examen clinique réalisé l''après-midi montre un test de Schober à 10+1 cm, une distance occiput-mur de 10 cm, une ampliation thoracique de 3,5 cm ; les hanches sont douloureuses à la mobilisation ; la flexion, l''abduction et les rotations sont modérément limitées. Les radiographies montrent des coxofémorales normales, des anomalies des 2 sacro-iliaques avec élargissement et irrégularité de l''interligne flou et condensation de ses berges. Il existe des ossifications sous-ligamentaires unissant les corps vertébraux de D11 à L4.VS : 48 mm à la 1ère heure.', false, true, 'Pour affirmer, chez ce malade, le diagnostic de spondylarthrite ankylosante, aquelle (lesquelles) des 5 propositions suivantes est (sont) exacte(s) ?', '[{"l":"A","t":"Un groupage tissulaire à la recherche du B27 est indispensable","c":false},{"l":"B","t":"Une scintigraphie osseuse est nécessaire","c":false},{"l":"C","t":"La mise en évidence dans le sérum d''anticorps antinucléaires et d''une hypocomplémentémie sera décisive","c":false},{"l":"D","t":"Une ponction biopsie de sacro-iliaque s''impose","c":false},{"l":"E","t":"Les données rapportées dans l''observation suffisent","c":true}]'::jsonb, 'Le critère de terrain HLA B27 n''est pas indispensable tant le tableau est évident. De plus lO% des pelvispondylites rhumatismales n''ont pas le HLA B27.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2294, 9, 'Rhumatologie', 'Spondylarthrites', 'M. B.... 48 ans, salarie peintre en bâtiment, souffre, depuis 3 ans d''épigastralgies survenant par poussées. La seule fibroscopie pratiquée, qui date de 2 ans, a montre un ulcère duodénal bulbaire ; le traitement est suivi très irrégulièrement ; des douleurs sont survenues récemment. Par ailleurs, depuis 4 ans, il existe des rachialgies rapportées à ses activités professionnelles, lesquelles sollicitent fortement les segments rachidiens mobiles. A début lombaire, ces douleurs, qui surviennent par poussées de quelques semaines, ont ensuite concerné également l''étage dorsal et la colonne cervicale. M. B... signale aussi des douleurs thoraciques latérales et antérieures et a vu enfin apparaître, depuis 1 mois, des douleurs inguinales bilatérales. Toutes ces algies du tronc ont une composante nocturne prolongée, en fin de nuit, et entraînent un enraidissement matinal de plusieurs heures. L''examen clinique réalisé l''après-midi montre un test de Schober à 10+1 cm, une distance occiput-mur de 10 cm, une ampliation thoracique de 3,5 cm ; les hanches sont douloureuses à la mobilisation ; la flexion, l''abduction et les rotations sont modérément limitées. Les radiographies montrent des coxofémorales normales, des anomalies des 2 sacro-iliaques avec élargissement et irrégularité de l''interligne flou et condensation de ses berges. Il existe des ossifications sous-ligamentaires unissant les corps vertébraux de D11 à L4.VS : 48 mm à la 1ère heure.', false, true, 'Voici 5 propositions concernant le test de SCHOBER; laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"Il explore la flexion du rachis lombaire et de la charnière lombosacrée","c":true},{"l":"B","t":"A l''etat normal, la longueur du trait passe de 10 à 16 cm au minimum","c":false},{"l":"C","t":"Il est toujours pathologique au cours de la spondylarthrite ankylosante","c":false},{"l":"D","t":"Il est toujours normal dans les lombalgies communes, d''origine discale","c":false},{"l":"E","t":"Sa valeur dans la spondylarthrite ankylosante, peut varier au cours de la journée","c":true}]'::jsonb, 'Le Schober est de 10 + 5 cm en moyenne et sa valeur peut varier très légèrement dans la journée car il s''agit d''une maladie inflammatoire avec raideur maximale le matin.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2295, 9, 'Rhumatologie', 'Spondylarthrites', 'M. B.... 48 ans, salarie peintre en bâtiment, souffre, depuis 3 ans d''épigastralgies survenant par poussées. La seule fibroscopie pratiquée, qui date de 2 ans, a montre un ulcère duodénal bulbaire ; le traitement est suivi très irrégulièrement ; des douleurs sont survenues récemment. Par ailleurs, depuis 4 ans, il existe des rachialgies rapportées à ses activités professionnelles, lesquelles sollicitent fortement les segments rachidiens mobiles. A début lombaire, ces douleurs, qui surviennent par poussées de quelques semaines, ont ensuite concerné également l''étage dorsal et la colonne cervicale. M. B... signale aussi des douleurs thoraciques latérales et antérieures et a vu enfin apparaître, depuis 1 mois, des douleurs inguinales bilatérales. Toutes ces algies du tronc ont une composante nocturne prolongée, en fin de nuit, et entraînent un enraidissement matinal de plusieurs heures. L''examen clinique réalisé l''après-midi montre un test de Schober à 10+1 cm, une distance occiput-mur de 10 cm, une ampliation thoracique de 3,5 cm ; les hanches sont douloureuses à la mobilisation ; la flexion, l''abduction et les rotations sont modérément limitées. Les radiographies montrent des coxofémorales normales, des anomalies des 2 sacro-iliaques avec élargissement et irrégularité de l''interligne flou et condensation de ses berges. Il existe des ossifications sous-ligamentaires unissant les corps vertébraux de D11 à L4.VS : 48 mm à la 1ère heure.', false, true, 'Des 5 propositions suivantes concernant ce cas, laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"Une distance occiput-mur de 10 cm n''est pas pathologique chez l''adulte","c":false},{"l":"B","t":"Une ampliation thoracique de 3.5 cm est pathologique et traduit une atteinte des articulations costovertébrales","c":true},{"l":"C","t":"La limitation du jeu des hanches ne peut pas être expliquée par la spondylarthrite ankylosante","c":false},{"l":"D","t":"Les images radiologiques vues sur la charnière dorsolombaire et le rachis lombaire correspondent à des syndesmophytes","c":true},{"l":"E","t":"Une nouvelle fibroscopie gastro-duodénale est justifiée avant un éventuel traitement anti-inflammatoire","c":true}]'::jsonb, 'La limitation des hanches y compris en flexion, sans pincement articulaire évident évoque une atteinte inflammatoire des coxofémorales qui engage le pronostic fonctionnel de la maladie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2296, 3, 'Rhumatologie', 'Principe de base en médecine physique et réadaptation', 'M. B.... 48 ans, salarie peintre en bâtiment, souffre, depuis 3 ans d''épigastralgies survenant par poussées. La seule fibroscopie pratiquée, qui date de 2 ans, a montre un ulcère duodénal bulbaire ; le traitement est suivi très irrégulièrement ; des douleurs sont survenues récemment. Par ailleurs, depuis 4 ans, il existe des rachialgies rapportées à ses activités professionnelles, lesquelles sollicitent fortement les segments rachidiens mobiles. A début lombaire, ces douleurs, qui surviennent par poussées de quelques semaines, ont ensuite concerné également l''étage dorsal et la colonne cervicale. M. B... signale aussi des douleurs thoraciques latérales et antérieures et a vu enfin apparaître, depuis 1 mois, des douleurs inguinales bilatérales. Toutes ces algies du tronc ont une composante nocturne prolongée, en fin de nuit, et entraînent un enraidissement matinal de plusieurs heures. L''examen clinique réalisé l''après-midi montre un test de Schober à 10+1 cm, une distance occiput-mur de 10 cm, une ampliation thoracique de 3,5 cm ; les hanches sont douloureuses à la mobilisation ; la flexion, l''abduction et les rotations sont modérément limitées. Les radiographies montrent des coxofémorales normales, des anomalies des 2 sacro-iliaques avec élargissement et irrégularité de l''interligne flou et condensation de ses berges. Il existe des ossifications sous-ligamentaires unissant les corps vertébraux de D11 à L4.VS : 48 mm à la 1ère heure.', false, true, 'Pour le traitement de ce rhumatisme inflammatoire, voici 5 propositions. Laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"Une déclaration du diagnostic à la Sécurité Sociale permettra une prise en charge à 100 %","c":true},{"l":"B","t":"Le risque de complication de l''ulcère duodénal contre-indique définitivement les AINS","c":false},{"l":"C","t":"Le paracétamol peut être utilise sans restriction","c":true},{"l":"D","t":"Un arrêt de travail sera justifié lors de poussées sévères","c":true},{"l":"E","t":"Une kinésithérapie est devenue inutile","c":false}]'::jsonb, 'Si la fibroscopie montre l''absence d''ulcère, un traitement par A.I.N.S. pourra être prescrit sous couvert d''un traitement par anti- H2. La kinésithérapie est indispensable pour retarder l''enraidissement et le conduire en position de fonction. Les antalgiques doivent être utilisés au maximum pour réduire les doses d''A.I.N.S.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2297, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Chez un homme de 38 ans, on découvre une uricémie à 85 mg/l ( méthode a l''uricase). Il n''a jamais fait de crises goutteuses, son poids est de 83 kg, sa taille de 168 cm, ses chiffres tensionnels de 170/100 mm Hg ; le reste de l''examen clinique est sans particularités. Il n''a pas de protéinurie ; l''examen du fond d''oeil est normal ; l''hémogramme est sans particularité. La créatinine plasmatique est à 10 micromol/l. Il n''y a pas de lithiase urique ; l''uraturie est demandée. Ce sujet à une alimentation hyperglucidique, riche en fruits (fructose), l''apport alcoolique est également important.', false, true, 'Parmi les affections suivantes, laquelle(lesquelles) vous parai(ssen)t susceptible(s) d''exprimer l''hyperuricémie ?', '[{"l":"A","t":"Déficit en hypoxanthine guanine phosphoribosyltransgérase","c":false},{"l":"B","t":"Glycogénose de type I","c":false},{"l":"C","t":"Syndrome myéloprolifératif","c":false},{"l":"D","t":"Néphroangiosclérose","c":false},{"l":"E","t":"Hyperuricémie idiopathique (goutte commune)","c":true}]'::jsonb, 'Toutes les pathologies citées s''accompagnent d''une hypéruricémie mais également d''autres signes qui sont absents ici.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2298, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Chez un homme de 38 ans, on découvre une uricémie à 85 mg/l ( méthode a l''uricase). Il n''a jamais fait de crises goutteuses, son poids est de 83 kg, sa taille de 168 cm, ses chiffres tensionnels de 170/100 mm Hg ; le reste de l''examen clinique est sans particularités. Il n''a pas de protéinurie ; l''examen du fond d''oeil est normal ; l''hémogramme est sans particularité. La créatinine plasmatique est à 10 micromol/l. Il n''y a pas de lithiase urique ; l''uraturie est demandée. Ce sujet à une alimentation hyperglucidique, riche en fruits (fructose), l''apport alcoolique est également important.', false, true, 'Vous conclurez que le sujet est hypo-uraturique si son uraturie est :', '[{"l":"A","t":"Comprise entre 10 et 50 mg/24 h","c":false},{"l":"B","t":"Comprise entre 50 et 200 mg/24 h","c":true},{"l":"C","t":"Comprise entre 300 et 600 mg/24 h","c":false},{"l":"D","t":"Comprise entre 800 et 2000 mg/24 h","c":false},{"l":"E","t":"Comprise entre 3000 et 6000 mg/24 h","c":false}]'::jsonb, 'L''uraturie normale est comprise entre 350 et 600 mg/24 h.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2299, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Chez un homme de 38 ans, on découvre une uricémie à 85 mg/l ( méthode a l''uricase). Il n''a jamais fait de crises goutteuses, son poids est de 83 kg, sa taille de 168 cm, ses chiffres tensionnels de 170/100 mm Hg ; le reste de l''examen clinique est sans particularités. Il n''a pas de protéinurie ; l''examen du fond d''oeil est normal ; l''hémogramme est sans particularité. La créatinine plasmatique est à 10 micromol/l. Il n''y a pas de lithiase urique ; l''uraturie est demandée. Ce sujet à une alimentation hyperglucidique, riche en fruits (fructose), l''apport alcoolique est également important.', false, true, 'L''enquête diététique est en faveur d''une alimentation apportant quotidiennement 3200 Kcal dont 63 % d''hydrate de carbone, 8 % de protides. 130 g d''alcool. Il boit quotidiennement 2,5 litres d''eau. Quel(s) facteur(s) alimentaire(s) vous parai(ssen)t susceptible(s) d''avoir favorisé l''hyperuricémie', '[{"l":"A","t":"Alimentation hypercalorique","c":true},{"l":"B","t":"Alimentation hyperglucidique","c":true},{"l":"C","t":"Alimentation hyperprotidique","c":false},{"l":"D","t":"Excès d''apport en alcool","c":true},{"l":"E","t":"Insuffisance d''apport hydrique","c":false}]'::jsonb, 'Le régime de l''hyperuricémie consiste à faire maigrir les obèses, supprimer les aliments riches en purines, traiter une dyslipidémie et supprimer les boissons alcoolisées.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2300, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Chez un homme de 38 ans, on découvre une uricémie à 85 mg/l ( méthode a l''uricase). Il n''a jamais fait de crises goutteuses, son poids est de 83 kg, sa taille de 168 cm, ses chiffres tensionnels de 170/100 mm Hg ; le reste de l''examen clinique est sans particularités. Il n''a pas de protéinurie ; l''examen du fond d''oeil est normal ; l''hémogramme est sans particularité. La créatinine plasmatique est à 10 micromol/l. Il n''y a pas de lithiase urique ; l''uraturie est demandée. Ce sujet à une alimentation hyperglucidique, riche en fruits (fructose), l''apport alcoolique est également important.', false, true, 'Quelle(s) mesure(s) thérapeutique(s) vous parai(ssen)t actuellement justifiée(s) ?', '[{"l":"A","t":"Régime normocalorique équilibré","c":true},{"l":"B","t":"Evictions des aliments purinophores","c":true},{"l":"C","t":"Majoration de l''activité physique","c":true},{"l":"D","t":"Prescription d''un diurétique (Thiazidique)","c":false},{"l":"E","t":"Prescription de benziodarone (Amplivix®)","c":true}]'::jsonb, 'Il n''est pas prouvé que traiter une hyperuricémie asymptomatique inférieure à 100 mg par jour serve à quelque chose, cependant ce patient présente des facteurs de risques cardiovasculaires qu''il est bon de traiter. Les diurétiques thiazidiques sont à éviter car hyperuricémiants.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2301, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'Quel examen a permis d''affirmer le diagnostic d''accès de goutte dans ce contexte ?', '[{"l":"A","t":"Radiographie des mains et poignets de face","c":false},{"l":"B","t":"Etude du liquide synovial obtenu par ponction du genou","c":true},{"l":"C","t":"Biopsie de synoviale","c":false},{"l":"D","t":"Radiographie du genou face et profil","c":false},{"l":"E","t":"Dosage de la xanthinémie","c":false}]'::jsonb, 'Le diagnostic peut être suspecté sur le terrain, et il est affirmé par la ponction articulaire qui retrouve un liquide inflammatoire contenant des microcristaux à bouts pointus.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2302, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'L''accès de goutte bi-articulaire dans ce contexte est dû à :', '[{"l":"A","t":"Une intolérance médicamenteuse à l''allopurinol","c":false},{"l":"B","t":"Une posologie insuffisante d''allopurinol","c":false},{"l":"C","t":"L''augmentation de la xanthinémie sous allopurinol","c":false},{"l":"D","t":"L''absence de prescription de colchicine ou d''un antinflammatoire non stéroïdien","c":true},{"l":"E","t":"Une mauvaise observance du malade au traitement","c":false}]'::jsonb, 'La crise de goutte est secondaire à la mobilisation du pool d''acide urique, conséquence du traitement.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2303, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'Parmi les traitements suivants, quel est celui qui vous parait le plus approprie à cette situation :', '[{"l":"A","t":"Arrêt définitif de l''allopurinol, colchicine 3 mg. par jour pendant 3 jours, puis 1 mg chaque soir en permanence","c":false},{"l":"B","t":"Colchicine : 3 mg. par jour pendant 2 jours, 2 mg pendant 2 jours puis 1 mg, par jour Allopurinol 400 mg/jour en traitement de fond","c":false},{"l":"C","t":"Un antiinflammatoire non stéroïdien pendant 5 jours et benzéromarone (Désuric®) 100 mg. par jour en traitement de fond","c":false},{"l":"D","t":"Cortancyl ® (Deltacortisone) 15 m par jour pendant 5 jours et poursuite de l''allopurinol 300 mg. par jour en traitement de fond","c":false},{"l":"E","t":"Un antinflammatoire non stéroïdien pendant 5 jours et allopurinol 300 mg. et colchicine 1 mg par jour en traitement de fond","c":true}]'::jsonb, 'L''A.I.N.S. est donné dans le but de faire céder la crise de goutte ; on aurait pu donner de la colchicine à la dose de 3 mg/j pendant 3 jours.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2304, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'Quelle est la nature vraisemblable des tuméfactions blanchâtres de la pulpe des doigts observées chez ce malade ?', '[{"l":"A","t":"Concrétion calcaire d''un syndrome de Thibierge Weissenbach","c":false},{"l":"B","t":"Nodule rhumatoïde","c":false},{"l":"C","t":"Nodule d''une vascularite cutanée induite par l''allopurinol","c":false},{"l":"D","t":"Concrétion d''urate de sodium","c":true},{"l":"E","t":"Dépôt de xanthine","c":false}]'::jsonb, 'Il s''agit à l''évidence d''un tophus goutteux dont les sièges d''élection sont le pavillon de l''oreille, le voisinage des articulations du coude, des mains et des pieds, et les tendons (tendon d''Achille).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2305, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'La goutte, dont souffre ce patient, peut-elle être considérée, en fonction des éléments fournis, comme :', '[{"l":"A","t":"Une goutte secondaire à une insuffisance rénale","c":false},{"l":"B","t":"Une goutte secondaire à une hémopathie","c":false},{"l":"C","t":"Une goutte saturnine","c":false},{"l":"D","t":"Une goutte par déficit en hypoxanthine guanine phosphoribosyltransférase","c":false},{"l":"E","t":"Une goutte primitive (hyperformatrice)","c":true}]'::jsonb, 'Il s''agit en effet d''une goutte tardive (50 ans), sans étiologie évidente.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2306, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', 'Un homme de 60 ans, mesurant 1 m 70 et pesant 68 kg, souffrait depuis 10 ans d''accès de goutte. Depuis quelques mois, sont apparues des tuméfactions blanchâtres siégeant sur la pulpe des doigts. Depuis trois semaines. il est traité par 300 mg de Zyloric®. Avant la mise au traitement, l''uricémie était de 600 micromol/l(101 mg) et l''uraturie de 24 h à 60 mmol (1010mg), cholestérol à 6 mmol/l, triglycérides à 2 mmol, uraturie : 3 mmol/24 h, créatinine : 78 micromol/l. Un contrôle de l''uricémie et de l''uraturie à la 3ème semaine de traitement par 300 mg de Zyloric donne les résultats suivants : uricémie = 320 micromol, uraturie = 3 mmol/24 h, créatinine = 78 micromol/l. Le soir même de ce dosage, le malade souffre brutalement d''une douleur du genou droit et du poignet gauche. Les deux articulations sont gonflées, chaudes, le poignet est rouge et le genou distendu par un épanchement intra-articulaire. Le diagnostic d''accès de goutte bi-articulaire est rapidement affirmé.', false, true, 'L''uricémie après 3 semaines de traitement par 300 mg d''allopurinol est passée de 600 micromol/l à 320 micromol/l. Cet effet hypouricémiant est dû :', '[{"l":"A","t":"A une inhibition de la réabsorption tubulaire de l''acide urique","c":false},{"l":"B","t":"A une diminution de l''absorption intestinale des purines","c":false},{"l":"C","t":"A une diminution de la dégradation des purines","c":false},{"l":"D","t":"A une inhibition de la xanthine oxydase et à une diminution de la purinosynthèse de novo","c":true},{"l":"E","t":"A la transformation de l''acide urique en allantoïne par stimulation de l''uricase","c":false}]'::jsonb, 'L''allopurinol est un inhibiteur de la xanthine-oxydase.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2307, 9, 'Rhumatologie', 'Spondylarthrites', 'Un homme de 30 ans alcoolo-tabagique chronique souffre depuis 2 ans de sciatalgies bilatérales à bascule, de cervicalgies, de talalgies, d''intensité maximale le matin au réveil, évoluant par poussées et depuis 15 jours d''une arthrite du genou droit. L''interrogatoire retrouve des antécédents d''oligoarthrite fixe pendant deux mois à l''âge de 25 ans, de diarrhée chronique avec plusieurs épisodes de rectorragie, d''uvéite antérieure récidivante. L''examen clinique révèle une raideur lombaire globale, une douleur à la mobilisation des sacro-iliaques, un herpès labial, un souffle diastolique 2/6 parasternal gauche et une hépatomégalie ferme. La température est à 37°, lexamen ophtalmologique révèle une névrite optique. Les radiographies objectivent des érosions des articulations sacro-iliaques, une érosion des angles anterosupérieurs des 1ères et 2èmes vertèbres lombaires, une discopathie L5 -S1 avec ostéophytose, une coxa plana et un aspect hérissé des calcanéums. Les examens biologiques montrent une NFS normale, une VS à 10 mm à la 1ère h. Les hémocultures sont négatives. Le diagnostic de pelvispondylite rhumatismale est posé.', false, true, 'Parmi les antécédents suivants retrouvés à l''interrogatoire, vous retenez en faveur du diagnostic de pelvispondylite rhumatismale :', '[{"l":"A","t":"Oligoarthrite fixe","c":true},{"l":"B","t":"Hépatite virale","c":false},{"l":"C","t":"Talalgies","c":true},{"l":"D","t":"Uvéite antérieure récidivante","c":true},{"l":"E","t":"Urticaire récidivante","c":false}]'::jsonb, 'L''atteinte caractéristique de la maladie est rachidienne et axiale mais le début peut se faire par une oligoarthrite.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2308, 9, 'Rhumatologie', 'Spondylarthrites', 'Un homme de 30 ans alcoolo-tabagique chronique souffre depuis 2 ans de sciatalgies bilatérales à bascule, de cervicalgies, de talalgies, d''intensité maximale le matin au réveil, évoluant par poussées et depuis 15 jours d''une arthrite du genou droit. L''interrogatoire retrouve des antécédents d''oligoarthrite fixe pendant deux mois à l''âge de 25 ans, de diarrhée chronique avec plusieurs épisodes de rectorragie, d''uvéite antérieure récidivante. L''examen clinique révèle une raideur lombaire globale, une douleur à la mobilisation des sacro-iliaques, un herpès labial, un souffle diastolique 2/6 parasternal gauche et une hépatomégalie ferme. La température est à 37°, lexamen ophtalmologique révèle une névrite optique. Les radiographies objectivent des érosions des articulations sacro-iliaques, une érosion des angles anterosupérieurs des 1ères et 2èmes vertèbres lombaires, une discopathie L5 -S1 avec ostéophytose, une coxa plana et un aspect hérissé des calcanéums. Les examens biologiques montrent une NFS normale, une VS à 10 mm à la 1ère h. Les hémocultures sont négatives. Le diagnostic de pelvispondylite rhumatismale est posé.', false, true, 'Parmi les signes cliniques suivants, vous retenez en faveur du diagnostic de pelvispondylite rhumatismale ?', '[{"l":"A","t":"Sciatiques bilatérales à bascule","c":true},{"l":"B","t":"Herpès labial","c":false},{"l":"C","t":"Souffle diastolique","c":true},{"l":"D","t":"Hépatomégalie","c":false},{"l":"E","t":"Névrite optique","c":false}]'::jsonb, 'Les sciatiques bilatérales à bascule doivent toujours faire rechercher cette maladie chez un homme jeune. L''insuffisance aortique est rare mais doit toujours être recherchée en raison de sa gravité.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2309, 9, 'Rhumatologie', 'Spondylarthrites', 'Un homme de 30 ans alcoolo-tabagique chronique souffre depuis 2 ans de sciatalgies bilatérales à bascule, de cervicalgies, de talalgies, d''intensité maximale le matin au réveil, évoluant par poussées et depuis 15 jours d''une arthrite du genou droit. L''interrogatoire retrouve des antécédents d''oligoarthrite fixe pendant deux mois à l''âge de 25 ans, de diarrhée chronique avec plusieurs épisodes de rectorragie, d''uvéite antérieure récidivante. L''examen clinique révèle une raideur lombaire globale, une douleur à la mobilisation des sacro-iliaques, un herpès labial, un souffle diastolique 2/6 parasternal gauche et une hépatomégalie ferme. La température est à 37°, lexamen ophtalmologique révèle une névrite optique. Les radiographies objectivent des érosions des articulations sacro-iliaques, une érosion des angles anterosupérieurs des 1ères et 2èmes vertèbres lombaires, une discopathie L5 -S1 avec ostéophytose, une coxa plana et un aspect hérissé des calcanéums. Les examens biologiques montrent une NFS normale, une VS à 10 mm à la 1ère h. Les hémocultures sont négatives. Le diagnostic de pelvispondylite rhumatismale est posé.', false, true, 'Parmi les signes radiologiques suivants, vous retenez en faveur du diagnostic de pelvispondylite rhumatismale ?', '[{"l":"A","t":"Erosions des articulations sacro-iliaques","c":true},{"l":"B","t":"Erosions des angles antéro-supérieurs des 1ère et 2ème vertèbres lombaires","c":true},{"l":"C","t":"Discopathie L5-S1 avec ostéophytose","c":false},{"l":"D","t":"Coxa plana","c":false},{"l":"E","t":"Aspect hérisse des calcanéums","c":true}]'::jsonb, 'Ces signes témoignent d''une sacrolite stade 1, d''une spondylite antérieure de Romanus et d''une calcanéite typique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2310, 9, 'Rhumatologie', 'Spondylarthrites', 'Un homme de 30 ans alcoolo-tabagique chronique souffre depuis 2 ans de sciatalgies bilatérales à bascule, de cervicalgies, de talalgies, d''intensité maximale le matin au réveil, évoluant par poussées et depuis 15 jours d''une arthrite du genou droit. L''interrogatoire retrouve des antécédents d''oligoarthrite fixe pendant deux mois à l''âge de 25 ans, de diarrhée chronique avec plusieurs épisodes de rectorragie, d''uvéite antérieure récidivante. L''examen clinique révèle une raideur lombaire globale, une douleur à la mobilisation des sacro-iliaques, un herpès labial, un souffle diastolique 2/6 parasternal gauche et une hépatomégalie ferme. La température est à 37°, lexamen ophtalmologique révèle une névrite optique. Les radiographies objectivent des érosions des articulations sacro-iliaques, une érosion des angles anterosupérieurs des 1ères et 2èmes vertèbres lombaires, une discopathie L5 -S1 avec ostéophytose, une coxa plana et un aspect hérissé des calcanéums. Les examens biologiques montrent une NFS normale, une VS à 10 mm à la 1ère h. Les hémocultures sont négatives. Le diagnostic de pelvispondylite rhumatismale est posé.', false, true, 'Pour rechercher une affection pouvant être associée à la spondylarthropathie chez ce patient, vous demandez :', '[{"l":"A","t":"Recherche de l''antigène HLA B 27","c":false},{"l":"B","t":"Wirsungographie","c":false},{"l":"C","t":"Ponction-biopsie sacro-iliaque","c":false},{"l":"D","t":"Coloscopie","c":true},{"l":"E","t":"Transit du grêle","c":true}]'::jsonb, 'Etant donné les antécédents, on recherche une cause digestive à cette spondylarthropathie (Crohn ou R.C.H.).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2311, 9, 'Rhumatologie', 'Spondylarthrites', 'Un homme de 30 ans alcoolo-tabagique chronique souffre depuis 2 ans de sciatalgies bilatérales à bascule, de cervicalgies, de talalgies, d''intensité maximale le matin au réveil, évoluant par poussées et depuis 15 jours d''une arthrite du genou droit. L''interrogatoire retrouve des antécédents d''oligoarthrite fixe pendant deux mois à l''âge de 25 ans, de diarrhée chronique avec plusieurs épisodes de rectorragie, d''uvéite antérieure récidivante. L''examen clinique révèle une raideur lombaire globale, une douleur à la mobilisation des sacro-iliaques, un herpès labial, un souffle diastolique 2/6 parasternal gauche et une hépatomégalie ferme. La température est à 37°, lexamen ophtalmologique révèle une névrite optique. Les radiographies objectivent des érosions des articulations sacro-iliaques, une érosion des angles anterosupérieurs des 1ères et 2èmes vertèbres lombaires, une discopathie L5 -S1 avec ostéophytose, une coxa plana et un aspect hérissé des calcanéums. Les examens biologiques montrent une NFS normale, une VS à 10 mm à la 1ère h. Les hémocultures sont négatives. Le diagnostic de pelvispondylite rhumatismale est posé.', false, true, 'Quels(s) traitement(s) pouvez-vous proposer pour la pelvispondylite rhumatismale chez ce patient ?', '[{"l":"A","t":"Antiinflammatoires non stéroïdiens","c":true},{"l":"B","t":"Sels d''or","c":false},{"l":"C","t":"D-pénicillamine","c":false},{"l":"D","t":"Antimalariques de synthèse","c":false},{"l":"E","t":"Infiltration de corticoïdes du genou","c":true}]'::jsonb, 'L''infiltration du genou permettra de résoudre le problème local et la dose d''A.I N.S. sera adaptée à la symptomatologie rachidienne et calcanéenne.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2312, 9, 'Rhumatologie', 'Maladie de Paget', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Parmi les diagnostics suivants, lequel (lesquels) aurai(en)t pu être initialement discuté(s) devant ces plages de condensation osseuse :', '[{"l":"A","t":"Métastase de cancer de la prostate","c":true},{"l":"B","t":"Ostéodystrophie rénale","c":false},{"l":"C","t":"Spondylarthrite ankylosante","c":false},{"l":"D","t":"Maladie de Hodgkin","c":true},{"l":"E","t":"Intoxication fluorée chronique","c":false}]'::jsonb, 'L''image de vertèbre ivoire fait discuter classiquement ces trois diagnostics.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2313, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Quel(s) est(sont) parmi les nuances radiologiques suivantes, celle(s) qui orienterait(ent) plutôt vers une maladie de Paget ?', '[{"l":"A","t":"Aspect en cadre de la 4ème vertèbre lombaire","c":true},{"l":"B","t":"Absence d''élargissement du corps de cette vertèbre","c":false},{"l":"C","t":"Aspect homogène de la condensation osseuse","c":false},{"l":"D","t":"Début de protrusion acétabulaire","c":true},{"l":"E","t":"Epaississement de la branche ilio-pubienne","c":true}]'::jsonb, 'La condensation vertébrale est classiquement maximale en périphérie avec agrandissement du corps vertébral', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2314, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Dans le bilan biologique de ce malade, quel(s) est(sont) le(s argument(s) qui écarteraient à priori le diagnostic de la maladie de Paget ?', '[{"l":"A","t":"Vitesse de sédimentation à 72 millimètre à la 1ère heure","c":true},{"l":"B","t":"Calcémie à 2,10 mmol/l (84 mg pour mille)","c":false},{"l":"C","t":"Phosphatases alcalines à 184 unités/l (N inférieure à 50u)","c":false},{"l":"D","t":"Phosphatases acides à 56 unités/l (N inférieure à 5u)","c":true},{"l":"E","t":"Calciurie a 250 mg par 24 heures","c":false}]'::jsonb, 'La vitesse de sédimentation et les marqueurs des cancers doivent être normaux dans la maladie de Paget. La calciurie peut être élevée en période ostéolytique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2315, 26, 'Rhumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Le diagnostic de maladie de Paget étant affirmé, quelle(s) complication(s) est(sont) à redouter à long terme, compte tenu des localisations observées chez ce patient ?', '[{"l":"A","t":"Coxopathie droite","c":true},{"l":"B","t":"Insuffisance cardiaque","c":false},{"l":"C","t":"Paraplégie spasmodique","c":false},{"l":"D","t":"Dégénérescence sarcomateuse","c":true},{"l":"E","t":"Fracture spontanée","c":false}]'::jsonb, 'La dégénérescence sarcomateuse bien que rare (1%) peut s''observer dans toutes les localisations. La coxopathie pagétique est présente dans 50% des cas et elle est de type protrusive.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2316, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Parmi les médicaments suivants, lequel (lesquels) peut (peuvent) être utilisé(s) pour soulager rapidement les douleurs osseuses de ce malade ?', '[{"l":"A","t":"Acide acétylsalicylique (2 g par jour)","c":true},{"l":"B","t":"Prednisone (30 mg par jour)","c":false},{"l":"C","t":"Vitamine B12 (15000 unités par jour)","c":false},{"l":"D","t":"Calcium (1 g par jour)","c":false},{"l":"E","t":"Indométacine (100 mg par jour)","c":true}]'::jsonb, 'Non commentée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2317, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'Comme traitement de fond. on pourra retenir chez ce malade :', '[{"l":"A","t":"Calcitonine : 2 unités, 3 fois par semaine pendant 4 mois","c":false},{"l":"B","t":"Calcitonine : 100 unités, 3 fois par semaines pendant 4 mois","c":true},{"l":"C","t":"Stérogyl® (vit D2) : 15 mg/jour pendant 1 mois","c":false},{"l":"D","t":"Didronel® (Etidronate) : 2 comprimés par jour pendant 6 mois","c":true},{"l":"E","t":"Didronel® (Etidronate) : 6 comprimés par jour pendant 6 mois","c":false}]'::jsonb, 'La calcitonine agit rapidement mais elle n''est pas toujours bien supportée. Le Didronel® agit plus lentement avec une certaine rémanence d''action à la dose de 5 à 10 mg/kg/j en cures de 6 mois.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2318, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un homme de 76 ans, 65 kg et 1.65 m souffre depuis 2 mois de lombalgies sans irradiation et de douleurs de la région de la hanche droite irradiant à la face antérieure de la cuisse, aggravées à la station debout et à la marche. A l''examen clinique, il n''existe ni limitation des mouvements du rachis et de la hanche, ni signe, neurologique objectif, l''état général est bien conserveé Sur les radiographies du rachis lombaire et du bassin, on constate une ostéocondensation de la quatrième vertèbre lombaire, de l''aile iliaque et de la ligne innominée droite. Un diagnostic de maladie de Paget est retenu.', false, true, 'L''efficacité de ce traitement sera jugée sur :', '[{"l":"A","t":"La diminution des douleurs","c":true},{"l":"B","t":"La régression de l''ostéocondensation radiologique","c":false},{"l":"C","t":"L''augmentation de la calciurie","c":false},{"l":"D","t":"La diminution des phosphatases alcalines","c":true},{"l":"E","t":"L''augmentation de l''hydroxyprolinurie","c":false}]'::jsonb, 'L''efficacité du traitement se juge sur la disparition des douleurs osseuses et la normalisation des paramètres biologiques.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2319, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans, sans antécédents particuliers, tombe à la suite d''un faux pas dans sa salle de bain sur la paume de la main droite, le bras en avant. Elle ressent une vive douleur du poignet et une impotence fonctionnelle de cette articulation. Vous la voyez une heure après le traumatisme, elle maintient son membre supérieur droit à l''aide de son avant-bras gauche; le poignet droit est gonflé.', false, true, 'Vous suspectez le diagnostic de fracture de Pouteau-Colles sur :', '[{"l":"A","t":"L''âge de la blessée","c":true},{"l":"B","t":"La chute sur la paume","c":true},{"l":"C","t":"Le sexe féminin","c":true},{"l":"D","t":"La déformation en ventre de fourchette du poignet droit","c":false},{"l":"E","t":"L''inclinaison en valgus du poignet droit","c":true}]'::jsonb, 'La fracture de Pouteau-Colles est une fracture de l''extrémité inférieure du radius, sus-articulaire, dont le mécanisme est le plus souvent une chute sur la face antérieure du poignet en hyperextension et pronation (B). Le déplacement est une bascule postérieure en dos de fourchette (D évoque la fracture de Goyrand-Smith avec ascension de la styloïde radiale) (E). Elle survient préférentiellement chez la femme âgée (ostéoporose post-ménopausique) mais se voit à tout âge (A,C).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2320, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans, sans antécédents particuliers, tombe à la suite d''un faux pas dans sa salle de bain sur la paume de la main droite, le bras en avant. Elle ressent une vive douleur du poignet et une impotence fonctionnelle de cette articulation. Vous la voyez une heure après le traumatisme, elle maintient son membre supérieur droit à l''aide de son avant-bras gauche; le poignet droit est gonflé.', false, true, 'A l''examen clinique, vous maintenez votre suspicion en trouvant :', '[{"l":"A","t":"Une tuméfaction du poignet droit","c":true},{"l":"B","t":"Une douleur métaphysaire","c":true},{"l":"C","t":"Une verticalisation de la ligne bistyloïdienne","c":false},{"l":"D","t":"Une dépression sus-articulaire dorsale","c":true},{"l":"E","t":"La possibilité de quelques mouvements discret","c":true}]'::jsonb, 'B. E - La fracture est sus articulaire. La douleur élective est donc métaphysaire et le poignet relativement libre. C - Elle est horizontalisée par l''ascension de la styloïde radiale ( la radio confirme l''ascension de la ligne de Laugier). D - La dépression correspond à la zone de comminution postérieure, en amont du dos de fourchette.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2321, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans, sans antécédents particuliers, tombe à la suite d''un faux pas dans sa salle de bain sur la paume de la main droite, le bras en avant. Elle ressent une vive douleur du poignet et une impotence fonctionnelle de cette articulation. Vous la voyez une heure après le traumatisme, elle maintient son membre supérieur droit à l''aide de son avant-bras gauche; le poignet droit est gonflé.', false, true, 'La radiographie face et profil du poignet droit confirme le diagnostic de fracture de Pouteau-Colles parce que :', '[{"l":"A","t":"Le trait de fracture est articulaire","c":false},{"l":"B","t":"Il existe une bascule postérieure du fragment distal","c":true},{"l":"C","t":"Le profil montre une comminution antérieure","c":false},{"l":"D","t":"De face on trouve une translation externe du fragment distal","c":true},{"l":"E","t":"Il existe une fracture de la styloïde cubitale","c":false}]'::jsonb, 'La fracture est par définition extra-articulaire (contre A). Le déplacement est par définition B + D. C - La comminution est postérieure. E - L''association constitue la fracture de Gerard-Marchant.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2322, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans, sans antécédents particuliers, tombe à la suite d''un faux pas dans sa salle de bain sur la paume de la main droite, le bras en avant. Elle ressent une vive douleur du poignet et une impotence fonctionnelle de cette articulation. Vous la voyez une heure après le traumatisme, elle maintient son membre supérieur droit à l''aide de son avant-bras gauche; le poignet droit est gonflé.', false, true, 'Le traitement orthopédique va être réalisé de la façon suivante :', '[{"l":"A","t":"Réduction avant la sixième heure","c":true},{"l":"B","t":"Réduction sans aucune anesthésie","c":false},{"l":"C","t":"Réduction par traction douce sur le pouce","c":true},{"l":"D","t":"Réduction par pression manuelle à direction antéro-postérieure","c":false},{"l":"E","t":"Contention plâtrée brachio-antébrachiale avec légère extension du poignet","c":false}]'::jsonb, 'La manoeuvre de réduction est une traction progressive dans l''axe sous anesthésie (locale, loco-régionale ou générale) jusqu''à ce que la corticale antérieure du fragment distal vienne "accrocher" la corticale antérieure du fragment proximal, en avant de celle-ci. La réduction de la corticale antérieure est fondamentale, le désengrenement de la comminution postérieure découle de ce geste. D. E - Pression antérieure et contention en extension reproduisent la bascule postérieure que l''on cherche au contraire à corriger. La contention se fait par un plâtre brachio-palmaire en légère flexion et inclinaison cubitale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2323, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 60 ans, sans antécédents particuliers, tombe à la suite d''un faux pas dans sa salle de bain sur la paume de la main droite, le bras en avant. Elle ressent une vive douleur du poignet et une impotence fonctionnelle de cette articulation. Vous la voyez une heure après le traumatisme, elle maintient son membre supérieur droit à l''aide de son avant-bras gauche; le poignet droit est gonflé.', false, true, 'Le traitement chirurgical primaire de cette fracture de Pouteau-Colles :', '[{"l":"A","t":"Est indiqué dans tous les cas","c":false},{"l":"B","t":"Peut être réalisé par embrochage","c":true},{"l":"C","t":"Peut être réalisé avec un fixateur externe","c":false},{"l":"D","t":"Peut être réalisé par cerclage","c":false},{"l":"E","t":"Doit comporter une ostéotomie radiale systématique","c":false}]'::jsonb, 'L''indication chirurgicale (brochage) est posée sur l''importance du déplacement et l''instabilité de la fracture.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2324, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un enfant de 4 ans, quelques heures après un traumatisme bénin du genou, accuse une douleur lancinante de l''extrémité inférieure du fémur associée à une élévation thermique à 39°5. Vous soupçonnez une ostéomyélite aiguë', false, true, 'Quel(s) signe(s) clinique(s) recherchez-vous ?', '[{"l":"A","t":"Impotence fonctionnelle","c":true},{"l":"B","t":"Un flexum irréductible du genou","c":false},{"l":"C","t":"Une douleur localisée sur le condyle interne","c":false},{"l":"D","t":"Une douleur diaphyso-épiphysaire circulaire et transfixiante","c":true},{"l":"E","t":"La présence d''adénopathies inguinales","c":false}]'::jsonb, 'A - L''impotence fonctionnelle est totale, comparable à celle des fractures. B - L''articulation n''est pas atteinte (dans l''ostéomyélite vue au début). La mobilisation très douce est possible et indolore. Le flessum est antalgique. D - C''est la caractéristique la plus évocatrice à l''examen. C - N''a aucune spécificité. E - Il n''y en à pas.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2325, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Un garçon de cinq ans en parfaite santé rentre de l''école en boitillant : il se couche et refuse de se lever pour dîner. Il accuse une douleur diffuse de l''aine et du tiers supérieur de la cuisse gauche. On n''a noté aucun traumatisme particulier, aucune épidémie a l''école, aucun antécédent familial orthopédique particulier. A l''examen : pas de fièvre, pas de céphalée, pas de troubles digestifs, O.R.L. ou autres. Pas d''attitude vicieuse, pas de modification locale, mobilité de la hanche gauche un peu limitée et douloureuse.', false, true, 'Votre première prescription est :', '[{"l":"A","t":"Corticothérapie adaptée au poids de l''enfant","c":false},{"l":"B","t":"Antibiothérapie à spectre large","c":false},{"l":"C","t":"Vitaminothérapie D","c":false},{"l":"D","t":"Kinésithérapie","c":false},{"l":"E","t":"Mise au repos absolu en attendant le résultat des examens complémentaires","c":true}]'::jsonb, 'ABC - Aucun traitement spécifique tant que le diagnostic n''est pas assuré ("primum non nocere"). D - Est contre-indiqué : le repos absolu de l''articulation atteinte s''impose car il peut s''agir à cet âge d''une arthrite septique (toujours y penser), d''une ostéochondrite ++ ou d''un "rhume de hanche" (diagnostic d''élimination).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2326, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Un garçon de cinq ans en parfaite santé rentre de l''école en boitillant : il se couche et refuse de se lever pour dîner. Il accuse une douleur diffuse de l''aine et du tiers supérieur de la cuisse gauche. On n''a noté aucun traumatisme particulier, aucune épidémie a l''école, aucun antécédent familial orthopédique particulier. A l''examen : pas de fièvre, pas de céphalée, pas de troubles digestifs, O.R.L. ou autres. Pas d''attitude vicieuse, pas de modification locale, mobilité de la hanche gauche un peu limitée et douloureuse.', false, true, 'Votre diagnostic de probabilité est :', '[{"l":"A","t":"Arthrite rhumatismale","c":false},{"l":"B","t":"Arthrite septique de la hanche","c":false},{"l":"C","t":"Poliomyélite","c":false},{"l":"D","t":"Ostéochondrite de la tête fémorale","c":true},{"l":"E","t":"Epiphysiolyse de la hanche","c":false}]'::jsonb, 'D - C''est le premier diagnostic à évoquer devant une boiterie du jeune enfant (3 à 6 ans), isolée sans facteur étiologique évident. B - Doit aussi toujours être éliminée (clinique plus bruyante, recherche de porte d''entrée). E - Terrain différent : garçon, adolescence, obésité ; attitude en flessum, rotation externe (les mobilités sont également diminuées).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2327, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Un garçon de cinq ans en parfaite santé rentre de l''école en boitillant : il se couche et refuse de se lever pour dîner. Il accuse une douleur diffuse de l''aine et du tiers supérieur de la cuisse gauche. On n''a noté aucun traumatisme particulier, aucune épidémie a l''école, aucun antécédent familial orthopédique particulier. A l''examen : pas de fièvre, pas de céphalée, pas de troubles digestifs, O.R.L. ou autres. Pas d''attitude vicieuse, pas de modification locale, mobilité de la hanche gauche un peu limitée et douloureuse.', false, true, 'La radiologie du bassin est normale, quel autre examen demandez-vous en priorité ?', '[{"l":"A","t":"Bilan électrophorèse sanguin","c":false},{"l":"B","t":"Examen scintigraphique","c":true},{"l":"C","t":"Echographie du petit bassin","c":false},{"l":"D","t":"Tomographie de l''extrémité supérieure du fémur","c":false},{"l":"E","t":"Recherche du groupe HLA B27","c":false}]'::jsonb, 'Les signes radiologiques sont retardés sur la clinique. La radio doit être comparative, comportant des incidences de face et de Lauenstein +++ et répétées. Les signes recherchés sont chronologiquement : 1 - Une image en "coup d''ongle" à la surface de l''épiphyse. 2 - Une densification du noyau épiphysaire fémoral supérieur. 3 - Une fragmentation du noyau. 4 - Puis un retour à la normale. La scintigraphie montre au début un trou de fixation, puis au cours de l''évolution une hyperfixation. Une scintigraphie normale élimine pratiquement le diagnostic.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2328, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', 'Un garçon de cinq ans en parfaite santé rentre de l''école en boitillant : il se couche et refuse de se lever pour dîner. Il accuse une douleur diffuse de l''aine et du tiers supérieur de la cuisse gauche. On n''a noté aucun traumatisme particulier, aucune épidémie a l''école, aucun antécédent familial orthopédique particulier. A l''examen : pas de fièvre, pas de céphalée, pas de troubles digestifs, O.R.L. ou autres. Pas d''attitude vicieuse, pas de modification locale, mobilité de la hanche gauche un peu limitée et douloureuse.', false, true, 'Si le diagnostic est confirmé, quel sera le traitement à cette phase initiale ?', '[{"l":"A","t":"Abstention thérapeutique","c":false},{"l":"B","t":"Traitement antalgique et anti-inflammatoire","c":false},{"l":"C","t":"Ponction articulaire, antibiothérapie et immobilisation plâtrée","c":false},{"l":"D","t":"Mise en décharge","c":true},{"l":"E","t":"Traitement chirurgical","c":false}]'::jsonb, 'Le traitement est la décharge (dont la durée reste un sujet de controverse), la surveillance radiologique répétée, et pour certains la traction au début. B - Traitement de la synovite transitoire ("rhume de hanche"). C - traitement de l''arthrite septique. E - traitement de certains cas d''épiphysiolyse.Parfois ostéotomies de recentrage dans certaines ostéochondrites. Et traitement des séquelles (coxa plana).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2329, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 45 ans consulte pour une polyarthrite d''apparition récente depuis quelques mois. Elle n''a reçu que des thérapeutiques non spécifiques symptomatiques. Les douleurs siègent aux poignets et aux mains,aux avant-pieds et plus modérément aux genoux. Les signes d''épanchement intra-articulaire sont nets, il n''y a pas de déformation apparente. La V.S. est à 60 mm/85 mm.', false, true, 'Parmi ces éléments, le(s)quel(s) représente(nt) des arguments d''orientation diagnostique en faveur d''une polyarthrite rhumatoïde ?', '[{"l":"A","t":"Atteintes symétriques des interphalangiennes proximales","c":true},{"l":"B","t":"Douleurs à la pression des têtes métatarsiennes","c":true},{"l":"C","t":"Ténosynovite des muscles extenseurs des doigts","c":true},{"l":"D","t":"Radiologiquement : érosion sur la tête de la phalange distale du Vème orteil","c":false},{"l":"E","t":"Sérologie rhumatoïde : Waaler-Rose au 1/16","c":false}]'::jsonb, 'La réaction est positive du 1/64e et l''érosion siège sur la tête du 5e métatarsien. Mais ces deux arguments sont généralement un peu plus tardifs.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2330, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 45 ans consulte pour une polyarthrite d''apparition récente depuis quelques mois. Elle n''a reçu que des thérapeutiques non spécifiques symptomatiques. Les douleurs siègent aux poignets et aux mains,aux avant-pieds et plus modérément aux genoux. Les signes d''épanchement intra-articulaire sont nets, il n''y a pas de déformation apparente. La V.S. est à 60 mm/85 mm.', false, true, 'Avant d''affirmer le diagnostic de polyarthrite rhumatoïde, il est nécessaire d''éliminer une maladie lupique. Parmi ces propositions, quelle(s) est (sont) celle(s) qui vous oriente(nt) en ce sens dans la mesure ou elle(s) se voie(nt) essentiellement dans la maladie lupique et beaucoup plus exceptionnellement dans la polyarthrite rhumatoïde ?', '[{"l":"A","t":"Présence d''anticorps antinucléaires à la dilution de 1/50","c":false},{"l":"B","t":"Découverte d''une leucopénieà la numération formule sanguine","c":true},{"l":"C","t":"Baisse du complément sérique mesuré par la valeur du CH50","c":true},{"l":"D","t":"Taux élevé de complexe immuns circulants","c":true},{"l":"E","t":"Positivité nette de l''immunofluorescence sur Crithidia Luciliae","c":true}]'::jsonb, 'Un faible taux de F.A.N peut se voir dans la P.R., si les anticorps anti-ADN natifs sont négatifs.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2331, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 45 ans consulte pour une polyarthrite d''apparition récente depuis quelques mois. Elle n''a reçu que des thérapeutiques non spécifiques symptomatiques. Les douleurs siègent aux poignets et aux mains,aux avant-pieds et plus modérément aux genoux. Les signes d''épanchement intra-articulaire sont nets, il n''y a pas de déformation apparente. La V.S. est à 60 mm/85 mm.', false, true, 'Chez cette patiente, vous pourrez redouter un certain nombre de manifestations extra articulaires compliquant la polyarthrite rhumatoïde. Laquelle(lesquelles) ?', '[{"l":"A","t":"Insuffisance ventriculaire gauche","c":false},{"l":"B","t":"Pleurésie séro-fibrineuse","c":true},{"l":"C","t":"Amylose","c":true},{"l":"D","t":"Pancréatite aiguë nécrotico hémorragique","c":false},{"l":"E","t":"Neuropathie périphérique sensitivomotrice","c":true}]'::jsonb, 'La pleurésie est la manifestation pleuro-pulmonaire la plus fréquente ; elle pose le problème d''une infection chez un malade souvent sous corticothérapie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2332, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 45 ans consulte pour une polyarthrite d''apparition récente depuis quelques mois. Elle n''a reçu que des thérapeutiques non spécifiques symptomatiques. Les douleurs siègent aux poignets et aux mains,aux avant-pieds et plus modérément aux genoux. Les signes d''épanchement intra-articulaire sont nets, il n''y a pas de déformation apparente. La V.S. est à 60 mm/85 mm.', false, true, 'Vous décidez de la prescription d''une chrysothérapie. Quel(s) est (sont) le(s) éléments qui représentent une contre-indication à son instauration ?', '[{"l":"A","t":"Hyperglycémie","c":false},{"l":"B","t":"Présence d''anticorps antiDNA","c":true},{"l":"C","t":"Protéinurie","c":true},{"l":"D","t":"Hypertriglycériémie","c":false},{"l":"E","t":"Hyperleucocytose","c":false}]'::jsonb, 'Le lupus est une contre-indication à la prescription de sels d''or et ceux-ci peuvent être la cause d''une aggravation ou d''une apparition d''une atteinte rénale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2333, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 45 ans consulte pour une polyarthrite d''apparition récente depuis quelques mois. Elle n''a reçu que des thérapeutiques non spécifiques symptomatiques. Les douleurs siègent aux poignets et aux mains,aux avant-pieds et plus modérément aux genoux. Les signes d''épanchement intra-articulaire sont nets, il n''y a pas de déformation apparente. La V.S. est à 60 mm/85 mm.', false, true, 'La chrysothérapie ne pouvant être instaurée, quelle(s) autre(s) mesure(s) thérapeutique(s) vous semble(nt) correcte(s) dans le traitement de cette polyarthrite ?', '[{"l":"A","t":"Traitement par la D-Penicillamine","c":true},{"l":"B","t":"Prescription d''anti inflammatoires non stéroïdiens","c":true},{"l":"C","t":"Corticothérapie générale","c":false},{"l":"D","t":"Immunodépresseurs","c":false},{"l":"E","t":"Infiltrations intra-articulaires cortisoniques hebdomadaires","c":false}]'::jsonb, 'Si les sels d''or ne peuvent être utilisés ou sont mal supportés, la D-pénicillamine peut être prescrite en traitement de fond. Les A.I.N.S. sont un appoint thérapeutique non négligeable lors des fluctuations de la maladie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2334, 35, 'Traumatologie', 'Syndrome du canal carpien', 'Vous êtes interne aux urgences, vous recevez une dame âgée de 70 ans ayant fait une chute sur le poignet en hyperextension. Son poignet est déformé et douloureux; l''impotence fonctionnelle est totale.', false, true, 'Votre prescription radiologique d''emblée comporte :', '[{"l":"A","t":"Un poignet de face","c":true},{"l":"B","t":"Une incidence du canal carpien","c":false},{"l":"C","t":"Des cliches fonctionnels du poignet","c":false},{"l":"D","t":"Un profil strict du poignet","c":true},{"l":"E","t":"Des 3/4 du poignet","c":false}]'::jsonb, 'Bons clichés de débrouillage. B - Inutile en urgence ; intérêt dans le syndrome du canal carpien secondaire ; à la recherche secondaire d''un cal vicieux. C - Dangereux. E - Pas de première intention.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2335, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Vous êtes interne aux urgences, vous recevez une dame âgée de 70 ans ayant fait une chute sur le poignet en hyperextension. Son poignet est déformé et douloureux; l''impotence fonctionnelle est totale.', false, true, 'En faveur d''une fracture de Pouteau-Colles, vous retenez :', '[{"l":"A","t":"Une bascule postérieure de l''épiphyse radiale","c":true},{"l":"B","t":"Une ascension de l''épiphyse radiale","c":true},{"l":"C","t":"Un trait de fracture sus-articulaire","c":true},{"l":"D","t":"Une translation latérale interne de l''épiphyse radiale","c":false},{"l":"E","t":"Une comminution postérieure du trait de fracture","c":true}]'::jsonb, 'Font partie de la définition. La bascule est postérieure (A) entraînant une comminution postérieure (E) et l''aspect évocateur en dos de fourchette. De face, l''épiphyse radiale subit une translation externe avec ascension de la styloïde radiale (B), horizontalisation de la ligne bistyloïdienne (ligne de Laugier radiologique).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2336, 43, 'Traumatologie', 'Syndrome des loges', 'Vous êtes interne aux urgences, vous recevez une dame âgée de 70 ans ayant fait une chute sur le poignet en hyperextension. Son poignet est déformé et douloureux; l''impotence fonctionnelle est totale.', false, true, 'Il est fréquent qu''une telle fracture se complique immédiatement de :', '[{"l":"A","t":"Une rupture du nerf médian","c":false},{"l":"B","t":"Un syndrome de Volkmann","c":false},{"l":"C","t":"Une ouverture du foyer de fracture","c":false},{"l":"D","t":"Une compression de l''artère radiale","c":false},{"l":"E","t":"Aucune de ces propositions","c":true}]'::jsonb, 'A - Le nerf médian est relativement protégé dans ce type de fracture. Par contre, il peut être comprimé de façon chronique par un cal vicieux. B - Le syndrome de loge après fracture de P.C. est rare car à l''extrémité inférieure, il y a peu d''hématome musculaire. Par contre, il est à éviter sous plâtre +++. C - Rare. D - N''est pas menacée par ce mécanisme (tassement postérieur).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2337, 29, 'Traumatologie', 'Algoneurodystrophie', 'Vous êtes interne aux urgences, vous recevez une dame âgée de 70 ans ayant fait une chute sur le poignet en hyperextension. Son poignet est déformé et douloureux; l''impotence fonctionnelle est totale.', false, true, 'Les 3 complications secondaires les plus fréquentes sont :', '[{"l":"A","t":"Une pseudarthrose","c":false},{"l":"B","t":"Un cal vicieux","c":true},{"l":"C","t":"Une raideur de la main et des doigts","c":true},{"l":"D","t":"Une algodystrophie réflexe de la main","c":true},{"l":"E","t":"Une ostéite","c":false}]'::jsonb, 'A - Exceptionnelle car siège métaphyso- épiphysaire. B - Fréquent surtout après traitement orthopédique (difficulté de réduction, déplacement secondaire en bascule postérieure++). C - Surtout après immobilisation plâtrée chez les sujets âgés. D - Classique. Non spécifique de ce type de fracture (traitement : repos articulaire, vessie de glace locale, calcitonine). E - Rare. Surtout après traitement chirurgical.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2338, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Vous êtes interne aux urgences, vous recevez une dame âgée de 70 ans ayant fait une chute sur le poignet en hyperextension. Son poignet est déformé et douloureux; l''impotence fonctionnelle est totale.', false, true, 'Quelle est la fracture de l''extrémité inférieure du radius la plus fréquente chez une femme âgée ?', '[{"l":"A","t":"Fracture sus-articulaire de Pouteau-Colles","c":false},{"l":"B","t":"Fracture comminutive, de l''extrémité inférieure du radius","c":true},{"l":"C","t":"Fracture décollement épiphysaire du radius","c":false},{"l":"D","t":"Fracture articulaire marginale antérieure","c":false},{"l":"E","t":"Fracture en bois vert de l''extrémité inférieure du radius","c":false}]'::jsonb, 'B - Les traits de refend articulaires (différence avec A) sont fréquents sur os ostéoporotique. D. E - Chez l''enfant. D - Mécanisme différent, moins fréquent que la chute sur le poignet en hyperextension et pronation (A,B).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2339, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 64 ans souffre depuis 12 ans d''une polyarthrite rhumatoïde. Le traitement a uniquement comporté des corticoïdes et des anti inflammatoires non stéroïdiens : elle reçoit actuellement 15 mg/j de Prednisone et 125 mg/j d''indométacine. Toute tentative de réduction des corticoïdes s''accompagne d'' une reprise des douleurs. Les signes d''hypercorticisme sont évidents. Deux motifs à son hospitalisation : des difficultés de préhension de la main droite, des douleurs du membre inférieur gauche à la marche depuis deux mois. Examen clinique : 1 ) Les difficultés de préhension s''expliquent par une déformation fixée des 2 et 3èmes doigts : hyperextension des interphalangiennes proximales (IPP), flexion des métacarpophalangiennes (MCP) et des interphalangiennes distales. 2) La douleur gênant la marche, siège à la face antérieure de la cuisse et s''arrête au dessus du genou. Les genoux sont secs, froids et stables depuis une synoviorthèse à Lynrium 90 faite trois ans auparavant. L''abduction et les rotations de la cuisse réveillent la douleur. Les radiographies : arthrites radiocarpiennes et des métacarpophalangiennes bilatérales. Les IPP et IPD sont radiologiquement normales. - genoux : discrets pincements des interlignes. - bassin de face : les interlignes coxofémoraux sont normaux ; à gauche, la structure de la tête fémorale est hétérogène, le contour a perdu sa sphéricité. - rachis : tassement de D7 et L3.', false, true, 'Quelle déformation des doigts gêne la fonction de la main chez cette malade ?', '[{"l":"A","t":"Coup de vent cubital","c":false},{"l":"B","t":"Main de singe","c":false},{"l":"C","t":"Doigts en boutonnière","c":false},{"l":"D","t":"Doigts à ressorts","c":false},{"l":"E","t":"Doigts en col de cygne","c":true}]'::jsonb, 'Sans commentaires.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2340, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 64 ans souffre depuis 12 ans d''une polyarthrite rhumatoïde. Le traitement a uniquement comporté des corticoïdes et des anti inflammatoires non stéroïdiens : elle reçoit actuellement 15 mg/j de Prednisone et 125 mg/j d''indométacine. Toute tentative de réduction des corticoïdes s''accompagne d'' une reprise des douleurs. Les signes d''hypercorticisme sont évidents. Deux motifs à son hospitalisation : des difficultés de préhension de la main droite, des douleurs du membre inférieur gauche à la marche depuis deux mois. Examen clinique : 1 ) Les difficultés de préhension s''expliquent par une déformation fixée des 2 et 3èmes doigts : hyperextension des interphalangiennes proximales (IPP), flexion des métacarpophalangiennes (MCP) et des interphalangiennes distales. 2) La douleur gênant la marche, siège à la face antérieure de la cuisse et s''arrête au dessus du genou. Les genoux sont secs, froids et stables depuis une synoviorthèse à Lynrium 90 faite trois ans auparavant. L''abduction et les rotations de la cuisse réveillent la douleur. Les radiographies : arthrites radiocarpiennes et des métacarpophalangiennes bilatérales. Les IPP et IPD sont radiologiquement normales. - genoux : discrets pincements des interlignes. - bassin de face : les interlignes coxofémoraux sont normaux ; à gauche, la structure de la tête fémorale est hétérogène, le contour a perdu sa sphéricité. - rachis : tassement de D7 et L3.', false, true, 'Les difficultés et douleurs à la marche sont dues à :', '[{"l":"A","t":"Une neuropathie par vascularite rhumatoïde","c":false},{"l":"B","t":"Une coxite rhumatoïde","c":false},{"l":"C","t":"Une algodystrophie","c":false},{"l":"D","t":"Une ostéonécrose de la tête fémorale","c":true},{"l":"E","t":"Une ostéoporose","c":false}]'::jsonb, 'L''interligne articulaire normal avec une perte de la sphéricité de la tête et une structure hétérogène signe le diagnostic.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2341, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 64 ans souffre depuis 12 ans d''une polyarthrite rhumatoïde. Le traitement a uniquement comporté des corticoïdes et des anti inflammatoires non stéroïdiens : elle reçoit actuellement 15 mg/j de Prednisone et 125 mg/j d''indométacine. Toute tentative de réduction des corticoïdes s''accompagne d'' une reprise des douleurs. Les signes d''hypercorticisme sont évidents. Deux motifs à son hospitalisation : des difficultés de préhension de la main droite, des douleurs du membre inférieur gauche à la marche depuis deux mois. Examen clinique : 1 ) Les difficultés de préhension s''expliquent par une déformation fixée des 2 et 3èmes doigts : hyperextension des interphalangiennes proximales (IPP), flexion des métacarpophalangiennes (MCP) et des interphalangiennes distales. 2) La douleur gênant la marche, siège à la face antérieure de la cuisse et s''arrête au dessus du genou. Les genoux sont secs, froids et stables depuis une synoviorthèse à Lynrium 90 faite trois ans auparavant. L''abduction et les rotations de la cuisse réveillent la douleur. Les radiographies : arthrites radiocarpiennes et des métacarpophalangiennes bilatérales. Les IPP et IPD sont radiologiquement normales. - genoux : discrets pincements des interlignes. - bassin de face : les interlignes coxofémoraux sont normaux ; à gauche, la structure de la tête fémorale est hétérogène, le contour a perdu sa sphéricité. - rachis : tassement de D7 et L3.', false, true, 'Quel(s) examen(s) parmi les suivants a(ont) un intérêt pour orienter le traitement médical de la polyarthrite rhumatoïde chez cette malade ?', '[{"l":"A","t":"Waaler Rose, Latex","c":false},{"l":"B","t":"Scintigraphie osseuse","c":false},{"l":"C","t":"Biopsie de synoviale","c":false},{"l":"D","t":"Recherche d''immuns complexes circulants","c":false},{"l":"E","t":"Protéinurie","c":true}]'::jsonb, 'Cette patiente est une candidate à la prescription de sels d''or et ceux-ci sont, bien entendu, contre-indiqués en cas de glomérulopathie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2342, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 64 ans souffre depuis 12 ans d''une polyarthrite rhumatoïde. Le traitement a uniquement comporté des corticoïdes et des anti inflammatoires non stéroïdiens : elle reçoit actuellement 15 mg/j de Prednisone et 125 mg/j d''indométacine. Toute tentative de réduction des corticoïdes s''accompagne d'' une reprise des douleurs. Les signes d''hypercorticisme sont évidents. Deux motifs à son hospitalisation : des difficultés de préhension de la main droite, des douleurs du membre inférieur gauche à la marche depuis deux mois. Examen clinique : 1 ) Les difficultés de préhension s''expliquent par une déformation fixée des 2 et 3èmes doigts : hyperextension des interphalangiennes proximales (IPP), flexion des métacarpophalangiennes (MCP) et des interphalangiennes distales. 2) La douleur gênant la marche, siège à la face antérieure de la cuisse et s''arrête au dessus du genou. Les genoux sont secs, froids et stables depuis une synoviorthèse à Lynrium 90 faite trois ans auparavant. L''abduction et les rotations de la cuisse réveillent la douleur. Les radiographies : arthrites radiocarpiennes et des métacarpophalangiennes bilatérales. Les IPP et IPD sont radiologiquement normales. - genoux : discrets pincements des interlignes. - bassin de face : les interlignes coxofémoraux sont normaux ; à gauche, la structure de la tête fémorale est hétérogène, le contour a perdu sa sphéricité. - rachis : tassement de D7 et L3.', false, true, 'Cette malade souffre d''un hypercorticisme iatrogène. Quel est parmi les programmes thérapeutiques suivants celui qui vous parait le plus à même de le pallier sans dommage pour son état articulaire ?', '[{"l":"A","t":"Arrêt progressif des corticoïdes en augmentant les doses d''indométacine","c":false},{"l":"B","t":"Substitution des corticoïdes oraux par des injections d''ACTH de synthèse","c":false},{"l":"C","t":"Arrêt progressif des corticoïdes et chirurgie réparatrice des mains","c":false},{"l":"D","t":"Mise en route d''un traitement antirhumatismal à action lente (Sels d''Or ou D-pénicillamine) puis réduction progressive des corticoïdes","c":true},{"l":"E","t":"Prescription d''anabolisant de synthèse (androgènes non virilisants)","c":false}]'::jsonb, 'La corticothérapie ne sera diminuée qu''au bout de 2 mois de traitement de fond (délai d''action nécessaire) et elle sera réduite très progressivement en raison du risque majeur d''insuffisance surrénale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2343, 10, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Une femme de 54 ans consulte pour une sciatique droite de topographie S1 apparue un mois plus tôt sans effort déclanchant net. Elle a des antécédents de lombalgies d''effort. Elle a subi 7 ans plus tôt une hystérectomie totale pour fibrome. La douleur est mal calmée par le repos et elle réveille même la malade. L''état général est conservé et il n''y a pas de fièvre. Il n''y a pas de syndrome rachidien ni de signe de Lasègue. Le réflexe achilléen droit est faible sans autre déficit neurologique. Le reste de l''examen clinique est normal.Les radiographies du rachis lombaire de face et de profil, et du bassin de face sont normales. La vitesse de sédimentation est à 8 mm à la première heure. l''hémogramme est normal. La calcémie est a 3 mmol/l (120 mg/l). La créatininémie est normale.', false, true, 'L''absence de syndrome rachidien oriente le diagnostic vers :', '[{"l":"A","t":"Une hernie discale non exclue","c":false},{"l":"B","t":"Une ostéoporose vertébrale","c":false},{"l":"C","t":"Une tumeur intrarachidienne","c":false},{"l":"D","t":"Une métastase osseuse sacrée","c":true},{"l":"E","t":"Une spondylodiscite infectieuse","c":false}]'::jsonb, 'Une sciatique sans lombalgie ni syndrome rachidien doit faire évoquer une atteinte radiculaire extrarachidienne. La topographie S1 oriente vers une atteinte sacrée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2344, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Une femme de 54 ans consulte pour une sciatique droite de topographie S1 apparue un mois plus tôt sans effort déclanchant net. Elle a des antécédents de lombalgies d''effort. Elle a subi 7 ans plus tôt une hystérectomie totale pour fibrome. La douleur est mal calmée par le repos et elle réveille même la malade. L''état général est conservé et il n''y a pas de fièvre. Il n''y a pas de syndrome rachidien ni de signe de Lasègue. Le réflexe achilléen droit est faible sans autre déficit neurologique. Le reste de l''examen clinique est normal.Les radiographies du rachis lombaire de face et de profil, et du bassin de face sont normales. La vitesse de sédimentation est à 8 mm à la première heure. l''hémogramme est normal. La calcémie est a 3 mmol/l (120 mg/l). La créatininémie est normale.', false, true, 'En faveur d''une hernie discale vous retiendriez :', '[{"l":"A","t":"Début progressif sans effort","c":false},{"l":"B","t":"Absence de signe de Lasègue","c":false},{"l":"C","t":"Antécédents fréquents de lombalgie d''effort","c":true},{"l":"D","t":"Vitesse de sédimentation normale","c":true},{"l":"E","t":"Absence de syndrome rachidien","c":false}]'::jsonb, 'La hernie discale est le plus souvent secondaire à une atteinte dégénérative du disque intervertébral responsable d''une lombosciatique mécanique avec syndrome rachidien et antécédents douloureux.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2345, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Une femme de 54 ans consulte pour une sciatique droite de topographie S1 apparue un mois plus tôt sans effort déclanchant net. Elle a des antécédents de lombalgies d''effort. Elle a subi 7 ans plus tôt une hystérectomie totale pour fibrome. La douleur est mal calmée par le repos et elle réveille même la malade. L''état général est conservé et il n''y a pas de fièvre. Il n''y a pas de syndrome rachidien ni de signe de Lasègue. Le réflexe achilléen droit est faible sans autre déficit neurologique. Le reste de l''examen clinique est normal.Les radiographies du rachis lombaire de face et de profil, et du bassin de face sont normales. La vitesse de sédimentation est à 8 mm à la première heure. l''hémogramme est normal. La calcémie est a 3 mmol/l (120 mg/l). La créatininémie est normale.', false, true, 'La constatation d''une hypercalcémie peut orienter le diagnostic vers :', '[{"l":"A","t":"Hernie discale","c":false},{"l":"B","t":"Maladie de Kahler","c":true},{"l":"C","t":"Métastase d''un cancer viscéral","c":true},{"l":"D","t":"Tumeur intrarachidienne","c":false},{"l":"E","t":"Spondylodiscite infectieuse","c":false}]'::jsonb, 'Une hypercalcémie sévère oriente d''emblée vers une cause néoplasique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2346, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 70 ans accuse depuis plusieurs mois une altération progressive de l''état général avec douleurs osseuses diffuses. L''examen clinique est par ailleurs normal. Un bilan est alors pratique dont les principaux éléments sont les suivants : - images ostéolytiques à l''emporte pièce au niveau du crâne, du bassin et des côtes ; déminéralisation du rachis dorso- lombaire - VS à 70 mm à la 1 ère heure - myélogramme 40 % de plasmocytes, dont certains atypiques - protidémie = 95 g/1 - electrophorèse des protéines sériques : pic d''allure monoclonale au niveau des gamma-globulines (40 g/l) - immunoélectrophorèse des protéines sérique : identification du pic à une immunoglobuline monoclonale de type IgG kappa - protéinurie : 1 g/l. presque exclusivement constituée par une protéinurie de Bence Jones - créatininémie = 340 micromol/l - calcémie = 3,2 micromol/l Le diagnostic de maladie de Kahler ou myélome multiple est posé et la malade hospitalisée.', false, true, 'En dehors de la maladie de Kahler, la maladie de Waldenstrِm représente une autre variété de dysglobulinémie maligne. Elle peut être éliminée chez notre malade devant :', '[{"l":"A","t":"Son âge","c":false},{"l":"B","t":"Le degré d''accélération de la VS","c":true},{"l":"C","t":"Le type de la prolifération cellulaire médullaire","c":true},{"l":"D","t":"Le type de l''immunoglobuline","c":true},{"l":"E","t":"L''existence d''une protéinurie de Bence Jones","c":true}]'::jsonb, 'La maladie de Waldenstrm est une dysglobulinémie à IgM sans protéinurie de Bence-Jones. Elle est secondaire à une prolifération médullaire lymphoplasmocytaire et il existe très fréquemment un syndrome d''hyperviscosité.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2347, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 70 ans accuse depuis plusieurs mois une altération progressive de l''état général avec douleurs osseuses diffuses. L''examen clinique est par ailleurs normal. Un bilan est alors pratique dont les principaux éléments sont les suivants : - images ostéolytiques à l''emporte pièce au niveau du crâne, du bassin et des côtes ; déminéralisation du rachis dorso- lombaire - VS à 70 mm à la 1 ère heure - myélogramme 40 % de plasmocytes, dont certains atypiques - protidémie = 95 g/1 - electrophorèse des protéines sériques : pic d''allure monoclonale au niveau des gamma-globulines (40 g/l) - immunoélectrophorèse des protéines sérique : identification du pic à une immunoglobuline monoclonale de type IgG kappa - protéinurie : 1 g/l. presque exclusivement constituée par une protéinurie de Bence Jones - créatininémie = 340 micromol/l - calcémie = 3,2 micromol/l Le diagnostic de maladie de Kahler ou myélome multiple est posé et la malade hospitalisée.', false, true, 'On peut aussi éliminer chez cette malade une gammapathie monoclonale dite bénigne devant :', '[{"l":"A","t":"Le degré d''accélération de la VS","c":true},{"l":"B","t":"Nature IgG de l''immunoglobuline monoclonale","c":false},{"l":"C","t":"L''importance de la plasmocytose médullaire","c":true},{"l":"D","t":"Le taux de la calcémie","c":true},{"l":"E","t":"La présence de lésions ostéolytiques","c":true}]'::jsonb, 'Une gammapathie monoclonale bénigne peut être rencontrée chez le sujet de plus de 40 ans, mais elle n''entraîne pas de signes de la série myéomateuse. Elle est constituée de chaînes gamma dans 85 % des cas.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2348, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 70 ans accuse depuis plusieurs mois une altération progressive de l''état général avec douleurs osseuses diffuses. L''examen clinique est par ailleurs normal. Un bilan est alors pratique dont les principaux éléments sont les suivants : - images ostéolytiques à l''emporte pièce au niveau du crâne, du bassin et des côtes ; déminéralisation du rachis dorso- lombaire - VS à 70 mm à la 1 ère heure - myélogramme 40 % de plasmocytes, dont certains atypiques - protidémie = 95 g/1 - electrophorèse des protéines sériques : pic d''allure monoclonale au niveau des gamma-globulines (40 g/l) - immunoélectrophorèse des protéines sérique : identification du pic à une immunoglobuline monoclonale de type IgG kappa - protéinurie : 1 g/l. presque exclusivement constituée par une protéinurie de Bence Jones - créatininémie = 340 micromol/l - calcémie = 3,2 micromol/l Le diagnostic de maladie de Kahler ou myélome multiple est posé et la malade hospitalisée.', false, true, 'La protéinurie de Bence Jones signalée :', '[{"l":"A","t":"Est constituée de chaînes lourdes d''immunoglobuline monoclonale","c":false},{"l":"B","t":"Est constituée de chaînes légères d''immunoglobuline monoclonale","c":false},{"l":"C","t":"Est constituée de molécules complètes d''immunoglobuline monoclonale","c":false},{"l":"D","t":"Est la conséquence de l''insuffisance rénale","c":false},{"l":"E","t":"Est nécessaire au diagnostic de maladie de Kahler","c":true}]'::jsonb, 'Il s''agit en effet de chaînes légères en excès de l''immunoglobuline monoclonale, et, elle peut être responsable d''une insuffisance rénale par toxicité directe des chaînes légères sur les tubules soit par précipitation des chaînes légères dans les tubules soit par amylose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2349, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 70 ans accuse depuis plusieurs mois une altération progressive de l''état général avec douleurs osseuses diffuses. L''examen clinique est par ailleurs normal. Un bilan est alors pratique dont les principaux éléments sont les suivants : - images ostéolytiques à l''emporte pièce au niveau du crâne, du bassin et des côtes ; déminéralisation du rachis dorso- lombaire - VS à 70 mm à la 1 ère heure - myélogramme 40 % de plasmocytes, dont certains atypiques - protidémie = 95 g/1 - electrophorèse des protéines sériques : pic d''allure monoclonale au niveau des gamma-globulines (40 g/l) - immunoélectrophorèse des protéines sérique : identification du pic à une immunoglobuline monoclonale de type IgG kappa - protéinurie : 1 g/l. presque exclusivement constituée par une protéinurie de Bence Jones - créatininémie = 340 micromol/l - calcémie = 3,2 micromol/l Le diagnostic de maladie de Kahler ou myélome multiple est posé et la malade hospitalisée.', false, true, 'L''hypercalcémie de la maladie de Kahler :', '[{"l":"A","t":"Est un élément permettant de suspecter une masse tumorale élevée","c":true},{"l":"B","t":"S''accompagne d''ordinaire d''une phosphorémie abaissée","c":false},{"l":"C","t":"Ne s''observe pas au cours du myélome à chaînes légères","c":false},{"l":"D","t":"Ne s''observe que lorsqu''existent des lésions ostéolytiques visibles radiologiquement","c":false},{"l":"E","t":"Peut être réduite par la chimiothérapie du myélome","c":true}]'::jsonb, 'La calcémie est un des paramètres mesurés qui permettent d''apprécier la masse tumorale selon la classification de Salmon et Durie. Il existe des formes "ostéoporotiques" du myélome qui s''expriment par une déminéralisation diffuse essentiellement au niveau du rachis.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2350, 10, 'Orthopédie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Une femme de 70 ans accuse depuis plusieurs mois une altération progressive de l''état général avec douleurs osseuses diffuses. L''examen clinique est par ailleurs normal. Un bilan est alors pratique dont les principaux éléments sont les suivants : - images ostéolytiques à l''emporte pièce au niveau du crâne, du bassin et des côtes ; déminéralisation du rachis dorso- lombaire - VS à 70 mm à la 1 ère heure - myélogramme 40 % de plasmocytes, dont certains atypiques - protidémie = 95 g/1 - electrophorèse des protéines sériques : pic d''allure monoclonale au niveau des gamma-globulines (40 g/l) - immunoélectrophorèse des protéines sérique : identification du pic à une immunoglobuline monoclonale de type IgG kappa - protéinurie : 1 g/l. presque exclusivement constituée par une protéinurie de Bence Jones - créatininémie = 340 micromol/l - calcémie = 3,2 micromol/l Le diagnostic de maladie de Kahler ou myélome multiple est posé et la malade hospitalisée.', false, true, 'Le traitement de fond de cette maladie de Kahler peut faire appel a :', '[{"l":"A","t":"Melphalan (Alkeran®)","c":true},{"l":"B","t":"Cyclophosphamide (Endoxan®)","c":true},{"l":"C","t":"Chlorambucil (Chloraminophène®)","c":false},{"l":"D","t":"Prednisone (Cortancyl®)","c":true},{"l":"E","t":"Radiophosphore","c":false}]'::jsonb, 'En raison de la présence de nombreuses géodes et d''une insuffisance rénale, il s''agit d''un stade 3 B (masse tumorale forte) qui doit indiquer une polychimiothérapie. Ici, visiblement le correcteur est parti sur une monochimiothérapie melphalan ou cyclophosphamide.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2351, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'M. V..., 74 ans, est hospitalisé pour des douleurs inguino-crurales tenaces, d''aggravation progressive et maintenant responsables de sévères troubles de la marche. Dans les antécédents, on note une claudication intermittente qui a fait découvrir à58 ans une artériopathie oblitérante des membres inférieurs ; une sympathectomie lombaire gauche, réalisée à 61 ans, n''a eu qu''un effet partiel ; la persistance de douleurs à la marche a conduit le malade à limiter de plus en plus ses sorties ; ces dernières années, il n''a pratiquement pas quitté son domicile (appartement en ville). Depuis que l''affection artérielle a été décelée M. V... s''est astreint à un régime très restrictif en matières grasses d''origine animale. Les douleurs actuelles ont débuté dans la région inguinale gauche ; un cliché a mis en évidence une fissure du col fémoral gauche qui a fait parler de fracture de fatigue et à conduit a la suppression de l''appui pendant 3 mois. Mais les douleurs sont réapparues des la reprise de la marche ; elles se sont bilatéralisées et s''associent à des douleurs thoraciques et scapulaires depuis quelques mois. Elles sont maintenant très sévères mais restent de type mécanique, elles ne permettent que quelques petits pas précautionneux. Outre les troubles de la marche, l''examen clinique montre un état général assez médiocre (45 kg pour 160 cm; perte de 8 kg) ; il n''y a pas de limitation nette des mouvements des hanches et du rachis; la pression du thorax est douloureuse. Les pouls fémoraux sont bien perçus. L''examen neurologique et digestif est normal ainsi que le reste de l''examen clinique. Les examens sanguins suivants donnent des résultats normaux : VS, hémogramme, créatininémie., glycémie, électrophorèse des protides. Il existe une hyperphosphatasémie alcaline modérée. Calcémie : 84 mg/l (21 mmol/l) ; phosphorémie : 22 mg/l (0,70 mmol), calciurie des 24 heures : 29 mg (0.82 mmol). Sur les radiographies du rachis lombaire, les vertèbres ont des contours flous ; le cliché du bassin décèle, sur le bord supérieur des deux cols fémoraux, une fissure avec condensation périphérique et périostose ; les articulations coxofémorales ont un aspect radiologique normal.', false, true, 'Lequel de ces examens permettra de confirmer le diagnostic d''ostéomalacie ?', '[{"l":"A","t":"Scintigraphie osseuse","c":false},{"l":"B","t":"Biopsie osseuse iliaque au trocart","c":true},{"l":"C","t":"Dosage de la 25 OH - vitamine D sérique","c":false},{"l":"D","t":"Radiographie de l''ensemble du squelette","c":false},{"l":"E","t":"Mesure de la clairance rénale du phosphore","c":false}]'::jsonb, 'La clearance du phosphore est augmentée et le dosage de la 25-0H vitamine D montre un taux sérique diminué, mais seule la biopsie osseuse affirme le diagnostic et permet de faire la part d''une éventuelle hyperparathyroïdie secondaire associée.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2352, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'M. V..., 74 ans, est hospitalisé pour des douleurs inguino-crurales tenaces, d''aggravation progressive et maintenant responsables de sévères troubles de la marche. Dans les antécédents, on note une claudication intermittente qui a fait découvrir à58 ans une artériopathie oblitérante des membres inférieurs ; une sympathectomie lombaire gauche, réalisée à 61 ans, n''a eu qu''un effet partiel ; la persistance de douleurs à la marche a conduit le malade à limiter de plus en plus ses sorties ; ces dernières années, il n''a pratiquement pas quitté son domicile (appartement en ville). Depuis que l''affection artérielle a été décelée M. V... s''est astreint à un régime très restrictif en matières grasses d''origine animale. Les douleurs actuelles ont débuté dans la région inguinale gauche ; un cliché a mis en évidence une fissure du col fémoral gauche qui a fait parler de fracture de fatigue et à conduit a la suppression de l''appui pendant 3 mois. Mais les douleurs sont réapparues des la reprise de la marche ; elles se sont bilatéralisées et s''associent à des douleurs thoraciques et scapulaires depuis quelques mois. Elles sont maintenant très sévères mais restent de type mécanique, elles ne permettent que quelques petits pas précautionneux. Outre les troubles de la marche, l''examen clinique montre un état général assez médiocre (45 kg pour 160 cm; perte de 8 kg) ; il n''y a pas de limitation nette des mouvements des hanches et du rachis; la pression du thorax est douloureuse. Les pouls fémoraux sont bien perçus. L''examen neurologique et digestif est normal ainsi que le reste de l''examen clinique. Les examens sanguins suivants donnent des résultats normaux : VS, hémogramme, créatininémie., glycémie, électrophorèse des protides. Il existe une hyperphosphatasémie alcaline modérée. Calcémie : 84 mg/l (21 mmol/l) ; phosphorémie : 22 mg/l (0,70 mmol), calciurie des 24 heures : 29 mg (0.82 mmol). Sur les radiographies du rachis lombaire, les vertèbres ont des contours flous ; le cliché du bassin décèle, sur le bord supérieur des deux cols fémoraux, une fissure avec condensation périphérique et périostose ; les articulations coxofémorales ont un aspect radiologique normal.', false, true, 'Parmi les données suivantes concernant ce cas, laquelle(lesquelles) n''est(ne sont) jamais recontrée(s) dans l''ostéoporose commune ?', '[{"l":"A","t":"L''âge de 74 ans","c":false},{"l":"B","t":"Le sexe masculin","c":false},{"l":"C","t":"L''artériopathie oblitérante des membres inférieurs","c":false},{"l":"D","t":"Les stries de Looser","c":true},{"l":"E","t":"L''hypocalcémie marquée","c":true}]'::jsonb, 'Le bilan phosphocalcique est normal dans l''ostéoporose commune et il n''y a pas de stries de Looser Milkman si elle est isolé.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2353, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'M. V..., 74 ans, est hospitalisé pour des douleurs inguino-crurales tenaces, d''aggravation progressive et maintenant responsables de sévères troubles de la marche. Dans les antécédents, on note une claudication intermittente qui a fait découvrir à58 ans une artériopathie oblitérante des membres inférieurs ; une sympathectomie lombaire gauche, réalisée à 61 ans, n''a eu qu''un effet partiel ; la persistance de douleurs à la marche a conduit le malade à limiter de plus en plus ses sorties ; ces dernières années, il n''a pratiquement pas quitté son domicile (appartement en ville). Depuis que l''affection artérielle a été décelée M. V... s''est astreint à un régime très restrictif en matières grasses d''origine animale. Les douleurs actuelles ont débuté dans la région inguinale gauche ; un cliché a mis en évidence une fissure du col fémoral gauche qui a fait parler de fracture de fatigue et à conduit a la suppression de l''appui pendant 3 mois. Mais les douleurs sont réapparues des la reprise de la marche ; elles se sont bilatéralisées et s''associent à des douleurs thoraciques et scapulaires depuis quelques mois. Elles sont maintenant très sévères mais restent de type mécanique, elles ne permettent que quelques petits pas précautionneux. Outre les troubles de la marche, l''examen clinique montre un état général assez médiocre (45 kg pour 160 cm; perte de 8 kg) ; il n''y a pas de limitation nette des mouvements des hanches et du rachis; la pression du thorax est douloureuse. Les pouls fémoraux sont bien perçus. L''examen neurologique et digestif est normal ainsi que le reste de l''examen clinique. Les examens sanguins suivants donnent des résultats normaux : VS, hémogramme, créatininémie., glycémie, électrophorèse des protides. Il existe une hyperphosphatasémie alcaline modérée. Calcémie : 84 mg/l (21 mmol/l) ; phosphorémie : 22 mg/l (0,70 mmol), calciurie des 24 heures : 29 mg (0.82 mmol). Sur les radiographies du rachis lombaire, les vertèbres ont des contours flous ; le cliché du bassin décèle, sur le bord supérieur des deux cols fémoraux, une fissure avec condensation périphérique et périostose ; les articulations coxofémorales ont un aspect radiologique normal.', false, true, 'Le(s)quel(s) de ces 5 éléments peu(ven)t être incriminé(s) dans la survenue de cette ostéomalacie ?', '[{"l":"A","t":"Le régime alimentaire très pauvre en lipides d''origine animale","c":true},{"l":"B","t":"Un traitement par antivitamine K suivi 3 ans pour l''artériopathie, quelques années auparavant","c":false},{"l":"C","t":"Un traitement hypolipémiant par clofibrate","c":false},{"l":"D","t":"Un défaut d''exposition solaire","c":true},{"l":"E","t":"Une réduction de l''activité physique","c":false}]'::jsonb, 'La vitamine D est une vitamine liposoluble dont l''absorption peut être réduite en cas d''apports lipidiques animaux modérés ou de traitement par la cholestyramine.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2354, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'M. V..., 74 ans, est hospitalisé pour des douleurs inguino-crurales tenaces, d''aggravation progressive et maintenant responsables de sévères troubles de la marche. Dans les antécédents, on note une claudication intermittente qui a fait découvrir à58 ans une artériopathie oblitérante des membres inférieurs ; une sympathectomie lombaire gauche, réalisée à 61 ans, n''a eu qu''un effet partiel ; la persistance de douleurs à la marche a conduit le malade à limiter de plus en plus ses sorties ; ces dernières années, il n''a pratiquement pas quitté son domicile (appartement en ville). Depuis que l''affection artérielle a été décelée M. V... s''est astreint à un régime très restrictif en matières grasses d''origine animale. Les douleurs actuelles ont débuté dans la région inguinale gauche ; un cliché a mis en évidence une fissure du col fémoral gauche qui a fait parler de fracture de fatigue et à conduit a la suppression de l''appui pendant 3 mois. Mais les douleurs sont réapparues des la reprise de la marche ; elles se sont bilatéralisées et s''associent à des douleurs thoraciques et scapulaires depuis quelques mois. Elles sont maintenant très sévères mais restent de type mécanique, elles ne permettent que quelques petits pas précautionneux. Outre les troubles de la marche, l''examen clinique montre un état général assez médiocre (45 kg pour 160 cm; perte de 8 kg) ; il n''y a pas de limitation nette des mouvements des hanches et du rachis; la pression du thorax est douloureuse. Les pouls fémoraux sont bien perçus. L''examen neurologique et digestif est normal ainsi que le reste de l''examen clinique. Les examens sanguins suivants donnent des résultats normaux : VS, hémogramme, créatininémie., glycémie, électrophorèse des protides. Il existe une hyperphosphatasémie alcaline modérée. Calcémie : 84 mg/l (21 mmol/l) ; phosphorémie : 22 mg/l (0,70 mmol), calciurie des 24 heures : 29 mg (0.82 mmol). Sur les radiographies du rachis lombaire, les vertèbres ont des contours flous ; le cliché du bassin décèle, sur le bord supérieur des deux cols fémoraux, une fissure avec condensation périphérique et périostose ; les articulations coxofémorales ont un aspect radiologique normal.', false, true, 'Le(s)quel(s) des 5 traitements suivant(s) est(sont) indiqué(s) chez ce malade ?', '[{"l":"A","t":"Calcithérapie isolée, 1.5 g/jour per os","c":false},{"l":"B","t":"Fluorure de sodium (50 mg/jour) + calcium 1 g/jour","c":false},{"l":"C","t":"Vitamine D2 : 10 000UI/jour","c":true},{"l":"D","t":"Calcitonine de saumon (Calsyn®) : 50 UI par vois sous-cutanée","c":false},{"l":"E","t":"Fluorure de sodium (50 mg/jour) + vitamine D2 8 000 UI/jour","c":false}]'::jsonb, 'Il s''agit d''une ostéomalacie par hypovitaminose D qu''il faut donc supplémenter en vitamine D, éventuellement sous forme de vitamine D2 (Stérogyl®) mais aussi sous forme de calcium. Le fluor est contre-indiqué et la calcitonine n''a pas d''indication.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2355, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Quelle est l''origine des engourdissements nocturnes des doigts qui ont inauguré la maladie ?', '[{"l":"A","t":"Une névralgie cervico-brachiale","c":false},{"l":"B","t":"Une neuropathie amyloïde","c":false},{"l":"C","t":"Une synovite des fléchisseurs","c":true},{"l":"D","t":"Une ostéonécrose du semi-lunaire","c":false},{"l":"E","t":"Une spasmophilie","c":false}]'::jsonb, 'La ténosynovité des tendons des fléchisseurs était responsable d''un syndrome du canal carpien (les gaines des fléchisseurs remontent jusque dans le canal).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2356, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Une ponction du genou a été effectuée avant la mise au traitement par l''allochrysine. Parmi les formules du liquide articulaire, quelle est celle qui s''adapte le mieux au diagnostic retenu de polyarthrite rhumatoïde ? Eléments/mm3 Polynucl Lymphoc. Monoc. Cristaux. Rapport compl.articul. compl.sérique', '[{"l":"A","t":"8 700 75 % 15 % 10 % - 0,15","c":false},{"l":"B","t":"8 700 75 % 15 % 10 % - 0,50","c":true},{"l":"C","t":"8 700 75 % 15 % 10 % + 0,25","c":false},{"l":"D","t":"8 700 10 % 10 % 75 % - 0,50","c":false},{"l":"E","t":"500 10 % 65 % 25 % - 0,25","c":false}]'::jsonb, 'Il s''agit d''un liquide inflammatoire contenant plus de 2 000 cellules par mm3 à prédominance de polynucléaires, avec absence de cristaux et abaissement du complément par rapport au complément sérique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2357, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Quelle est parmi les associations suivantes, celle qui est la plus compatible avec le diagnostic de polyarthrite rhumatoïde avant la mise en route du traitement de fond ?', '[{"l":"A","t":"VS : 65, leucocytes : 3 200, Waaler Rose : 1/128, Latex : 1/20000, anticorps antinucléaires : 1/1000, homogène : protéinurie absente","c":false},{"l":"B","t":"VS : 65., leucocytes : 7 200, Waaler Rose : négatif, Latex : négatif anticorps antinucléaires : absent, protéinurie : absente","c":true},{"l":"C","t":"VS : 65, leucocytes : 7 200, Waaler Rose négatif, Latex négatif anticorps antinucléaires : absent, protéinurie 2 g/24 h","c":false},{"l":"D","t":"VS : 65, leucocytes : 7 200, Waaler Rose : négatif, Latex : négatif. anticorps antinucléaires : 1/1000, mouchète, protéinurie : absente","c":false},{"l":"E","t":"VS : 10, pincement et condensation des interlignes articulaires des 2 et 3ème articulations métacarpophalangiennes droites","c":false}]'::jsonb, '20% des polyarthrites rhumatoïdes sont séronégatives après un an d''évolution. Une leucopénie, des facteurs antinucléaires très élevés et une protéinurie doivent faire évoquer un lupus.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2358, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Sur les radiographies de l''avant pied faites au 7ème mois d''évolution, une image très évocatrice de PR. est retrouvée : laquelle ?', '[{"l":"A","t":"Déminéralisation diffuse des os de l''avant pied","c":false},{"l":"B","t":"Géode cerclée de la diaphyse du 5ème métatarsien","c":false},{"l":"C","t":"Erosion de la 5ème tête métatarsienne","c":true},{"l":"D","t":"Pincement du 5ème interligne métatarsophalangien et ostéophytose","c":false},{"l":"E","t":"Périostose du 5ème métatarsien","c":false}]'::jsonb, 'L''érosion de la tête du 5e métatarsien est un signe précieux car assez précoce et très évocateur.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2359, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Le traitement par les sels d''or étant décidé. quelle surveillance vous parait la plus adaptée ?', '[{"l":"A","t":"Electrorétinogramme tous les six mois - protéinurie tous les mois","c":false},{"l":"B","t":"NFS - VS toutes les semaines - protéinurie tous les deux mois","c":false},{"l":"C","t":"Protéinurie avant chaque injection d''or, NFS, VS, Waaler Rose, Latex tous les deux mois","c":false},{"l":"D","t":"Protéinurie avant chaque injection d''or, NFS, VS, Waaler Rose, Latex facteurs antinucléaires tous les 3 mois","c":false},{"l":"E","t":"Protéinurie avant chaque injection d''or, NFS, V S, tous les mois","c":true}]'::jsonb, 'La protéinurie doit être effectuée avant chaque injection. La numération recherchera une complication hématologique rare et la VS surveillera l''évolution de la maladie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2360, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Une femme de 42 ans souffrait depuis un an. Au début, elle se plaignait d''un engourdissement nocturne des doigts puis sont apparus des douleurs et un gonflement des poignets et une difficulté à fléchir les doigts, des douleurs et gonflement du genou droit et des métatarsophalangiennes droites et gauches. Le diagnostic retenu 6 mois après le début de l''affection sur des examens cliniques biologiques et radiologiques est celui de polyarthrite rhumatoïde. Les douleurs et les signes objectifs d''arthrite étant insuffisamment soulagés par 3 grammes par jour d''aspirine ou par 150 mg par jour d''indométacine, un traitement par les sels d''or a été prescrit à la dose de 5 centigrammes par semaine. Le traitement a été bien toléré. Au 5ème mois l''effet de ce traitement est favorable. La raideur matinale est passée de 45 a 15 minutes. Les poignets ont retrouve un aspect normal. La vitesse de sédimentation initialement à 65 mm à la 1ère heure est revenue à 15 mm à la 1 ère heure', false, true, 'Quelle suite pensez-vous donner au traitement de cette malade, compte-tenu de l''amélioration actuelle ?', '[{"l":"A","t":"Allochrysine® : cinq centigrammes par semaine","c":false},{"l":"B","t":"Arrêt de l''Allochrysine® et surveillance clinique et biologique","c":false},{"l":"C","t":"Arrêt de l''Allochrysine® remplacée par 600 mg de D-Penicillamine par jour","c":false},{"l":"D","t":"Allochrysine : dix centigrammes par mois tant que ce médicament reste efficace et bien supporté","c":true},{"l":"E","t":"Arrêt de l''Allochrysine®, indométhacine : 75 mg par jour","c":false}]'::jsonb, 'Q.C.M. discutable car il n''y a pas unanimité sur les modalités du traitement lorsque la dose de 1,20 à 40 g est atteinte. Certains suspendent le traitement, d''autres espacent les injections...(dose cumulée : 1,30 g).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2361, 3, 'Rhumatologie', 'Principe de base en médecine physique et réadaptation', 'Un homme de 32 ans, peintre en bâtiment, souffre d''une sciatique droite. Celle-ci, s''est installée à la suite d''un effort, survenu sur son lieu de travail. L''interrogatoire retrouve des épisodes de lumbagos aigus de durée brève et d''intensité modérée, mais le patient n''avait jamais eu de sciatique. Il n''a pas d''antécédents pathologiques notables, en particulier pas de problèmes digestifs. La douleur n''est pas très intense, mais elle est exacerbée par la position debout ou assise prolongée. Elle est mal calmée par le repos et tient le malade réveille la nuit. Il n''a pas de troubles sphinctériens. A l''examen, il existe une attitude antalgique croisée : le rachis est raide avec un signe de la sonnette. La douleur suit un trajet L5 : la manoeuvre de Lasègue devient douloureuse à 60 degrés Le réflexe achilléen est conservé, la force musculaire est normale, il n''y a pas d''anesthésie en selle. L''examen clinique général est normal. Des radiographies standard du rachis mettent en évidence une diminution nette de la hauteur du disque L4-L5, à l''exclusion de toute autre anomalie.', false, true, 'Parmi les possibilités thérapeutiques suivantes, vous retenez initialement :', '[{"l":"A","t":"Mise au repos complet","c":true},{"l":"B","t":"Kinésithérapie lombaire","c":false},{"l":"C","t":"Diclofanac (Voltarène®) : 150 mg par jour per os","c":true},{"l":"D","t":"Paracétamol : 1,5 g par jour","c":true},{"l":"E","t":"Prednisone : 1 mg par kilo et par jour","c":false}]'::jsonb, 'Il s''agit d''une lombosciatique de caractère mécanique. Le traitement repose essentiellement sur le repos allongé, les antalgiques (1 comprimé de 500 mg de paracétamol 3 fois par jour ou dose double) et éventuellement des anti-inflammatoires.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2362, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 32 ans, peintre en bâtiment, souffre d''une sciatique droite. Celle-ci, s''est installée à la suite d''un effort, survenu sur son lieu de travail. L''interrogatoire retrouve des épisodes de lumbagos aigus de durée brève et d''intensité modérée, mais le patient n''avait jamais eu de sciatique. Il n''a pas d''antécédents pathologiques notables, en particulier pas de problèmes digestifs. La douleur n''est pas très intense, mais elle est exacerbée par la position debout ou assise prolongée. Elle est mal calmée par le repos et tient le malade réveille la nuit. Il n''a pas de troubles sphinctériens. A l''examen, il existe une attitude antalgique croisée : le rachis est raide avec un signe de la sonnette. La douleur suit un trajet L5 : la manoeuvre de Lasègue devient douloureuse à 60 degrés Le réflexe achilléen est conservé, la force musculaire est normale, il n''y a pas d''anesthésie en selle. L''examen clinique général est normal. Des radiographies standard du rachis mettent en évidence une diminution nette de la hauteur du disque L4-L5, à l''exclusion de toute autre anomalie.', false, true, 'Après 8 jours de ce traitement, aucune amélioration n''est obtenue. Vous proposez alors :', '[{"l":"A","t":"Mise en place d''un lombostat plâtré","c":false},{"l":"B","t":"3 infiltrations épidurales de corticoïdes à 4 jours d''intervalle","c":true},{"l":"C","t":"Manipulations vertébrales","c":false},{"l":"D","t":"Tractions vertébrales","c":true},{"l":"E","t":"Injections IM de vitamine B12 (Dibencozan 20 000®) une par jour pendant trente jours","c":false}]'::jsonb, 'Les infiltrations épidurales sont efficaces et les tractions peuvent être proposées en raison de l''absence de contre-indications mais elles seront interrompues des l''amélioration.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2363, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 32 ans, peintre en bâtiment, souffre d''une sciatique droite. Celle-ci, s''est installée à la suite d''un effort, survenu sur son lieu de travail. L''interrogatoire retrouve des épisodes de lumbagos aigus de durée brève et d''intensité modérée, mais le patient n''avait jamais eu de sciatique. Il n''a pas d''antécédents pathologiques notables, en particulier pas de problèmes digestifs. La douleur n''est pas très intense, mais elle est exacerbée par la position debout ou assise prolongée. Elle est mal calmée par le repos et tient le malade réveille la nuit. Il n''a pas de troubles sphinctériens. A l''examen, il existe une attitude antalgique croisée : le rachis est raide avec un signe de la sonnette. La douleur suit un trajet L5 : la manoeuvre de Lasègue devient douloureuse à 60 degrés Le réflexe achilléen est conservé, la force musculaire est normale, il n''y a pas d''anesthésie en selle. L''examen clinique général est normal. Des radiographies standard du rachis mettent en évidence une diminution nette de la hauteur du disque L4-L5, à l''exclusion de toute autre anomalie.', false, true, 'Cette attitude est la bonne, puisque le patient s''améliore et s''achemine vers la guérison Que prescrivez-vous alors ?', '[{"l":"A","t":"Arrêt de travail de 10 jours","c":false},{"l":"B","t":"Arrêt de travail de 45 jours","c":true},{"l":"C","t":"20 séances de massages et de rééducation du rachis lombaire","c":true},{"l":"D","t":"Un lombostat","c":true},{"l":"E","t":"Jusqu''à disparition complète des symptômes, de la vitamine B1 (1 g par jour), par voie orale","c":false}]'::jsonb, 'Il s''agit d''un travailleur manuel et la "cicatrisation" du disque doit être obtenue avant la reprise du travail ; elle nécessite environ 6 semaines. La reprise du travail peut se faire avec un lombostat. L''attitude est fonction des écoles.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2364, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 32 ans, peintre en bâtiment, souffre d''une sciatique droite. Celle-ci, s''est installée à la suite d''un effort, survenu sur son lieu de travail. L''interrogatoire retrouve des épisodes de lumbagos aigus de durée brève et d''intensité modérée, mais le patient n''avait jamais eu de sciatique. Il n''a pas d''antécédents pathologiques notables, en particulier pas de problèmes digestifs. La douleur n''est pas très intense, mais elle est exacerbée par la position debout ou assise prolongée. Elle est mal calmée par le repos et tient le malade réveille la nuit. Il n''a pas de troubles sphinctériens. A l''examen, il existe une attitude antalgique croisée : le rachis est raide avec un signe de la sonnette. La douleur suit un trajet L5 : la manoeuvre de Lasègue devient douloureuse à 60 degrés Le réflexe achilléen est conservé, la force musculaire est normale, il n''y a pas d''anesthésie en selle. L''examen clinique général est normal. Des radiographies standard du rachis mettent en évidence une diminution nette de la hauteur du disque L4-L5, à l''exclusion de toute autre anomalie.', false, true, 'Lors de la reprise du travail, il faut régulariser la position du malade vis à vis des organismes sociaux. Plusieurs attitudes sont possibles, sauf une. Laquelle ?', '[{"l":"A","t":"Reprise avec soin trois mois","c":false},{"l":"B","t":"Guérison","c":false},{"l":"C","t":"Demande de mi-temps thérapeutique","c":false},{"l":"D","t":"Consolidation avec I.P.P. à fixer","c":false},{"l":"E","t":"Aucune formalité n''est nécessaire","c":true}]'::jsonb, 'Il faut obligatoirement régulariser la situation du patient car il s''agit d''un accident de travail qui a fait l''objet d''une déclaration.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2365, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un homme de 32 ans, peintre en bâtiment, souffre d''une sciatique droite. Celle-ci, s''est installée à la suite d''un effort, survenu sur son lieu de travail. L''interrogatoire retrouve des épisodes de lumbagos aigus de durée brève et d''intensité modérée, mais le patient n''avait jamais eu de sciatique. Il n''a pas d''antécédents pathologiques notables, en particulier pas de problèmes digestifs. La douleur n''est pas très intense, mais elle est exacerbée par la position debout ou assise prolongée. Elle est mal calmée par le repos et tient le malade réveille la nuit. Il n''a pas de troubles sphinctériens. A l''examen, il existe une attitude antalgique croisée : le rachis est raide avec un signe de la sonnette. La douleur suit un trajet L5 : la manoeuvre de Lasègue devient douloureuse à 60 degrés Le réflexe achilléen est conservé, la force musculaire est normale, il n''y a pas d''anesthésie en selle. L''examen clinique général est normal. Des radiographies standard du rachis mettent en évidence une diminution nette de la hauteur du disque L4-L5, à l''exclusion de toute autre anomalie.', false, true, 'Dès la reprise du travail, une récidive survient, avec diminution importante de la force musculaire des péroniers latéraux, persistante après une semaine de traitement médical bien conduit. Les explorations neuro- radiologiques confirment la présence d''une hernie discale exclue L4-L5. Que proposez-vous ?', '[{"l":"A","t":"Reprise du traitement médical : repos au lit, infiltration","c":false},{"l":"B","t":"La mise en place d''un lombostat plâtré","c":false},{"l":"C","t":"Une chimionucléolyse","c":false},{"l":"D","t":"Un traitement chirurgical de la hernie discale","c":true},{"l":"E","t":"La mise en tractions continue","c":false}]'::jsonb, 'Il s''agit d''une sciatique parésiante qui résiste au traitement médical bien conduit avec l''image d''hernie discale à la radiculographie, l''intervention chirurgicale s''impose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2366, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un blessé de 45 ans, transporteur routier, éthylique, pesant 87 kilos, a été victime 15 ans auparavant d''un polytraumatisme avec traumatisme crânien, fracture de la diaphyse fémorale droite et gauche, fracture ouverte comminutive de la jambe droite, au tiers moyen-tiers inférieur traitée par plâtre. IL a eu des suites opératoires mouvementées, il a repris son travail deux ans après l''accident. IL consulte pour des douleurs du genou droit de type mécanique apparues il y a quelques mois. A l''examen clinique et radiographique, les deux fémurs sont consolides et bien alignes. mais le tibia droit présente un cal vicieux avec angulation de 10° en varus. Il existe des signes d''ostéite avec une fistule qui s''ouvre deux ou trois fois par an mais qui est actuellement cicatrisée.', false, true, 'Les séquelles auraient été éventuellement évitées par un traitement local de la fracture ouverte comportant :', '[{"l":"A","t":"Parage méticuleux","c":true},{"l":"B","t":"Immobilisation stricte par fixateur externe","c":true},{"l":"C","t":"Réduction correcte","c":true},{"l":"D","t":"Fermeture de la peau","c":true},{"l":"E","t":"Conservation des esquilles osseuses dépériostées","c":false}]'::jsonb, 'Le parage en salle d''opération doit être extrêmement méticuleux, l''immobilisation stricte avec un fixateur externe est la seule possibilité lors des grands fracas. La fermeture cutanée est idéale à condition qu''elle se fasse sans tension. Il faut éviter le dépériostage excessif.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2367, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un blessé de 45 ans, transporteur routier, éthylique, pesant 87 kilos, a été victime 15 ans auparavant d''un polytraumatisme avec traumatisme crânien, fracture de la diaphyse fémorale droite et gauche, fracture ouverte comminutive de la jambe droite, au tiers moyen-tiers inférieur traitée par plâtre. IL a eu des suites opératoires mouvementées, il a repris son travail deux ans après l''accident. IL consulte pour des douleurs du genou droit de type mécanique apparues il y a quelques mois. A l''examen clinique et radiographique, les deux fémurs sont consolides et bien alignes. mais le tibia droit présente un cal vicieux avec angulation de 10° en varus. Il existe des signes d''ostéite avec une fistule qui s''ouvre deux ou trois fois par an mais qui est actuellement cicatrisée.', false, true, 'Une désorientation temporospatiale était apparue 24 heures après l''accident, il existait des pétéchies sous- conjonctivales et des infiltrats au fond d''oeil. S''agissait-il ?', '[{"l":"A","t":"D''un delirium tremens","c":false},{"l":"B","t":"D''un coma hépatique","c":false},{"l":"C","t":"D''une hémorragie méningée","c":false},{"l":"D","t":"D''une embolie graisseuse","c":true},{"l":"E","t":"D''un hématome extra-dural","c":false}]'::jsonb, 'Ce tableau fait évoquer en effet l''embolie graisseuse avec les micro-infarctus distaux et les infiltrats du fond d''oeil. Il doit faire rechercher un poumon lésionnel avec détresse respiratoire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2368, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un blessé de 45 ans, transporteur routier, éthylique, pesant 87 kilos, a été victime 15 ans auparavant d''un polytraumatisme avec traumatisme crânien, fracture de la diaphyse fémorale droite et gauche, fracture ouverte comminutive de la jambe droite, au tiers moyen-tiers inférieur traitée par plâtre. IL a eu des suites opératoires mouvementées, il a repris son travail deux ans après l''accident. IL consulte pour des douleurs du genou droit de type mécanique apparues il y a quelques mois. A l''examen clinique et radiographique, les deux fémurs sont consolides et bien alignes. mais le tibia droit présente un cal vicieux avec angulation de 10° en varus. Il existe des signes d''ostéite avec une fistule qui s''ouvre deux ou trois fois par an mais qui est actuellement cicatrisée.', false, true, 'Vers le cinquième jour après l''accident, devant une élévation thermique à 38,5 degrés avec douleur de la jambe, il fallait évoquer :', '[{"l":"A","t":"Compression par plâtre trop serré","c":false},{"l":"B","t":"Déplacement secondaire des fragments","c":false},{"l":"C","t":"Infection du foyer de fracture","c":true},{"l":"D","t":"Thrombo-phlébite","c":true},{"l":"E","t":"Escarre sous plâtre","c":false}]'::jsonb, 'L''infection du foyer de fracture est l''accident le plus redouté après une fracture ouverte mais il faut également toujours penser à la thrombo-phlébite.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2369, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un blessé de 45 ans, transporteur routier, éthylique, pesant 87 kilos, a été victime 15 ans auparavant d''un polytraumatisme avec traumatisme crânien, fracture de la diaphyse fémorale droite et gauche, fracture ouverte comminutive de la jambe droite, au tiers moyen-tiers inférieur traitée par plâtre. IL a eu des suites opératoires mouvementées, il a repris son travail deux ans après l''accident. IL consulte pour des douleurs du genou droit de type mécanique apparues il y a quelques mois. A l''examen clinique et radiographique, les deux fémurs sont consolides et bien alignes. mais le tibia droit présente un cal vicieux avec angulation de 10° en varus. Il existe des signes d''ostéite avec une fistule qui s''ouvre deux ou trois fois par an mais qui est actuellement cicatrisée.', false, true, 'Pour connaître la cause des douleurs actuelles du genou, quel(s) examen(s) complémentaire(s) apporte(nt) le plus simplement la réponse', '[{"l":"A","t":"Radiographies standard du genou en charge","c":true},{"l":"B","t":"Tomodensitométrie du genou","c":false},{"l":"C","t":"Radiographies des membres inférieurs en totalité et en charge","c":false},{"l":"D","t":"Arthrographie","c":false},{"l":"E","t":"Scintigraphie osseuse","c":false}]'::jsonb, 'Les cals vicieux angulaires en varus sont les moins bien tolérés car ils provoquent des douleurs et des retentissements articulaires sus et sousjacents dès qu''ils atteignent 10°. Le cliché standard en charge recherchera un pincement localisé.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2370, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un blessé de 45 ans, transporteur routier, éthylique, pesant 87 kilos, a été victime 15 ans auparavant d''un polytraumatisme avec traumatisme crânien, fracture de la diaphyse fémorale droite et gauche, fracture ouverte comminutive de la jambe droite, au tiers moyen-tiers inférieur traitée par plâtre. IL a eu des suites opératoires mouvementées, il a repris son travail deux ans après l''accident. IL consulte pour des douleurs du genou droit de type mécanique apparues il y a quelques mois. A l''examen clinique et radiographique, les deux fémurs sont consolides et bien alignes. mais le tibia droit présente un cal vicieux avec angulation de 10° en varus. Il existe des signes d''ostéite avec une fistule qui s''ouvre deux ou trois fois par an mais qui est actuellement cicatrisée.', false, true, 'Parmi les conseils thérapeutiques suivants, un est à exclure de façon impérative :', '[{"l":"A","t":"La rééducation fonctionnelle","c":false},{"l":"B","t":"Les infiltrations intra-articulaires de corticoïdes","c":true},{"l":"C","t":"Le traitement chirurgical de l''ostéïté","c":false},{"l":"D","t":"Le changement de métier","c":false},{"l":"E","t":"La prescription d''anti inflammatoires non stéroïdiens","c":false}]'::jsonb, 'L''utilisation de corticoïdes, même par voie articulaire, est à proscrire en raison de l''ostéite récente.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2371, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un garçon de 23 ans a noté une modification de ses traits depuis 3 ans. Ses extrémités se sont épaissies. Il a du changer de paires de chaussures. Il a remarqué que son visage s''était modifié. Il présente des arthralgies au niveau des deux poignets : il se plaint de céphalées à prédominance matinale.', false, true, 'Le diagnostic le plus vraisemblable est :', '[{"l":"A","t":"Une hypoparathyroïdie","c":false},{"l":"B","t":"Une hypothyroïdie","c":false},{"l":"C","t":"Une acromégalie","c":true},{"l":"D","t":"Un hypercortisolisme","c":false},{"l":"E","t":"Un hypogonadisme","c":false}]'::jsonb, 'Le tableau est typique. Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2372, 10, 'Rhumatologie', 'Rhumatismes endocriniens (acromégalie)', 'Un garçon de 23 ans a noté une modification de ses traits depuis 3 ans. Ses extrémités se sont épaissies. Il a du changer de paires de chaussures. Il a remarqué que son visage s''était modifié. Il présente des arthralgies au niveau des deux poignets : il se plaint de céphalées à prédominance matinale.', false, true, 'Ce syndrome est souvent associé avec :', '[{"l":"A","t":"Une phosphorémie basse, une hypoglycémie, une cholestérolémie élevée","c":false},{"l":"B","t":"Un diabète, un épaississement des parties molles, une hémianopsie bitemporale","c":true},{"l":"C","t":"Une ostéoporose, des vergetures, une hypertension artérielle","c":false},{"l":"D","t":"Une augmentation de la densité osseuse, une hypocalcémie","c":false},{"l":"E","t":"Aucun de ces groupements symptomatiques","c":false}]'::jsonb, 'L''épaississement des parties molles est à la base du syndrome dysmorphique. Il existe une hyperphosphorémie surtout nette au moment des poussées, un véritable diabète est associé dans 10% des cas. L''hémianopsie bi-temporale doit faire rechercher une tumeur hypophysaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2373, 10, 'Rhumatologie', 'Rhumatismes endocriniens (acromégalie)', 'Un garçon de 23 ans a noté une modification de ses traits depuis 3 ans. Ses extrémités se sont épaissies. Il a du changer de paires de chaussures. Il a remarqué que son visage s''était modifié. Il présente des arthralgies au niveau des deux poignets : il se plaint de céphalées à prédominance matinale.', false, true, 'Les radiographies osseuses révèlent habituellement dans ce type d''affection :', '[{"l":"A","t":"Une résorption sous-périostée, des kystes osseux, un effondrement vertébral","c":false},{"l":"B","t":"Une calcification des ganglions de la base, une densité osseuse augmentée des calcifications ectopiques","c":false},{"l":"C","t":"Une ostéoporose, un amaincissement du crâne","c":false},{"l":"D","t":"Un allongement du maxillaire inférieur, une selle turcique augmentée de volume, un épaississement des parties molles","c":true},{"l":"E","t":"Aucune anomalie osseuse","c":false}]'::jsonb, 'Le prognathisme vrai, l''épaississement des parties molles, l''épaississement de la voûte et l''hypertrophie des sinus frontaux et maxillaires font partie du tableau radiologique. La suspicion d''adénome hypophysaire doit faire rechercher un élargissement de la selle turcique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2374, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Un garçon de 23 ans a noté une modification de ses traits depuis 3 ans. Ses extrémités se sont épaissies. Il a du changer de paires de chaussures. Il a remarqué que son visage s''était modifié. Il présente des arthralgies au niveau des deux poignets : il se plaint de céphalées à prédominance matinale.', false, true, 'Ces patients présentent souvent de manière associée :', '[{"l":"A","t":"Un goître, une hypersudation, une hyperséborrhée","c":true},{"l":"B","t":"Une captation élevée d''iode radioactif, une hypercalcémie avec lithiase rénale","c":false},{"l":"C","t":"Une hyperplasie surrénalienne","c":false},{"l":"D","t":"Une hypoglycémie, une poly-adénomatose endocrinienne avec histoire familiale","c":false},{"l":"E","t":"Une phosphorémie normale avec phosphatase alcaline élevée","c":false}]'::jsonb, 'La peau est hyperséborrhéique, infiltrée, rugueuse avec des sueurs abondantes. Il existe une hyperphosphorémie, une hypercalciurie avec lithiase rénale, un hypogonadisme, un goltre euthyroïdien et un retentissement surrénalien modéré, rarement, l''acromégalie est une manifestation d''une polyadénomatose de type 1 (adénome hypophysaire et parathyroïdien, tumeur pancréatique).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2375, 23, 'Rhumatologie', 'Déviations rachidiennes : scoliose, cyphose', 'Un malade est suivi pour une spondylarthrite ankylosante. A la suite d''une chute, il se plaint d''une douleur lombaire surtout vive en position debout et aux mouvements. Cette douleur n''est pas améliorée par les antiinflammatoires non stéroïdiens (AINS) alors que sous AINS, il n''a pas les douleurs nocturnes qui le réveillaient chaque nuit auparavant. L''examen montre que la distance C7-mur qui était de 8 cm un an avant est passée à 12 cm. Mains-sol : 32 cm inchangée. Les radiographies montrent comme l''année précédente une sacroiliite bilatérale stade II, des syndesmophytes dorsolombaires et une fusion des articulaires postérieures dorsales basses et lombaires. Sont apparus un pincement du disque L1-L2, une condensation des plateaux en regard et une solution de continuité sur l''arc postérieur', false, true, 'L''augmentation de la distance C7-mur traduit l''aggravation de quelle déformation ?', '[{"l":"A","t":"Projection du cou en avant","c":false},{"l":"B","t":"Lordose lombaire","c":false},{"l":"C","t":"Cyphose dorsale","c":true},{"l":"D","t":"Luxation cervico-occipitale","c":false},{"l":"E","t":"Scoliose à court rayon","c":false}]'::jsonb, 'La raideur cervicale ne permet plus de compenser l''aggravation de la cyphose dorso-lombaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2376, 9, 'Rhumatologie', 'Spondylarthrites', 'Un malade est suivi pour une spondylarthrite ankylosante. A la suite d''une chute, il se plaint d''une douleur lombaire surtout vive en position debout et aux mouvements. Cette douleur n''est pas améliorée par les antiinflammatoires non stéroïdiens (AINS) alors que sous AINS, il n''a pas les douleurs nocturnes qui le réveillaient chaque nuit auparavant. L''examen montre que la distance C7-mur qui était de 8 cm un an avant est passée à 12 cm. Mains-sol : 32 cm inchangée. Les radiographies montrent comme l''année précédente une sacroiliite bilatérale stade II, des syndesmophytes dorsolombaires et une fusion des articulaires postérieures dorsales basses et lombaires. Sont apparus un pincement du disque L1-L2, une condensation des plateaux en regard et une solution de continuité sur l''arc postérieur', false, true, 'Quelle(s) mesure(s) faut-il prendre pour corriger cette déformation ?', '[{"l":"A","t":"Postures à plat ventre","c":true},{"l":"B","t":"Traitement de fond par la Salazopyrine®","c":false},{"l":"C","t":"Port d''un collier cervical","c":false},{"l":"D","t":"Gymnastique intensive","c":true},{"l":"E","t":"Port d''un corset plâtré de Swain","c":false}]'::jsonb, 'Les exercices de postures et la gymnastique, plusieurs fois par jour s''efforceront de maintenir le rachis dorsal en rectitude et le rachis lombaire en lordose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2377, 9, 'Rhumatologie', 'Spondylarthrites', 'Un malade est suivi pour une spondylarthrite ankylosante. A la suite d''une chute, il se plaint d''une douleur lombaire surtout vive en position debout et aux mouvements. Cette douleur n''est pas améliorée par les antiinflammatoires non stéroïdiens (AINS) alors que sous AINS, il n''a pas les douleurs nocturnes qui le réveillaient chaque nuit auparavant. L''examen montre que la distance C7-mur qui était de 8 cm un an avant est passée à 12 cm. Mains-sol : 32 cm inchangée. Les radiographies montrent comme l''année précédente une sacroiliite bilatérale stade II, des syndesmophytes dorsolombaires et une fusion des articulaires postérieures dorsales basses et lombaires. Sont apparus un pincement du disque L1-L2, une condensation des plateaux en regard et une solution de continuité sur l''arc postérieur', false, true, 'Chez ce malade, l''atteinte sacro-iliaque bilatérale classée stade II, se traduit radiologiquement par :', '[{"l":"A","t":"Un pincement irrégulier de l''interligne","c":true},{"l":"B","t":"Une fusion des deux os","c":false},{"l":"C","t":"Un pseudoélargissement de l''interligne","c":false},{"l":"D","t":"Une condensation des berges sacrées et iliaques","c":true},{"l":"E","t":"Des géodes sous chondrales dans une condensation de la berge iliaque","c":false}]'::jsonb, 'Q.C.M. équivoque en raison des 2 classifications en vigueur : celle de Forestier et celle de Dilsen (en 4 stades).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2378, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Un malade est suivi pour une spondylarthrite ankylosante. A la suite d''une chute, il se plaint d''une douleur lombaire surtout vive en position debout et aux mouvements. Cette douleur n''est pas améliorée par les antiinflammatoires non stéroïdiens (AINS) alors que sous AINS, il n''a pas les douleurs nocturnes qui le réveillaient chaque nuit auparavant. L''examen montre que la distance C7-mur qui était de 8 cm un an avant est passée à 12 cm. Mains-sol : 32 cm inchangée. Les radiographies montrent comme l''année précédente une sacroiliite bilatérale stade II, des syndesmophytes dorsolombaires et une fusion des articulaires postérieures dorsales basses et lombaires. Sont apparus un pincement du disque L1-L2, une condensation des plateaux en regard et une solution de continuité sur l''arc postérieur', false, true, 'Quelle est la nature de la lésion discale L1-L2 apparue depuis un an ?', '[{"l":"A","t":"Arthrose pseudopottique","c":false},{"l":"B","t":"Spondylodiscite à Klebsiella Pneumoniae","c":false},{"l":"C","t":"Spondylodiscite inflammatoire de la Sp A","c":true},{"l":"D","t":"Pseudospondylodiscite sur une zone hypermobile","c":false},{"l":"E","t":"Mal de Pott","c":false}]'::jsonb, 'Le pincement d''un disque au cours d''une spondylarthrite ankylosante fait évoquer une spondylodiscite inflammatoire. La condensation des plateaux est en faveur d''une atteinte cicatricielle.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2379, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Quel est le diagnostic clinique le plus probable ?', '[{"l":"A","t":"Luxation postéro-supérieure de hanche","c":false},{"l":"B","t":"Fracture de l''ischion","c":false},{"l":"C","t":"Fracture du cotyle","c":false},{"l":"D","t":"Fracture par arrachement du grand trochanter","c":false},{"l":"E","t":"Fracture du col du fémur","c":true}]'::jsonb, 'Impotence fonctionnelle complète chez une femme âgée après une chute avec raccourcissement, adduction et rotation externe du membre inférieur droit : un seul diagnostic à suspecter et à confirmer par des radiographies.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2380, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Le bilan radiologique que vous demandez en urgence comporte :', '[{"l":"A","t":"Bassin de face","c":true},{"l":"B","t":"Grands axes des membres inférieurs","c":false},{"l":"C","t":"Hanche droite face et profil","c":true},{"l":"D","t":"Clichés dynamiques de hanche droite en abduction et adduction","c":false},{"l":"E","t":"Radiographie pulmonaire","c":true}]'::jsonb, 'A et C sont nécessaires et suffisants pour le diagnostic. La radiographie de thorax est demandée à visée préopératoire et en raison des antécédents.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2381, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Quel(s) autre(s) examen(s) vous parai(ssen)t utile(s) parmi ceux-ci ?', '[{"l":"A","t":"Epreuve cardiaque d''effort","c":false},{"l":"B","t":"Gaz du sang","c":true},{"l":"C","t":"Recherche d''un facteur rhumatoïde","c":false},{"l":"D","t":"Tests de coagulation","c":true},{"l":"E","t":"Scintigraphie osseuse","c":false}]'::jsonb, 'Il faut évaluer le retentissement de l''insuffisance respiratoire et rechercher un effet shunt en faveur d''une embolie pulmonaire (immobilisation, fièvre, varices).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2382, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Parmi ces prescriptions, il faut mettre immédiatement en oeuvre :', '[{"l":"A","t":"Une transfusion sanguine","c":false},{"l":"B","t":"Une rééquilibration ionique","c":true},{"l":"C","t":"Un anticoagulant","c":true},{"l":"D","t":"Une traction du membre","c":false},{"l":"E","t":"Une antibiothérapie à large spectre","c":false}]'::jsonb, 'La réhydratation est indispensable de même qu''un traitement prophylactique de la thrombose sur ce terrain.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2383, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Si un acte chirurgical est nécessaire, il devrait être logiquement pour vous :', '[{"l":"A","t":"Une abstention chirurgicale","c":false},{"l":"B","t":"Une ostéosynthèse par vis","c":false},{"l":"C","t":"Une ostéosynthèse par clous de Ender","c":false},{"l":"D","t":"Une prothèse totale","c":true},{"l":"E","t":"Une prothèse céphalique","c":false}]'::jsonb, 'En raison de l''âge (prothèse céphalique) et des antécédents de coxarthrose droite (prothèse cotyloïdienne).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2384, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 70 ans, vivant seule chez elle, est retrouvée sur le sol dans sa cuisine par ses voisins, 24 heures après une chute d''un escabeau. Elle est consciente mais déshydratée. Elle est incapable de se relever du fait d''une impotence fonctionnelle totale du membre inférieur droit. Celui ci paraît raccourci, en adduction et rotation externe. La température est à 38.5°. Le médecin habituel de cette malade, appelé en urgence, demande l''hospitalisation et note sur son certificat ses antécédents : - Varices volumineuses bilatérales - Insuffisance respiratoire chronique - Coxarthrose droite évoluée', false, true, 'Si un acte chirurgical est effectué, il devient alors justifié d''instituer :', '[{"l":"A","t":"Lutte anti-escarre","c":true},{"l":"B","t":"Kinésithérapie respiratoire","c":true},{"l":"C","t":"Traitement anticoagulant","c":true},{"l":"D","t":"Bandages élastiques des membres","c":true},{"l":"E","t":"Lever précoce","c":true}]'::jsonb, 'Les principales complications précoces de la chirurgie sont : - accidents thromboemboliques - encombrement respiratoire et infections - incontinence et infections urinaires - escarres aux points d''appui - désorientation temporo-spatiale - complications locales de la prothèse : luxation, infection, paralysie sciatique, hématome.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2385, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame D.25 ans, est hospitalisée pour des polyarthralgies touchant les coudes et les genoux. L''interrogatoire ne retrouve aucun antécédent, ni prise médicamenteuse. L''examen clinique met en évidence des ulcérations buccales et un frottement péricardique. Le bilan biologique objective une anémie normochrome normocytaire régénérative avec Coombs direct positif et une protéinurie. Le bilan hépatique est normal. L''électrophorèse des protides montre une hyperalpha2globulinémie et une hypergammaglobulinémie. La VS est augmentée. Le diagnostic de lupus érythémateux disséminé est évoqué.', false, true, 'Ce diagnostic pourrait également être évoqué devant :', '[{"l":"A","t":"Hypocomplémentémie","c":true},{"l":"B","t":"Présence d''anticorps anti-IgG","c":false},{"l":"C","t":"Immunofluorescence anti-noyau positive au 1/10 000","c":true},{"l":"D","t":"Diminution du pourcentage des lymphocytes T8+","c":false},{"l":"E","t":"Présence de cryoglobuline","c":false}]'::jsonb, 'Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2386, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame D.25 ans, est hospitalisée pour des polyarthralgies touchant les coudes et les genoux. L''interrogatoire ne retrouve aucun antécédent, ni prise médicamenteuse. L''examen clinique met en évidence des ulcérations buccales et un frottement péricardique. Le bilan biologique objective une anémie normochrome normocytaire régénérative avec Coombs direct positif et une protéinurie. Le bilan hépatique est normal. L''électrophorèse des protides montre une hyperalpha2globulinémie et une hypergammaglobulinémie. La VS est augmentée. Le diagnostic de lupus érythémateux disséminé est évoqué.', false, true, 'Quel(s) est(sont) celui(ceux) dont la positivité est en faveur du diagnostic ?', '[{"l":"A","t":"Présence d''anticorps anti-RNP","c":false},{"l":"B","t":"Présence d''anticorps anti-DNA natif","c":true},{"l":"C","t":"Présence d''anticorps anti-Sm","c":true},{"l":"D","t":"Présence d''anticorps anti-DNA dénaturé","c":false},{"l":"E","t":"Présence d''anticorps anti-centromère","c":false}]'::jsonb, 'Les anti-ADN natifs (de type IgG) et les anti-Sm sont très spécifiques du LED.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2387, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame D.25 ans, est hospitalisée pour des polyarthralgies touchant les coudes et les genoux. L''interrogatoire ne retrouve aucun antécédent, ni prise médicamenteuse. L''examen clinique met en évidence des ulcérations buccales et un frottement péricardique. Le bilan biologique objective une anémie normochrome normocytaire régénérative avec Coombs direct positif et une protéinurie. Le bilan hépatique est normal. L''électrophorèse des protides montre une hyperalpha2globulinémie et une hypergammaglobulinémie. La VS est augmentée. Le diagnostic de lupus érythémateux disséminé est évoqué.', false, true, 'Le diagnostic étant confirmé, indiquez celui ou ceux qui vous parai(ssen)t utile(s) pour suivre l''évolution :', '[{"l":"A","t":"Complément hémolytique sérique total CH 50","c":true},{"l":"B","t":"Anticorps anti-muscle lisse","c":false},{"l":"C","t":"Anticorps anti-microsomes thyroïdiens","c":false},{"l":"D","t":"Facteur rhumatoïde","c":false},{"l":"E","t":"Anticorps anti-DNA natif","c":true}]'::jsonb, 'Sont aussi nécessaires, la numération formule sanguine, la VS, les sous-fractions C3-C4, la créatininémie, la protéinurie des 24 heures et le sédiment urinaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2388, 2, 'Rhumatologie', 'Connectivites et vascularites', 'Madame D.25 ans, est hospitalisée pour des polyarthralgies touchant les coudes et les genoux. L''interrogatoire ne retrouve aucun antécédent, ni prise médicamenteuse. L''examen clinique met en évidence des ulcérations buccales et un frottement péricardique. Le bilan biologique objective une anémie normochrome normocytaire régénérative avec Coombs direct positif et une protéinurie. Le bilan hépatique est normal. L''électrophorèse des protides montre une hyperalpha2globulinémie et une hypergammaglobulinémie. La VS est augmentée. Le diagnostic de lupus érythémateux disséminé est évoqué.', false, true, 'Citez la(les) localisation(s) clinique(s) pouvant mettre en jeu la vie du malade :', '[{"l":"A","t":"Cutanée","c":false},{"l":"B","t":"Rénale","c":true},{"l":"C","t":"Pleurale","c":false},{"l":"D","t":"Articulaire","c":false},{"l":"E","t":"Cérébrale","c":true}]'::jsonb, 'Les localisations cérébrales semblent plus fréquentes en cas de présence d''anticorps anti-cardiolipidiques. Elles semblent associées à une augmentation du C3a et sont très bien visualisées par l''IRM cérébrale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2389, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un malade de 45 ans, conducteur de poids lourds, souffre depuis trois mois, après un effort de soulèvement, d''une douleur lombaire irradiant à la fesse gauche, à la face postéro-latérale de la cuisse, à la face externe de la jambe, pour gagner le dessus du pied gauche. Cette douleur, d''horaire mécanique, calmée par le repos, est impulsive à la toux et s''accompagne de paresthésies plantaires. Antécédents : lombalgies chroniques depuis dix ans avec épisodes de lumbagos, intervention pour hernie inguinale gauche il y a quatre ans.', false, true, 'Parmi les signes cliniques suivants, indiquez celui ou ceux qui seraient en rapport avec les atteintes monoradiculaires présentées par ce malade ?', '[{"l":"A","t":"Parésie du moyen fessier","c":true},{"l":"B","t":"Impossibilité de marcher sur la pointe du pied","c":false},{"l":"C","t":"Diminution du réflexe rotulien","c":false},{"l":"D","t":"Hypoesthésie de la face dorsale du pied et du gros orteil","c":true},{"l":"E","t":"Abolition du réflexe crémastérien","c":false}]'::jsonb, 'QCM discutable car la sciatique n''est pas totalement monoradiculaire : trajet L5 typique avec paresthésies plantaires de type S1. Vraisemblable volumineuse hernie discale L4 L5 gauche comprimant la racine L5 gauche et déviant la racine S1 gauche. Si l''on considère qu''il s''agit d''une sciatique monoradiculaire L5 : A et D sont les 2 seules réponses.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2390, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un malade de 45 ans, conducteur de poids lourds, souffre depuis trois mois, après un effort de soulèvement, d''une douleur lombaire irradiant à la fesse gauche, à la face postéro-latérale de la cuisse, à la face externe de la jambe, pour gagner le dessus du pied gauche. Cette douleur, d''horaire mécanique, calmée par le repos, est impulsive à la toux et s''accompagne de paresthésies plantaires. Antécédents : lombalgies chroniques depuis dix ans avec épisodes de lumbagos, intervention pour hernie inguinale gauche il y a quatre ans.', false, true, 'Parmi les signes radiologiques suivants, lequel(lesquels) vous ferait(feraient) douter du diagnostic de sciatique commune par hernie discale ?', '[{"l":"A","t":"Disques L4-L5 et L5-S1 normaux","c":true},{"l":"B","t":"Baillement postérieur L4-L5","c":false},{"l":"C","t":"Effacement sur plateau inférieur de L4","c":true},{"l":"D","t":"Pincement L4-L5 avec érosion de l''angle antérosupérieur de L5","c":true},{"l":"E","t":"Tassement du corps vertébral L4","c":true}]'::jsonb, 'Le baillement postérieur est un très bon signe de hernie discale sur les clichés radiologiques standard.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2391, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un malade de 45 ans, conducteur de poids lourds, souffre depuis trois mois, après un effort de soulèvement, d''une douleur lombaire irradiant à la fesse gauche, à la face postéro-latérale de la cuisse, à la face externe de la jambe, pour gagner le dessus du pied gauche. Cette douleur, d''horaire mécanique, calmée par le repos, est impulsive à la toux et s''accompagne de paresthésies plantaires. Antécédents : lombalgies chroniques depuis dix ans avec épisodes de lumbagos, intervention pour hernie inguinale gauche il y a quatre ans.', false, true, 'Malgré la mise en oeuvre d''un traitement médical approprié, la douleur sciatique persiste, bien que la lombalgie se soit améliorée. L''indication d''une sacco-radiculographie d''urgence sera décidée en raison de la constatation clinique récente de :', '[{"l":"A","t":"Intolérance et inefficacité des anti-inflammatoires","c":false},{"l":"B","t":"Sensation de refroidissement du pied gauche","c":false},{"l":"C","t":"Persistance des lombalgies","c":false},{"l":"D","t":"Nécessité de pousser pour uriner","c":true},{"l":"E","t":"Hypoesthésie périnéale","c":true}]'::jsonb, 'La découverte de signes évocateurs de syndrome de la queue de cheval fait poser l''indication opératoire en urgence.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2392, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', 'Un malade de 45 ans, conducteur de poids lourds, souffre depuis trois mois, après un effort de soulèvement, d''une douleur lombaire irradiant à la fesse gauche, à la face postéro-latérale de la cuisse, à la face externe de la jambe, pour gagner le dessus du pied gauche. Cette douleur, d''horaire mécanique, calmée par le repos, est impulsive à la toux et s''accompagne de paresthésies plantaires. Antécédents : lombalgies chroniques depuis dix ans avec épisodes de lumbagos, intervention pour hernie inguinale gauche il y a quatre ans.', false, true, 'Une sacco-radiculographie est faite. Le liquide céphalo-rachidien est analysé à cette occasion. Indiquez la ou les formule(s) compatible(s) avec une origine discale de cette sciatique ?', '[{"l":"A","t":"Protéinorachie à 0,30 g/l, moins de un élément par mm3","c":true},{"l":"B","t":"Protéinorachie à 0,30 g/l, 300 éléments par mm3","c":false},{"l":"C","t":"Protéinorachie à 0,15 g/l, moins de un élément par mm3","c":false},{"l":"D","t":"Abaissement des sucres et des chlorures","c":false},{"l":"E","t":"Protéinorachie à 0,90 g/l, moins de un élément par mm3","c":true}]'::jsonb, 'La cellularité doit être normale. La protéinorachie est normale ou élevée (théoriquement inférieure à 1g/litre). L''hypoprotéinorachie n''est pas évocatrice de hernie discale (elle est retrouvée lors de cul-des-sacs duraux larges).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2393, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'A la suite d''un accident, le conducteur, âgé de 40 ans, est retrouvé éjecté de son véhicule, conscient, mais incapable d''un mouvement volontaire de ses quatre membres. Il n''avait, dans son véhicule, ni appui-tête, ni ceinture de sécurité. A un premier examen rapide de ses membres, on ne retrouve aucune plaie ni aucune désaxation majeure.', false, true, 'Vous êtes de garde et vous recevez ce blessé. Si le SAMU l''a correctement transporté, vous devez constater que :', '[{"l":"A","t":"Il a le cou en hyper-extension","c":false},{"l":"B","t":"Il est en position latérale de sécurité","c":false},{"l":"C","t":"Il est sur le dos avec un coussin sous la tête","c":false},{"l":"D","t":"Il est à plat ventre avec un coussin sous le menton","c":false},{"l":"E","t":"Il est en alignement tête-cou-tronc","c":true}]'::jsonb, 'Chez tout patient suspect de traumatisme du rachis, il est essentiel de rechercher des signes de détresse respiratoire (C4) et de l''immobiliser en rectitude tête-cou-tronc.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2394, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'A la suite d''un accident, le conducteur, âgé de 40 ans, est retrouvé éjecté de son véhicule, conscient, mais incapable d''un mouvement volontaire de ses quatre membres. Il n''avait, dans son véhicule, ni appui-tête, ni ceinture de sécurité. A un premier examen rapide de ses membres, on ne retrouve aucune plaie ni aucune désaxation majeure.', false, true, 'Parmi ces propositions, laquelle ou lesquelles acceptez-vous ?', '[{"l":"A","t":"Vous le retournez pour palper les apophyses épineuses","c":false},{"l":"B","t":"Vous recherchez des signes de section médullaire complète","c":true},{"l":"C","t":"Vous vérifiez les amplitudes de mobilité du rachis cervical","c":false},{"l":"D","t":"Vous demandez des clichés standard du crâne et face et profil de tout le rachis","c":true},{"l":"E","t":"Vous demandez des clichés bouche ouverte du rachis cervical supérieur","c":true}]'::jsonb, 'Il ne faut surtout pas mobiliser le patient, tout l''axe tête-cou-tronc doit être exploré radiologiquement, y compris l''étage C1-C2 et l''odontoïde.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2395, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'A la suite d''un accident, le conducteur, âgé de 40 ans, est retrouvé éjecté de son véhicule, conscient, mais incapable d''un mouvement volontaire de ses quatre membres. Il n''avait, dans son véhicule, ni appui-tête, ni ceinture de sécurité. A un premier examen rapide de ses membres, on ne retrouve aucune plaie ni aucune désaxation majeure.', false, true, 'Les signes cliniques présents vont orienter votre diagnostic topographique vers :', '[{"l":"A","t":"Les masses latérales de l''atlas","c":false},{"l":"B","t":"L''odontoïde","c":false},{"l":"C","t":"Le rachis cervical inférieur de C3 à C7","c":true},{"l":"D","t":"La charnière cervico-dorsale","c":false},{"l":"E","t":"La charnière dorso-lombaire","c":false}]'::jsonb, 'Il existe une tétraplégie sans détresse respiratoire, la lésion siège donc en dessous de C4 et au niveau de C5-C6 au moins.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2396, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'A la suite d''un accident, le conducteur, âgé de 40 ans, est retrouvé éjecté de son véhicule, conscient, mais incapable d''un mouvement volontaire de ses quatre membres. Il n''avait, dans son véhicule, ni appui-tête, ni ceinture de sécurité. A un premier examen rapide de ses membres, on ne retrouve aucune plaie ni aucune désaxation majeure.', false, true, 'Les premiers clichés effectués ne montrent pas de fracture sur la localisation anatomique suggérée par l''examen neurologique. Il faut alors rechercher :', '[{"l":"A","t":"Un traumatisme crânien passé inaperçu avec lésions neurologiques","c":false},{"l":"B","t":"Une entorse grave C1-C2 réduite","c":false},{"l":"C","t":"Une luxation D12-L1","c":false},{"l":"D","t":"Une entorse grave entre C3 et C7 réduite","c":true},{"l":"E","t":"Une thrombose des artères vertébrales","c":false}]'::jsonb, 'S''il n''existe pas de fracture évidente, une entorse grave est vraisemblablement responsable de cette lésion médullaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2397, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', 'A la suite d''un accident, le conducteur, âgé de 40 ans, est retrouvé éjecté de son véhicule, conscient, mais incapable d''un mouvement volontaire de ses quatre membres. Il n''avait, dans son véhicule, ni appui-tête, ni ceinture de sécurité. A un premier examen rapide de ses membres, on ne retrouve aucune plaie ni aucune désaxation majeure.', false, true, 'Pour affirmer votre diagnostic, lequel ou lesquels de ces examens complémentaires radiologiques vous paraissent utile ?', '[{"l":"A","t":"Un scanner crânien","c":false},{"l":"B","t":"Une artériographie des troncs supra-aortiques","c":false},{"l":"C","t":"Un scanner rachidien","c":true},{"l":"D","t":"Des épreuves dynamiques","c":false},{"l":"E","t":"Une myélographie","c":true}]'::jsonb, 'Le scanner peut déceler de minimes lésions osseuses, l''IRM semble riche de promesse (hématomes,...).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2398, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'Les clichés radiologiques devraient montrer :', '[{"l":"A","t":"Une vertèbre borgne","c":false},{"l":"B","t":"Une vertèbre en cadre","c":false},{"l":"C","t":"Un tassement vertébral","c":true},{"l":"D","t":"Un plateau vertébral estompé","c":false},{"l":"E","t":"Des géodes intra-somatiques","c":false}]'::jsonb, 'Le tassement de l''ostéoporose commune siège de D4 à L4 ou L5 . Il a un aspect de déformation cunéiforme antérieure au début, puis secondairement, et éventuellement, un aspect biconcave ou en galette avec respect du mur postérieur de la vertébre sans altération des plateaux ou des pédicules, avec un aspect homogène.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2399, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'La biopsie osseuse iliaque confirmerait le diagnostic en montrant :', '[{"l":"A","t":"Des îlots plasmocytaires","c":false},{"l":"B","t":"Une hyperostéoïdose avec ralentissement de la minéralisation","c":false},{"l":"C","t":"Une augmentation des surfaces de résorption ostéoclastique","c":false},{"l":"D","t":"Une diminution du volume trabéculaire osseux","c":true},{"l":"E","t":"Une structure osseuse lamellaire en mosaïque","c":false}]'::jsonb, 'Il s''agit de lésions de base. Une hyper-résorption ostéoclastique peut exister et définit l''ostéoporose à haut niveau de remodelage.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2400, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'Quel(s) facteur(s) de risque pour l''ostéoporose chez cette patiente retenez-vous dans l''observation ?', '[{"l":"A","t":"L''âge = 68 ans","c":true},{"l":"B","t":"Les antécédents de maladie de Basedow","c":true},{"l":"C","t":"L''hystéro-ovariectomie à 38 ans","c":true},{"l":"D","t":"Le poids pour la taille","c":true},{"l":"E","t":"Les antécédents de tuberculose pleurale","c":false}]'::jsonb, 'La ménopause précoce par castration chirurgicale sans traitement substitutif est le principal facteur de risque avec l''âge (ménopausée depuis 30 ans). L''hyperthyroïdie est une cause d''ostéoporose, pour les antécédents d''hyperthyroïdie, c''est moins certains. L''obésité protège de l''ostéoporose.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2401, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'Pour affirmer le diagnostic d''ostéoporose, vous pensez qu''il est nécessaire de demander en plus :', '[{"l":"A","t":"Une détermination du calcium total de l''organisme","c":false},{"l":"B","t":"Un examen tomodensitométrique du rachis","c":false},{"l":"C","t":"Une radiographie du bassin","c":false},{"l":"D","t":"Une scintigraphie osseuse","c":false},{"l":"E","t":"Aucun des examens précédents","c":true}]'::jsonb, 'La biopsie osseuse en double marquage suffit.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2402, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'Pour traiter l''ostéoporose de cette malade vous donnerez :', '[{"l":"A","t":"Une corticothérapie per os 0,1 mg/kg","c":false},{"l":"B","t":"Du fluorure de sodium 5 mg/j","c":false},{"l":"C","t":"De la vitamine D 400 U/j","c":true},{"l":"D","t":"Du calcium 1 g/j","c":true},{"l":"E","t":"Du disphosphonate 1 mg/24h","c":false}]'::jsonb, 'QCM discutable. Les doses de fluorure de sodium sont de 50 mg par jour et les doses de vitamine D sont cinq à dix fois supérieures.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2403, 15, 'Rhumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Une femme de 68 ans mesurant 1,60m et pesant 48 kg se plaint depuis dix jours d''une douleur dorsale basse, apparue brutalement sans cause évidente, très vive, rendant la station debout presque impossible, soulagée en partie par le décubitus. Elle a souffert dans l''adolescence d''une pleurésie tuberculeuse, a subi 30 ans auparavant une thyroïdectomie pour Basedow et peu après une hystérectomie pour fibrome ; enfin deux ans plus tôt, elle a été traitée pour une fracture de l''extrémité inférieure du radius. L''examen clinique montre une douleur localisée vers la région dorso-lombaire ainsi qu''une raideur rachidienne à ce niveau. Le reste de l''examen clinique est normal (température à 37°C). Après un certain nombre d''examens para-cliniques, le diagnostic d''ostéoporose commune est établi.', false, true, 'Non traitée, l''évolution de cette ostéoporose comporte un risque de :', '[{"l":"A","t":"Fracture du col fémoral","c":false},{"l":"B","t":"Rétrécissement du canal rachidien","c":false},{"l":"C","t":"Nouveaux tassements de vertèbres","c":true},{"l":"D","t":"Fractures de côtes","c":false},{"l":"E","t":"Compression médullaire","c":false}]'::jsonb, 'De nouveaux tassements peuvent survenir pendant les 6 premiers mois du traitement. La fracture du col fémoral est toujours possible.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2404, 10, 'Rhumatologie', 'Maladie de Paget', 'Un homme de 70 ans se plaint de céphalées persistantes et d''une surdité progressive. Il souffre depuis trois mois de lombalgies mécaniques modérées et depuis 15 jours de douleurs importantes de la cuisse droite. A l''examen le rachis lombaire est enraidi, peu douloureux. La jambe gauche est le siège d''une incurvation dans les deux plans, avec genu varum. La température cutanée en regard est augmentée. Les examens biologiques montrent une N.F.S., une V.S., une électrophorèse sanguine et urinaire normales, une calcémie à 100 mg/l, une phosphorémie à 32 mg/l, une calciurie à 155 mg/24 h, des phosphatases acides à 5,5 UI/l (normale 3-8), des phosphatases alcalines à 450 UI/l (normale 80-220 UII/l); une hydroxyprolinurie à 95 mg/24 h (normale 40 mg/24 h). Les radiographies objectivent des discopathies lombaires étagées avec pincement discal L4-L5, une ostéophytose lombaire, une hypertrophie avec élargissement des corticales du fémur droit et du t bia gauche, une fissure de la convexité du fémur droit, un aspect fibrillaire anarchique de l''hémi-bassin droit, une condensation avec hypertrophie des os de la base du crâne, une ostéoporose circonscrite fronto-pariétale droite. Le diagnostic de maladie de Paget est retenu.', false, true, 'Quel(s) élément(s) clinique(s) peut(peuvent) être en rapport avec la maladie de Paget ?', '[{"l":"A","t":"Céphalées persistantes","c":true},{"l":"B","t":"Hypo-acousie","c":true},{"l":"C","t":"Lombalgies","c":false},{"l":"D","t":"Augmentation de la température locale de la jambe gauche","c":true},{"l":"E","t":"Douleurs de la cuisse droite","c":true}]'::jsonb, 'Les lombalgies sont mécaniques et très probablement en rapport avec les discopathies lombaires étagées. Les céphalées et l''hypoacousie risquent d''être définitives. La douleur de cuisse droite peut être rattachée à l''atteinte de l''hémibassin ou au remodelage osseux fémoral (une fissure peut être l''amorce d''une fracture transversale).', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2405, 10, 'Rhumatologie', 'Maladie de Paget', 'Un homme de 70 ans se plaint de céphalées persistantes et d''une surdité progressive. Il souffre depuis trois mois de lombalgies mécaniques modérées et depuis 15 jours de douleurs importantes de la cuisse droite. A l''examen le rachis lombaire est enraidi, peu douloureux. La jambe gauche est le siège d''une incurvation dans les deux plans, avec genu varum. La température cutanée en regard est augmentée. Les examens biologiques montrent une N.F.S., une V.S., une électrophorèse sanguine et urinaire normales, une calcémie à 100 mg/l, une phosphorémie à 32 mg/l, une calciurie à 155 mg/24 h, des phosphatases acides à 5,5 UI/l (normale 3-8), des phosphatases alcalines à 450 UI/l (normale 80-220 UII/l); une hydroxyprolinurie à 95 mg/24 h (normale 40 mg/24 h). Les radiographies objectivent des discopathies lombaires étagées avec pincement discal L4-L5, une ostéophytose lombaire, une hypertrophie avec élargissement des corticales du fémur droit et du t bia gauche, une fissure de la convexité du fémur droit, un aspect fibrillaire anarchique de l''hémi-bassin droit, une condensation avec hypertrophie des os de la base du crâne, une ostéoporose circonscrite fronto-pariétale droite. Le diagnostic de maladie de Paget est retenu.', false, true, 'Quel(s) paramètre(s) biologique(s) témoigne(nt) de l''évolutivité de la maladie de Paget ?', '[{"l":"A","t":"Calcémie à 100 mg/l","c":false},{"l":"B","t":"Phosphorémie à 2 mg/l","c":false},{"l":"C","t":"Hydroxyprolinurie à 95 mg/24 h","c":true},{"l":"D","t":"Phosphatases acides à 5,5 UI/l","c":false},{"l":"E","t":"Phosphatases alcalines à 450 UI/l","c":true}]'::jsonb, 'Les phosphatases alcalines témoignent de l''hyperactivité des ostéoblastes et l''hydroxyprolinurie de celle des ostéoclastes. Sauf en cas d''immobilisation (fracture), la calcémie reste normale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2406, 10, 'Rhumatologie', 'Maladie de Paget', 'Un homme de 70 ans se plaint de céphalées persistantes et d''une surdité progressive. Il souffre depuis trois mois de lombalgies mécaniques modérées et depuis 15 jours de douleurs importantes de la cuisse droite. A l''examen le rachis lombaire est enraidi, peu douloureux. La jambe gauche est le siège d''une incurvation dans les deux plans, avec genu varum. La température cutanée en regard est augmentée. Les examens biologiques montrent une N.F.S., une V.S., une électrophorèse sanguine et urinaire normales, une calcémie à 100 mg/l, une phosphorémie à 32 mg/l, une calciurie à 155 mg/24 h, des phosphatases acides à 5,5 UI/l (normale 3-8), des phosphatases alcalines à 450 UI/l (normale 80-220 UII/l); une hydroxyprolinurie à 95 mg/24 h (normale 40 mg/24 h). Les radiographies objectivent des discopathies lombaires étagées avec pincement discal L4-L5, une ostéophytose lombaire, une hypertrophie avec élargissement des corticales du fémur droit et du t bia gauche, une fissure de la convexité du fémur droit, un aspect fibrillaire anarchique de l''hémi-bassin droit, une condensation avec hypertrophie des os de la base du crâne, une ostéoporose circonscrite fronto-pariétale droite. Le diagnostic de maladie de Paget est retenu.', false, true, 'Parmi les signes radiologiques, quel(s) est celui ou ceux en faveur de la maladie de Paget ?', '[{"l":"A","t":"Discopathies lombaires étagées","c":false},{"l":"B","t":"Fissure fémorale droite","c":true},{"l":"C","t":"Hypertrophie des corticales","c":true},{"l":"D","t":"Aspect fibrillaire anarchique de la trame","c":true},{"l":"E","t":"Ostéoporose circonscrite du crâne","c":true}]'::jsonb, 'La fissure siégeant sur la convexité d''un os long est très évocatrice, de même de l''ostéoporose circonscrite et l''aspect fibrillaire anarchique de la trame.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2407, 10, 'Rhumatologie', 'Maladie de Paget', 'Un homme de 70 ans se plaint de céphalées persistantes et d''une surdité progressive. Il souffre depuis trois mois de lombalgies mécaniques modérées et depuis 15 jours de douleurs importantes de la cuisse droite. A l''examen le rachis lombaire est enraidi, peu douloureux. La jambe gauche est le siège d''une incurvation dans les deux plans, avec genu varum. La température cutanée en regard est augmentée. Les examens biologiques montrent une N.F.S., une V.S., une électrophorèse sanguine et urinaire normales, une calcémie à 100 mg/l, une phosphorémie à 32 mg/l, une calciurie à 155 mg/24 h, des phosphatases acides à 5,5 UI/l (normale 3-8), des phosphatases alcalines à 450 UI/l (normale 80-220 UII/l); une hydroxyprolinurie à 95 mg/24 h (normale 40 mg/24 h). Les radiographies objectivent des discopathies lombaires étagées avec pincement discal L4-L5, une ostéophytose lombaire, une hypertrophie avec élargissement des corticales du fémur droit et du t bia gauche, une fissure de la convexité du fémur droit, un aspect fibrillaire anarchique de l''hémi-bassin droit, une condensation avec hypertrophie des os de la base du crâne, une ostéoporose circonscrite fronto-pariétale droite. Le diagnostic de maladie de Paget est retenu.', false, true, 'Quel(s) paramètre(s) biologique(s) devez-vous surveiller pour juger l''efficacité de votre traitement ?', '[{"l":"A","t":"V.S.","c":false},{"l":"B","t":"Calcémie","c":false},{"l":"C","t":"Phosphatases alcalines","c":true},{"l":"D","t":"Phosphorémie","c":false},{"l":"E","t":"Hydroxyprolinurie","c":true}]'::jsonb, 'La calcémie peut éventuellement être demandée pour dépister (tardivement) une hypothétique ostéomalacie.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2408, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Monsieur A..., 60 ans, est hospitalisé pour des lombalgies invalidantes depuis 15 jours, et résistantes aux antalgiques habituels. Il y a deux mois, il a subi deux cystoscopie pour une hématurie. Un polype a été enlevé et l''examen histologique a conclu à sa bénignité. Une U.I.V. élimine toute cause rénale. Quelques jours après la seconde exploration endoscopique, monsieur A... a présenté des frissons, un accès fébrile à 38°C, régressif sous antiseptique urinaire. Lors de son hospitalisation, la température est à 40°C, le faciès altéré, il se mobilise mal. La palpation réveille une douleur en L4-L5. Le reste de l''examen s''avère normal. La V.S. est à 100 mm à la première heure, les globules blancs sont à 18 000 dont 80 % de Polynucléaires Ionogrammes sanguin et urinaire sont normaux.', false, true, 'La radiographie standard du rachis lombaire montre une rectitude rachidienne. Le plateau supérieur de L5 est effacé. Le premier diagnostic à évoquer est :', '[{"l":"A","t":"Fracture sur ostéome décalcifiante","c":false},{"l":"B","t":"Maladie de Kahler","c":false},{"l":"C","t":"Spondylodiscite à germes banals","c":true},{"l":"D","t":"Pott lombaire","c":false},{"l":"E","t":"Métastase vertébrale","c":false}]'::jsonb, 'Diagnostic à évoquer en premier, au vu des antécédents d''exploration endoscopique urinaire à répétition et de pic fébrile.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2409, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Monsieur A..., 60 ans, est hospitalisé pour des lombalgies invalidantes depuis 15 jours, et résistantes aux antalgiques habituels. Il y a deux mois, il a subi deux cystoscopie pour une hématurie. Un polype a été enlevé et l''examen histologique a conclu à sa bénignité. Une U.I.V. élimine toute cause rénale. Quelques jours après la seconde exploration endoscopique, monsieur A... a présenté des frissons, un accès fébrile à 38°C, régressif sous antiseptique urinaire. Lors de son hospitalisation, la température est à 40°C, le faciès altéré, il se mobilise mal. La palpation réveille une douleur en L4-L5. Le reste de l''examen s''avère normal. La V.S. est à 100 mm à la première heure, les globules blancs sont à 18 000 dont 80 % de Polynucléaires Ionogrammes sanguin et urinaire sont normaux.', false, true, 'Une exploration biologique s''impose d''emblée. Laquelle ?', '[{"l":"A","t":"Sérodiagnostic de Wright","c":false},{"l":"B","t":"Dosage des phosphatases acides prostatiques","c":false},{"l":"C","t":"Dosage de la calcémie","c":false},{"l":"D","t":"Hémoculture","c":true},{"l":"E","t":"Dosage de l''hydroxyprolinurie","c":false}]'::jsonb, 'Les hémocultures, au moins trois, seront systématiques avec bien sûr nouvelle hémoculture en cas de fièvre supérieure à 38°5 ou de frissons jusqu''à isolement du germe.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2410, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Monsieur A..., 60 ans, est hospitalisé pour des lombalgies invalidantes depuis 15 jours, et résistantes aux antalgiques habituels. Il y a deux mois, il a subi deux cystoscopie pour une hématurie. Un polype a été enlevé et l''examen histologique a conclu à sa bénignité. Une U.I.V. élimine toute cause rénale. Quelques jours après la seconde exploration endoscopique, monsieur A... a présenté des frissons, un accès fébrile à 38°C, régressif sous antiseptique urinaire. Lors de son hospitalisation, la température est à 40°C, le faciès altéré, il se mobilise mal. La palpation réveille une douleur en L4-L5. Le reste de l''examen s''avère normal. La V.S. est à 100 mm à la première heure, les globules blancs sont à 18 000 dont 80 % de Polynucléaires Ionogrammes sanguin et urinaire sont normaux.', false, true, 'Les examens apportent peu de renseignements. Quel examen complémentaire allez-vous prescrire pour confirmer votre diagnostic ?', '[{"l":"A","t":"Echotomographie","c":false},{"l":"B","t":"Exploration tomodensitométrique","c":false},{"l":"C","t":"Scintigraphie au pyrophosphates marqués au TC99m","c":false},{"l":"D","t":"Ponction discale","c":true},{"l":"E","t":"Xéroradiographie","c":false}]'::jsonb, 'La scintigraphie révélera un foyer d''hyperfixation et le scanner pourra montrer les images de spondylodiscite et d''abcès des parties molles. La ponction discale a l''avantage de pouvoir ramener le germe.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2411, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Monsieur A..., 60 ans, est hospitalisé pour des lombalgies invalidantes depuis 15 jours, et résistantes aux antalgiques habituels. Il y a deux mois, il a subi deux cystoscopie pour une hématurie. Un polype a été enlevé et l''examen histologique a conclu à sa bénignité. Une U.I.V. élimine toute cause rénale. Quelques jours après la seconde exploration endoscopique, monsieur A... a présenté des frissons, un accès fébrile à 38°C, régressif sous antiseptique urinaire. Lors de son hospitalisation, la température est à 40°C, le faciès altéré, il se mobilise mal. La palpation réveille une douleur en L4-L5. Le reste de l''examen s''avère normal. La V.S. est à 100 mm à la première heure, les globules blancs sont à 18 000 dont 80 % de Polynucléaires Ionogrammes sanguin et urinaire sont normaux.', false, true, 'Pendant la période diagnostique, on doit proposer au malade :', '[{"l":"A","t":"Un repos strict au lit","c":true},{"l":"B","t":"L''entretien de la trophicité des membres par une rééducation appropriée","c":true},{"l":"C","t":"Un plâtre","c":false},{"l":"D","t":"Une coquille plâtrée","c":true},{"l":"E","t":"L''obligation de marcher","c":false}]'::jsonb, 'Avec une prévention de la maladie thromboembolique.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2412, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une femme de 65 ans active, présente à la suite d''une chute de mobylette, une fracture cervicale vraie du fémur dont le trait est oblique en bas et en dedans. Le déplacement ouvre l''angle cervico-céphalique (20°). De profil, le déplacement est pratiquement nul. Il n''y a pas d''arthrose associée. L''impotence fonctionnelle est d''ailleurs modérée et permet à cette femme de décoller le talon du lit. La marche cependant est très douloureuse. L''état général de la blessée est bon et permet une anesthésie générale de longue durée.', false, true, 'Il s''agit d''une fracture :', '[{"l":"A","t":"Garden I Pauwels I","c":true},{"l":"B","t":"Garden I Pauwels II","c":false},{"l":"C","t":"Garden II Pauwels I","c":false},{"l":"D","t":"Garden II Pauwels II","c":false},{"l":"E","t":"Garden III Pauwels III","c":false}]'::jsonb, 'Il s''agit d''une fracture engrenée en coxa valga donc de type Garden I et Pauwels I. La classification de Pauwels I envisage 3 groupes de gravité croissante en fonction de l''obliquité du trait par rapport à l''horizontale.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2413, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 65 ans active, présente à la suite d''une chute de mobylette, une fracture cervicale vraie du fémur dont le trait est oblique en bas et en dedans. Le déplacement ouvre l''angle cervico-céphalique (20°). De profil, le déplacement est pratiquement nul. Il n''y a pas d''arthrose associée. L''impotence fonctionnelle est d''ailleurs modérée et permet à cette femme de décoller le talon du lit. La marche cependant est très douloureuse. L''état général de la blessée est bon et permet une anesthésie générale de longue durée.', false, true, 'Cette fracture est d''un bon pronostic :', '[{"l":"A","t":"Car elle est stable","c":true},{"l":"B","t":"Car elle prédispose a la consolidation","c":true},{"l":"C","t":"Car elle ne se complique habituellement pas de nécrose","c":false},{"l":"D","t":"Car la réduction est facile sur table orthopédique","c":false},{"l":"E","t":"Car elle survient chez une femme en bon état général","c":true}]'::jsonb, 'Il s''agit d''une fracture stable qui consolide toujours après enclouage ou vissage ; il existe cependant un risque de nécrose secondaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2414, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Une femme de 65 ans active, présente à la suite d''une chute de mobylette, une fracture cervicale vraie du fémur dont le trait est oblique en bas et en dedans. Le déplacement ouvre l''angle cervico-céphalique (20°). De profil, le déplacement est pratiquement nul. Il n''y a pas d''arthrose associée. L''impotence fonctionnelle est d''ailleurs modérée et permet à cette femme de décoller le talon du lit. La marche cependant est très douloureuse. L''état général de la blessée est bon et permet une anesthésie générale de longue durée.', false, true, 'La fracture de cette blessée pourrait faire l''objet :', '[{"l":"A","t":"D''une ostéosynthèse en place par vis","c":true},{"l":"B","t":"D''une ostéosynthèse après réduction par vis","c":false},{"l":"C","t":"D''une arthroplastie d''emblée","c":false},{"l":"D","t":"D''une abstention thérapeutique sans autoriser l''appui avec surveillance radiologique régulière","c":false},{"l":"E","t":"D''une ostéosynthèse en place par clous de Ender","c":false}]'::jsonb, 'QCM discutable. Le repos au lit simple peut être envisagé mais il existe un risque de déplacement secondaire, l''intervention est donc indiquée d''autant qu''elle permet une reprise de l''appui : vissage en triangulation, enclouage type Smith-Petersen.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2415, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Une femme de 65 ans active, présente à la suite d''une chute de mobylette, une fracture cervicale vraie du fémur dont le trait est oblique en bas et en dedans. Le déplacement ouvre l''angle cervico-céphalique (20°). De profil, le déplacement est pratiquement nul. Il n''y a pas d''arthrose associée. L''impotence fonctionnelle est d''ailleurs modérée et permet à cette femme de décoller le talon du lit. La marche cependant est très douloureuse. L''état général de la blessée est bon et permet une anesthésie générale de longue durée.', false, true, 'Dans l''hypothèse de la survenue d''une nécrose aseptique de la tête fémorale fonctionnellement très gênante :', '[{"l":"A","t":"Il faut réaliser une arthroplastie par prothèse totale","c":true},{"l":"B","t":"Il faut réaliser une ostéotomie de Stewart","c":false},{"l":"C","t":"Il faut réaliser une résection tête et col","c":false},{"l":"D","t":"Il faut réaliser une simple ablation du matériel et attendre l''évolution","c":false},{"l":"E","t":"Il faut attendre la consolidation de la fracture et surveiller l''évolution","c":false}]'::jsonb, 'A partir de 65 ans, il vaut mieux rendre le plus rapidement poss ble son autonomie à cette patiente.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2416, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions :', false, true, 'Au niveau du pouce, vous constatez une plaie palmaire en regard de l''articulation métacarpo-phalangienne avec une perte de la flexion de P2 sur P1. Vous pensez à une section :', '[{"l":"A","t":"Du rameau thénarien du médian","c":false},{"l":"B","t":"Du court fléchisseur du pouce","c":false},{"l":"C","t":"Du fléchisseur superficiel du pouce","c":false},{"l":"D","t":"Du long fléchisseur propre du pouce","c":true},{"l":"E","t":"Du premier interosseux palmaire","c":false}]'::jsonb, 'Le déficit de la flexion active de P2 sur P1 du pouce correspond à une lésion ou une section du long fléchisseur propre du pouce.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2417, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions :', false, true, 'Il y a une plaie en regard de la face palmaire P2. Le médius a gardé une flexion active de P2 sur P1 mais a perdu celle de P3 sur P2. Vous évoquez une section :', '[{"l":"A","t":"Du fléchisseur superficiel du médius","c":false},{"l":"B","t":"Du fléchisseur profond du médius","c":true},{"l":"C","t":"Des deux tendons fléchisseurs du médius","c":false},{"l":"D","t":"Des interosseux et lombricaux du médius","c":false},{"l":"E","t":"Des nerfs collatéraux","c":false}]'::jsonb, 'La décussation du fléchisseur profond à travers les deux bandelettes du fléchisseur superficiel se fait en regard de la métacarpophalangienne et de la première phalange.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2418, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions :', false, true, 'L''annulaire a été sectionné par le coup de scie au niveau de P2. Pour envisager une réimplantation par microchirurgie, il faut :', '[{"l":"A","t":"Un délai écoulé de moins d''une heure","c":false},{"l":"B","t":"Un conditionnement du doigt dans un bain de sérum glacé","c":false},{"l":"C","t":"Un conditionnement dans un sachet isolant et de la glace","c":true},{"l":"D","t":"Une section franche","c":true},{"l":"E","t":"La possibilité de réparer au moins une veine","c":true}]'::jsonb, 'Sans commentaire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2419, 15, 'Traumatologie', 'Main', 'Un menuisier de 25 ans, droitier, fait une fausse manoeuvre et est blessé à la main droite par une scie circulaire. Vous êtes de garde et vous faites un premier bilan des lésions :', false, true, 'Une radiographie montre que le trapèze présente une fracture comminutive. Vous prévoyez des conséquences sur :', '[{"l":"A","t":"La stabilité du deuxième métacarpien","c":true},{"l":"B","t":"L''ouverture de la première commissure","c":true},{"l":"C","t":"La pince pouce-index","c":true},{"l":"D","t":"L''inclinaison radiale de la main","c":false},{"l":"E","t":"La flexion de la métacarpo-phalangienne du pouce","c":false}]'::jsonb, 'Le trapèze s''articule avec le premier et le deuxième métacarpe retentissant ainsi sur tous les mouvements des deux premiers doigts.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2420, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 28 ans souffre depuis huit jours de douleurs polyarticulaires avec céphalées, asthénie, fièvre à 38°C. L''examen montre un gonflement douloureux du genou gauche et une éruption morbilliforme fugace apparaissant le soir à l''acmé de la fièvre.', false, true, 'Si vous envisagez le diagnostic de F.L.R. (Fiessinger-Leroy-Reiter) vous retiendrez en sa faveur :', '[{"l":"A","t":"L''éruption","c":false},{"l":"B","t":"L''apparition d''une conjonctivite","c":true},{"l":"C","t":"La découverte d''une splénomégalie","c":false},{"l":"D","t":"La découverte d''adénopathies","c":false},{"l":"E","t":"La découverte d''une balanite","c":true}]'::jsonb, 'Les lésions cutanéomuqueuses sont plus inconstantes que les manifestations articulaires, urogénitales, digestives ou oculaires mais elles sont de bonne valeur sémiologique : balanite, macules ou érosions du scrotum, plaques érythémateuses gingivales, papule ou pustule cutanée évoluant vers le "clou de tapisserie" et enfin éruption psoriasiforme.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2421, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 28 ans souffre depuis huit jours de douleurs polyarticulaires avec céphalées, asthénie, fièvre à 38°C. L''examen montre un gonflement douloureux du genou gauche et une éruption morbilliforme fugace apparaissant le soir à l''acmé de la fièvre.', false, true, 'Si vous envisagez le diagnostic de syndrome de Lِfgren (dans le cadre d''une sarcoïdose), vous retiendrez en sa faveur :', '[{"l":"A","t":"L''éruption vespérale","c":false},{"l":"B","t":"La découverte de nodosités des membres inférieurs","c":true},{"l":"C","t":"La découverte d''une opacité pulmonaire segmentaire","c":false},{"l":"D","t":"La découverte d''un ganglion hilaire","c":true},{"l":"E","t":"La découverte d''un frottement péricardique","c":false}]'::jsonb, 'Les péricardites sarcoïdosiques sont exceptionnelles. L''érythème noueux est très évocateur en cas d''arthralgies et doit faire demander systématiquement une radiographie de thorax à la recherche d''adénopathies hilaires bilatérales et non compressives. L''infiltrat réticulomicronodulaire est disséminé et rarement localisé.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2422, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 28 ans souffre depuis huit jours de douleurs polyarticulaires avec céphalées, asthénie, fièvre à 38°C. L''examen montre un gonflement douloureux du genou gauche et une éruption morbilliforme fugace apparaissant le soir à l''acmé de la fièvre.', false, true, 'Si vous envisagez le diagnostic de rhumatisme gonococcique vous retiendrez en sa faveur :', '[{"l":"A","t":"L''eruption morbilliforme du soir","c":false},{"l":"B","t":"L''apparition de pustules à centre hémorragique du tronc","c":true},{"l":"C","t":"L''apparition d''une kératose palmoplantaire","c":false},{"l":"D","t":"La constatation de placards érythrosquameux des coudes","c":false},{"l":"E","t":"L''apparition d''une urticaire","c":false}]'::jsonb, 'Un rhumatisme avec des ténosynovites profuses et une pustule à centre nécrotique est gonococcique jusqu''à preuve du contraire.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(2423, 21, 'Rhumatologie', 'Arthrite septique', 'Un homme de 28 ans souffre depuis huit jours de douleurs polyarticulaires avec céphalées, asthénie, fièvre à 38°C. L''examen montre un gonflement douloureux du genou gauche et une éruption morbilliforme fugace apparaissant le soir à l''acmé de la fièvre.', false, true, 'Si vous envisagez le diagnostic de RAA vous retiendrez en sa faveur :', '[{"l":"A","t":"L''éruption vespérale","c":false},{"l":"B","t":"L''apparition d''adénopathie","c":false},{"l":"C","t":"L''apparition d''un frottement péricardique","c":true},{"l":"D","t":"L''apparition d''une splénomégalie","c":false},{"l":"E","t":"L''apparition d''une iritis","c":false}]'::jsonb, 'Le RAA est beaucoup moins fréquent chez l''adulte que les autres pathologies. Seuls les critères majeurs de Jones doivent être retenus : polyarthrite migratrice, cardite, nodosités de Meynet, érythème marginé et dore. Il faut surtout éliminer une cardite lupique et une maladie de Osler.', '["Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb);
